// ================= CORE (v2) =================
"use strict";
MEDVOCAB.forEach(v=>VOCAB.push(v));ALLTAGVOCAB.forEach(v=>VOCAB.push(v));MEDL2.forEach(m=>MEDL.push(m));
const $=(s,r)=>(r||document).querySelector(s), $$=(s,r)=>[...(r||document).querySelectorAll(s)];
const esc=s=>String(s==null?"":s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const pad=n=>String(n).padStart(2,"0");
const keyOf=d=>d.getFullYear()+"-"+pad(d.getMonth()+1)+"-"+pad(d.getDate());
const todayKey=()=>keyOf(new Date());
const fmtDate=k=>{if(!k)return "";const [y,m,d]=k.split("-");return d+"/"+m+"/"+y};
const addDays=(k,n)=>{const [y,m,d]=k.split("-").map(Number);return keyOf(new Date(y,m-1,d+n))};
const diffDays=(a,b)=>{const [y1,m1,d1]=a.split("-").map(Number),[y2,m2,d2]=b.split("-").map(Number);return Math.round((new Date(y2,m2-1,d2)-new Date(y1,m1-1,d1))/864e5)};
const shuffle=a=>{a=a.slice();for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a};
const clamp=(x,a,b)=>Math.max(a,Math.min(b,x));
let TOTAL_DAYS=182;
// ---------- toast & errors
let toastT=null;
function toast(msg,ms){const t=$("#toast");if(!t)return;t.textContent=msg;t.classList.add("show");clearTimeout(toastT);toastT=setTimeout(()=>t.classList.remove("show"),ms||2000)}
function logError(e){try{const m=String(e&&(e.message||e.reason&&e.reason.message)||e).slice(0,300);S.errlog=(S.errlog||[]).slice(-9);S.errlog.push({at:new Date().toISOString(),m});saveSoon()}catch(x){}}
window.addEventListener("error",e=>logError(e.error||e.message));
window.addEventListener("unhandledrejection",e=>logError(e.reason));
// ---------- catalog
const DOC=/^(Arzt|Du|Oberarzt|Oberärztin|Chirurg|Chefarzt)$/;
const CATALOG=new Map();
function addCard(c){if(!CATALOG.has(c.id))CATALOG.set(c.id,c)}
VOCAB.forEach(v=>addCard({id:"w:"+v[0],de:v[0],en:v[1],type:v[2],ex:v[3],tag:v[4],kind:"word"}));
const CHUNKS_BY_LESSON={};
MEDL.concat(ALLTAG).forEach(L=>{(L.dialog||[]).forEach((d,i)=>{if(!DOC.test(d[0]))return;const words=d[1].split(/\s+/).length;if(words>16||words<3)return;const c={id:"s:"+L.id+":"+i,de:d[1],en:d[2],ex:"",tag:"satz",kind:"satz",lesson:L.id};addCard(c);(CHUNKS_BY_LESSON[L.id]=CHUNKS_BY_LESSON[L.id]||[]).push(c.id)})});
function customCards(){return (S.custom||[]).map((c,i)=>({id:"c:"+i,de:c.de,en:c.en,ex:c.ex||"",info:c.info||"",tag:c.tag||"custom",kind:"custom"}))}
function card(id){if(id.startsWith("c:")){const i=+id.slice(2);const c=(S.custom||[])[i];return c?{id,de:c.de,en:c.en,ex:c.ex||"",tag:c.tag||"custom",kind:"custom"}:null}return CATALOG.get(id)||null}
function allCards(){return [...CATALOG.values()].concat(customCards())}
const DICT={};
function buildDict(){for(const k in DICT)delete DICT[k];allCards().forEach(c=>{if(c.kind==="satz")return;const k=c.de.replace(/^(der|die|das) /,"").toLowerCase();if(!DICT[k])DICT[k]=c})}
function genderOf(de){const m=/^(der|die|das) /.exec(de);return m?m[1]:null}
function deHTML(de){const g=genderOf(de);return g?`<span class="g-${g}">${g}</span> ${esc(de.slice(g.length+1))}`:esc(de)}
// ---------- state
const DEF={v:2,startDate:todayKey(),focus:"klinik",minutes:60,newPerDay:15,maxReviews:150,ttsRate:.95,autoplay:true,hints:true,theme:"system",motion:true,
  cards:{},custom:[],unlocked:{},newToday:{date:"",n:0,p:0},lessons:{},read:{},kultur:{},log:{},today:null,errors:{},mistakes:[],corrections:[],sims:[],fsp:[],onboarded:false,weekSeen:0,errlog:[],events:[],haptic:true,sound:false,restDays:true,shifts:{},blitzBest:0,lastBackup:"",coachDismiss:{},appHint:0,lit:{},kino:{},examRes:[],examSeen:{},examRot:{},examTarget:"goethe",look:"auto",pxt:"orange",textSize:100,exams:{goethe:"",fsp:""},gram:{},hoeren:{},readQ:{},holdMode:"app",google:{},citrusPlan:null,savedAt:""};
const LS_KEY="mephisto",SNAP_KEY="mephisto_snap";
let STORAGE_OK=true;
function lsGet(k){try{return localStorage.getItem(k)}catch(e){STORAGE_OK=false;return null}}
function lsSet(k,v){try{localStorage.setItem(k,v);return true}catch(e){STORAGE_OK=false;return false}}
function fresh(){return JSON.parse(JSON.stringify(DEF))}
function migrateV1(o){const n=fresh();const today=todayKey();
  ["startDate","minutes","newPerDay","onboarded"].forEach(k=>{if(o[k]!=null)n[k]=o[k]});
  n.focus=LEGACY_PATH[o.pathway]||"klinik";if(o.dir==="en")n.prodFirst=true;
  n.custom=Array.isArray(o.custom)?o.custom.filter(c=>c&&c.de&&c.en):[];
  Object.entries(o.cards||{}).forEach(([k,st])=>{if(!st||typeof st!=="object")return;let id=null;if(/^v\d+$/.test(k)){const v=VOCAB[+k.slice(1)];if(v)id="w:"+v[0]}else if(/^c\d+$/.test(k))id="c:"+k.slice(1);if(!id)return;const prev=n.cards[id];const s={ease:+st.ease||2.5,int:+st.int||0,reps:+st.reps||0,lapses:+st.lapses||0,due:/^\d{4}-\d\d-\d\d$/.test(st.due)?st.due:today};if(!prev||s.int>prev.int)n.cards[id]=s});
  const les=(src)=>Object.entries(src||{}).forEach(([id,sc])=>{if(typeof sc!=="number")return;const int=sc<60?1:sc<80?3:14;n.lessons[id]={best:sc,last:today,n:1,int,due:addDays(today,int)};(CHUNKS_BY_LESSON[id]||[]).forEach(c=>n.unlocked[c]=1)});
  les(o.gram);les(o.med);les(o.alltag);
  Object.keys(o.read||{}).forEach(id=>n.read[id]=true);Object.keys(o.faust||{}).forEach(id=>n.read[id]=true);
  Object.keys(o.kultur||{}).forEach(i=>n.kultur[i]=true);
  Object.entries(o.done||{}).forEach(([d,v])=>{if(v&&Object.values(v).some(Boolean))n.log[d]={act:1}});
  if(o.errors&&typeof o.errors==="object")n.errors=o.errors;
  ["corrections","sims","fsp"].forEach(k=>{if(Array.isArray(o[k]))n[k]=o[k].slice(-100)});
  if(Array.isArray(o.mistakeCards))n.mistakes=o.mistakeCards.slice(-300);
  return n}
function validate(o){const n=Object.assign(fresh(),o);
  if(!FOCUS[n.focus]&&n.focus!=="zertifikat")n.focus="klinik";if(!/^\d{4}-\d\d-\d\d$/.test(n.startDate))n.startDate=todayKey();
  n.minutes=clamp(+n.minutes||60,15,180);n.newPerDay=clamp(+n.newPerDay||15,0,60);n.maxReviews=clamp(+n.maxReviews||150,20,500);n.ttsRate=clamp(+n.ttsRate||.95,.6,1.3);
  ["cards","unlocked","lessons","read","kultur","log","errors","lit","kino","examSeen","examRot","shifts","coachDismiss","exams","gram","hoeren","readQ"].forEach(k=>{if(!n[k]||typeof n[k]!=="object"||Array.isArray(n[k]))n[k]={}});
  ["custom","mistakes","corrections","sims","fsp","errlog","examRes","events"].forEach(k=>{if(!Array.isArray(n[k]))n[k]=[]});
  if(!n.newToday||typeof n.newToday!=="object")n.newToday={date:"",n:0,p:0};
  if(n.today&&(!Array.isArray(n.today.steps)||typeof n.today.idx!=="number"))n.today=null;
  return n}
let LOAD_NOTE="";
function load(){const raw=lsGet(LS_KEY);if(!raw)return fresh();
  try{const o=JSON.parse(raw);if(!o||typeof o!=="object")throw new Error("not an object");if(o.v===2)return validate(o);const m=validate(migrateV1(o));LOAD_NOTE="Dein Fortschritt wurde auf die neue Version übertragen.";lsSet("mephisto_v1_backup",raw);return m}
  catch(e){lsSet("mephisto_corrupt",raw);LOAD_NOTE="Gespeicherte Daten waren beschädigt. Eine Kopie liegt unter „Daten → Schnappschüsse“.";return fresh()}}
let S=load();
let saveT=null;
function saveNow(){clearTimeout(saveT);saveT=null;if(!lsSet(LS_KEY,JSON.stringify(S)))showStorageWarning()}
function saveSoon(){clearTimeout(saveT);saveT=setTimeout(saveNow,250)}
document.addEventListener("visibilitychange",()=>{if(document.visibilityState==="hidden"&&saveT)saveNow()});
window.addEventListener("pagehide",()=>{if(saveT)saveNow()});
let storageWarned=false;
function showStorageWarning(){if(storageWarned)return;storageWarned=true;toast("Speichern nicht möglich (privates Fenster?). Sichere deinen Fortschritt unter Ich → Daten.",6000)}
function snapshot(){const d=todayKey();let snaps={};try{snaps=JSON.parse(lsGet(SNAP_KEY)||"{}")||{}}catch(e){snaps={}}if(snaps[d])return;snaps[d]=JSON.stringify(S);const keys=Object.keys(snaps).sort();while(keys.length>3)delete snaps[keys.shift()];lsSet(SNAP_KEY,JSON.stringify(snaps))}
function snapshots(){try{return JSON.parse(lsGet(SNAP_KEY)||"{}")||{}}catch(e){return {}}}
// ---------- time in the plan
const dayNumber=()=>Math.max(1,diffDays(S.startDate,todayKey())+1);
let weekNumber=()=>clamp(Math.ceil(dayNumber()/7),1,WEEKS.length);
const weekDay=()=>((dayNumber()-1)%7)+1;
const WEEK=()=>WEEKS[weekNumber()-1];
// ---------- daily log
function logDay(field,n){const d=todayKey();const L=S.log[d]=S.log[d]||{};L[field]=(L[field]||0)+(n==null?1:n);L.act=1;saveSoon()}
// one line per meaningful thing you did, newest last (kept: 600)
function logEvent(type,text,val){const d=new Date();S.events=(S.events||[]).concat([{d:todayKey(),t:pad(d.getHours())+":"+pad(d.getMinutes()),type,text:String(text||"").slice(0,140),val:val==null?null:val}]).slice(-600);saveSoon()}
// active study time: counted while a session or tool is open and the app is visible (idle gaps over 3 min are not counted)
let STUDY={on:false,last:0};
function studyTick(){if(!STUDY.on||document.visibilityState!=="visible")return;const now=Date.now();const dt=now-STUDY.last;STUDY.last=now;if(dt>0&&dt<180000){const d=todayKey();const L=S.log[d]=S.log[d]||{};L.sec=(L.sec||0)+Math.round(dt/1000);if(L.sec>=300&&!L.act){L.act=1;if(typeof logEvent==="function")logEvent("time","5 Minuten gelernt: Tag zählt")}saveSoon()}}
function studyStart(){STUDY.on=true;STUDY.last=Date.now()}
function studyStop(){studyTick();STUDY.on=false}
setInterval(studyTick,15000);
["pointerdown","keydown"].forEach(n=>document.addEventListener(n,()=>{if(STUDY.on)studyTick()},{passive:true,capture:true}));
document.addEventListener("visibilitychange",()=>{if(document.visibilityState==="visible")STUDY.last=Date.now();else studyTick()});
const minutesOn=k=>{const L=S.log[k];return L?Math.round((L.sec||0)/60)+(L.min||0):0};
function streak(){let n=0,k=todayKey();const has=x=>S.log[x]&&S.log[x].act;if(!has(k))k=addDays(k,-1);while(has(k)){n++;k=addDays(k,-1)}return n}
function retention(){let r=0,o=0;Object.entries(S.log).forEach(([d,L])=>{if(diffDays(d,todayKey())<=30){r+=L.mrev||0;o+=L.mok||0}});return r>=10?Math.round(100*o/r):null}
// ---------- scheduler (SM-2 family with in-session relearning)
const newState=()=>({ease:2.5,int:0,reps:0,lapses:0,due:todayKey()});
function previewInt(key,q){const c=S.cards[key]||newState();if(q===0)return 0;if(c.reps===0)return q===3?4:1;if(c.reps===1)return q===1?2:q===2?3:7;return Math.min(365,Math.max(c.int+1,Math.round(c.int*(q===1?1.2:q===2?c.ease:c.ease*1.3))))}
function rate(key,q){const t=todayKey();const c=S.cards[key]?Object.assign({},S.cards[key]):newState();const mature=c.int>=21;
  if(q===0){if(c.reps>0)c.lapses++;c.reps=0;c.int=0;c.ease=Math.max(1.3,c.ease-.2);c.due=t}
  else{let i=previewInt(key,q);if(i>4)i=Math.round(i*(0.95+Math.random()*0.1));c.int=i;c.ease=clamp(c.ease+(q===1?-.15:q===3?.15:0),1.3,3);c.reps++;c.due=addDays(t,i)}
  S.cards[key]=c;logDay("rev");if(q>=2)logDay("ok",1);if(mature){logDay("mrev");if(q>=2)logDay("mok")}saveSoon()}
function isDue(key){const c=S.cards[key];return c&&c.due<=todayKey()}
function resetNewToday(){if(S.newToday.date!==todayKey())S.newToday={date:todayKey(),n:0,p:0}}
function introducedNew(isProd){resetNewToday();if(isProd)S.newToday.p++;else S.newToday.n++;logDay("new");saveSoon()}
function newPool(tag){resetNewToday();const left=Math.max(0,S.newPerDay-S.newToday.n);if(!left)return [];
  let pool=allCards().filter(c=>!S.cards[c.id]&&(c.kind!=="satz"||S.unlocked[c.id]));
  if(tag)return pool.filter(c=>c.tag===tag).slice(0,left);
  const chunks=pool.filter(c=>c.kind==="satz").slice(0,Math.ceil(left/2));
  const ord=FOCUS[S.focus].newOrder;const rest=pool.filter(c=>c.kind!=="satz").sort((a,b)=>{const ia=ord.indexOf(a.tag),ib=ord.indexOf(b.tag);return (ia<0?9:ia)-(ib<0?9:ib)});
  return chunks.concat(rest).slice(0,left)}
function prodPool(){resetNewToday();const left=Math.max(0,5-S.newToday.p);if(!left)return [];return Object.keys(S.cards).filter(k=>!k.startsWith("p:")&&S.cards[k].int>=4&&!S.cards["p:"+k]&&card(k)).slice(0,left)}
function dueKeys(){const t=todayKey();return Object.keys(S.cards).filter(k=>S.cards[k].due<=t&&card(k.replace(/^p:/,""))).sort((a,b)=>S.cards[a].due<S.cards[b].due?-1:1)}
function buildQueue(opt){opt=opt||{};const q=[];
  if(opt.due!==false){dueKeys().slice(0,S.maxReviews).forEach(k=>{const p=k.startsWith("p:");q.push({key:k,id:p?k.slice(2):k,mode:p?"prod":"rec"})})}
  const add=[];if(opt.new!==false){newPool(opt.tag).forEach(c=>add.push({key:c.id,id:c.id,mode:"rec",isNew:true}));if(!opt.tag)prodPool().forEach(k=>add.push({key:"p:"+k,id:k,mode:"prod",isNew:true,isProd:true}))}
  const rev=shuffle(q);const out=[];let ai=0;rev.forEach((x,i)=>{out.push(x);if(i%3===2&&ai<add.length)out.push(add[ai++])});while(ai<add.length)out.push(add[ai++]);return out}
function mastered(){return Object.keys(S.cards).filter(k=>!k.startsWith("p:")&&S.cards[k].int>=21).length}
function knownWords(){return Object.keys(S.cards).filter(k=>!k.startsWith("p:")&&S.cards[k].reps>0).length}
// ---------- lessons with spaced re-review (score <60 → 1 d, <80 → 3 d, else 14 d then ×2.5)
function lessonById(id){return MEDL.find(l=>l.id===id)||ALLTAG.find(l=>l.id===id)||GRAMMAR.find(l=>l.id===id)||null}
function lessonKind(id){return id[0]==="m"?"klinik":id[0]==="a"?"alltag":"grammatik"}
function completeLesson(id,score){const t=todayKey();const L=Object.assign({best:0,n:0,int:0},S.lessons[id]||{});L.best=Math.max(L.best,score);L.lastScore=score;L.last=t;L.n++;L.int=score<60?1:score<80?3:(L.int>=14?Math.min(180,Math.round(L.int*2.5)):14);L.due=addDays(t,L.int);S.lessons[id]=L;
  (CHUNKS_BY_LESSON[id]||[]).forEach(c=>S.unlocked[c]=1);logDay("les");const LL=lessonById(id);logEvent("lesson",(LL?LL.title:id)+" · Quiz "+score+" %",score);saveSoon()}
function lessonsDue(){const t=todayKey();return Object.entries(S.lessons).filter(([id,L])=>L.due<=t&&lessonById(id)).map(([id])=>id)}
// ---------- errors & mistakes
function addErrors(list,src){(list||[]).forEach(e=>{const ty=ERR_TYPES.includes(e.type)?e.type:"Sonstiges";S.errors[ty]=(S.errors[ty]||0)+1;if(e.original&&e.fix&&String(e.fix).length<90){S.mistakes.push({type:ty,text:"{{c1::"+e.fix+"}} (nicht: "+e.original+")",extra:e.why||"",date:todayKey(),src:src||""})}});if(S.mistakes.length>300)S.mistakes=S.mistakes.slice(-300);saveSoon()}
// ---------- typed answers
const normT=s=>String(s||"").toLowerCase().replace(/ß/g,"ss").replace(/ä/g,"ae").replace(/ö/g,"oe").replace(/ü/g,"ue").replace(/[.,!?;:„"“”‚‘’'()«»–—-]/g," ").replace(/\s+/g," ").trim();
function lev(a,b){if(a===b)return 0;const m=a.length,n=b.length;if(!m)return n;if(!n)return m;let prev=Array.from({length:n+1},(_,j)=>j);for(let i=1;i<=m;i++){const cur=[i];for(let j=1;j<=n;j++)cur[j]=Math.min(prev[j]+1,cur[j-1]+1,prev[j-1]+(a[i-1]===b[j-1]?0:1));prev=cur}return prev[n]}
function similarity(a,b){a=normT(a);b=normT(b);if(!a&&!b)return 1;return 1-lev(a,b)/Math.max(a.length,b.length)}
function wordDiff(got,want){const A=String(got||"").trim().split(/\s+/).filter(Boolean),B=String(want||"").trim().split(/\s+/).filter(Boolean);const a=A.map(normT),b=B.map(normT);const m=a.length,n=b.length;const L=Array.from({length:m+1},()=>new Array(n+1).fill(0));for(let i=m-1;i>=0;i--)for(let j=n-1;j>=0;j--)L[i][j]=a[i]===b[j]?1+L[i+1][j+1]:Math.max(L[i+1][j],L[i][j+1]);
  const out=[];let i=0,j=0;while(i<m&&j<n){if(a[i]===b[j]){out.push(`<span class="d-ok">${esc(B[j])}</span>`);i++;j++}else if(L[i+1][j]>=L[i][j+1]){out.push(`<span class="d-del">${esc(A[i])}</span>`);i++}else{out.push(`<span class="d-ins">${esc(B[j])}</span>`);j++}}while(i<m)out.push(`<span class="d-del">${esc(A[i++])}</span>`);while(j<n)out.push(`<span class="d-ins">${esc(B[j++])}</span>`);return out.join(" ")}
// spelling that normT forgives (capitals, ß, umlauts) is still shown to the learner; from B1 it costs the "Richtig" on cards
function spellNote(got,wants){try{const x=s=>String(s||"").replace(/[.,!?;:„"“”‚‘’'()«»–—]/g," ").replace(/\s+/g," ").trim();const g=x(got);const w=(wants||[]).filter(Boolean).find(v=>normT(v)===normT(got));if(!w||!g)return "";const ww=x(w);if(ww===g)return "";
  const why=[];if(ww.toLowerCase()!==g.toLowerCase()){if(/ß/.test(ww)!==/ß/.test(g))why.push("ß");if(/[äöüÄÖÜ]/.test(ww)&&!/[äöüÄÖÜ]/.test(g))why.push("Umlaute (ä, ö, ü)");if(/-/.test(ww)!==/-/.test(g)&&!why.length)why.push("Bindestrich")}
  const lw=ww.replace(/ß/g,"ss").replace(/ä/g,"ae").replace(/ö/g,"oe").replace(/ü/g,"ue").replace(/Ä/g,"Ae").replace(/Ö/g,"Oe").replace(/Ü/g,"Ue").replace(/-/g," "),lg=g.replace(/ß/g,"ss").replace(/ä/g,"ae").replace(/ö/g,"oe").replace(/ü/g,"ue").replace(/Ä/g,"Ae").replace(/Ö/g,"Oe").replace(/Ü/g,"Ue").replace(/-/g," ");
  if(lw!==lg&&lw.toLowerCase()===lg.toLowerCase())why.push("Groß- und Kleinschreibung");if(!why.length)return "";
  return ` <span class="spell-note">Rechtschreibung: <b>${esc(w)}</b> – achte auf ${why.join(" und ")}.</span>`}catch(e){return ""}}
function spellStrict(){try{if(S.strict===true)return true;if(S.strict===false)return false;return typeof learnerLv==="function"&&learnerLv()>=2}catch(e){return false}}
function gradeTyped(got,want){const g=normT(got),w=normT(want);if(!g)return {q:0,msg:"Keine Antwort."};if(g===w){const sn=spellNote(got,[want]);if(sn&&spellStrict())return {q:1,msg:"Fast richtig."+sn};return {q:2,msg:"Richtig."+sn}}
  const wg=genderOf(want);if(wg){const gm=/^(der|die|das|den|dem|des)\s+(.*)$/.exec(g);const wn=normT(want.slice(wg.length+1));if(gm&&gm[2]===wn&&gm[1]!==wg){addErrors([{type:"Artikel/Genus",original:gm[1]+" "+wn,fix:want,why:"Gender: "+wg}],"typed");return {q:0,msg:`Artikel: <b class="g-${wg}">${wg}</b>, nicht ${gm[1]}.`,art:true}}if(!gm&&g===wn)return {q:1,msg:`Fast: mit Artikel <b class="g-${wg}">${wg}</b>.`}}
  const s=similarity(got,want);if(s>=.88)return {q:1,msg:"Fast richtig. Kleiner Tippfehler."};return {q:0,msg:"Noch nicht."}}
// ---------- speech
const TTS_OK=typeof window!=="undefined"&&"speechSynthesis" in window&&typeof SpeechSynthesisUtterance!=="undefined";
let DE_VOICE=null;
function pickVoice(){try{const vs=speechSynthesis.getVoices();DE_VOICE=vs.find(v=>/^de(-|_)DE/i.test(v.lang))||vs.find(v=>/^de/i.test(v.lang))||null}catch(e){}}
if(TTS_OK){pickVoice();try{speechSynthesis.addEventListener("voiceschanged",pickVoice)}catch(e){}}
let ttsHinted=false;
function say(text,o){o=o||{};return new Promise(res=>{if(!TTS_OK){if(!o.silent&&!ttsHinted){ttsHinted=true;toast("Keine Sprachausgabe in dieser Ansicht. Öffne den Link in Safari oder Chrome.",4500)}return res(false)}
  try{speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(String(text).replace(/\s+/g," "));u.lang="de-DE";u.rate=(o.rate||S.ttsRate);if(DE_VOICE)u.voice=DE_VOICE;let done=false;const fin=()=>{if(!done){done=true;res(true)}};u.onend=fin;u.onerror=fin;setTimeout(fin,Math.max(2500,String(text).length*110/(u.rate||1)));speechSynthesis.speak(u)}catch(e){res(false)}})}
