// ===== Mephisto 13.1 · Module hooks. Loaded right after c_core.js.
// Rule: no file reassigns a shared global function any more. A module that adds to a screen registers a section:
//   MOD.after("viewHome","kompass",fn)   — fn(m,...args) runs after the base view and every earlier section, in load order.
// Each section runs in its own try/catch, so one broken module can no longer blank the whole screen.
// MOD.list() shows every hook and its sections.
const MOD=(function(){const H={};
  function install(name){if(H[name])return H[name];const base=window[name];if(typeof base!=="function")throw new Error("MOD: no function "+name);
    const h={base,after:[]};
    const disp=function(){const r=h.base.apply(this,arguments);for(const [tag,fn] of h.after){try{fn.apply(this,arguments)}catch(e){try{logError({message:"MOD "+name+"/"+tag+": "+(e&&e.message||e)})}catch(x){}console.error(e)}}return r};
    disp.__mod=name;window[name]=disp;H[name]=h;return h}
  return{
    after(name,tag,fn){install(name).after.push([tag,fn])},
    list(){const o={};Object.keys(H).forEach(k=>o[k]=H[k].after.map(a=>a[0]));return o},
    report(){return Object.entries(this.list()).map(([k,v])=>k+": "+v.join(" → ")).join("\n")}}})();

