function confetti(){const my=++CONF;if(!S.motion||matchMedia("(prefers-reduced-motion: reduce)").matches)return;const c=$("#confetti");const ctx=c.getContext("2d");const W=c.width=innerWidth,H=c.height=innerHeight;const cols=["#E2651C","#F59A4E","#2F64B5","#C23B3B","#2A8A55","#FFD08A"];const P=Array.from({length:110},()=>({x:W/2+(Math.random()-.5)*W*.3,y:H*.35,vx:(Math.random()-.5)*9,vy:-Math.random()*11-4,s:4+Math.random()*5,c:cols[Math.floor(Math.random()*cols.length)],r:Math.random()*6,vr:(Math.random()-.5)*.3}));let t=0;(function f(){ctx.clearRect(0,0,W,H);P.forEach(p=>{p.vy+=.32;p.x+=p.vx;p.y+=p.vy;p.r+=p.vr;ctx.save();ctx.translate(p.x,p.y);ctx.rotate(p.r);ctx.fillStyle=p.c;ctx.fillRect(-p.s/2,-p.s/3,p.s,p.s*.66);ctx.restore()});if(my!==CONF)return;if(++t<140)requestAnimationFrame(f);else ctx.clearRect(0,0,W,H)})()}
