// ---------- quiz
function quizRunner(el,qs,o){o=o||{};let i=0,right=0;const items=qs.map(q=>{const opts=q.o.map((t,k)=>({t,right:k===q.a}));return {q:q.q,opts:shuffle(opts),why:q.why}});
  function step(){if(i>=items.length){const sc=Math.round(100*right/items.length);el.innerHTML=`<div class="stack s fade-in"><div class="row between"><h3>Ergebnis</h3><span class="pill ${sc>=80?"good":sc>=60?"o":"bad"}">${sc} %</span></div><p class="muted">${right} von ${items.length} richtig. ${o.msg?o.msg(sc):sc>=80?"Sitzt. Nächste Wiederholung in zwei Wochen.":sc>=60?"Solide. Kommt in drei Tagen wieder.":"Kommt morgen wieder. Lies die Erklärungen oben noch einmal."}</p>${o.retry!==false?`<div class="row"><button class="sm qz-re">Nochmal</button></div>`:""}</div>`;const re=$(".qz-re",el);if(re)re.onclick=()=>{i=0;right=0;step()};KEYS=null;if(o.onDone)o.onDone(sc);return}
    const it=items[i];el.innerHTML=`<div class="q fade-in"><div class="eyebrow">Frage ${i+1} / ${items.length}</div><div class="stem">${esc(it.q)}</div><div class="opts">${it.opts.map((x,k)=>`<button data-k="${k}"><span class="k">${k+1}</span>${esc(x.t)}</button>`).join("")}</div><div class="qz-why"></div></div>`;
    const pick=k=>{if($(".qz-why",el).innerHTML)return;if(typeof fb==="function")fb(!!it.opts[k].right);const b=$$("[data-k]",el);b.forEach(x=>{x.disabled=true;if(it.opts[+x.dataset.k].right)x.classList.add("right")});if(it.opts[k].right)right++;else b[k].classList.add("wrong");$(".qz-why",el).innerHTML=`<div class="why">${esc(it.why)}</div><div class="row" style="margin-top:.7rem"><button class="primary qz-nx">Weiter <span class="kbd">↵</span></button></div>`;$(".qz-nx",el).onclick=()=>{i++;step()};KEYS=e=>{if(e.key==="Enter"){e.preventDefault();i++;step()}}};
    $$("[data-k]",el).forEach(b=>b.onclick=()=>pick(+b.dataset.k));KEYS=e=>{const n=+e.key;if(n>=1&&n<=it.opts.length)pick(n-1)}}
  step()}
// ---------- dialogue + lesson
function hideTr(){return weekNumber()>=6}
function dialogHTML(dialog){const gk=glossKey({});return `<div class="dl" data-gk="${gk}">${dialog.map(d=>{const me=/^(Arzt|Du|Ärztin)$/.test(d[0]);return `<div class="turn ${me?"me":""}"><div class="who"><span>${esc(d[0])}</span><button data-say="${esc(d[1])}" aria-label="Anhören">${ic("vol")}</button></div><div>${glossify(d[1])}</div><div class="tr" ${hideTr()?"hidden":""}>${esc(d[2])}</div></div>`}).join("")}</div>`}
function lessonView(el,L,o){o=o||{};const kind=lessonKind(L.id);const st=S.lessons[L.id];const chunks=(CHUNKS_BY_LESSON[L.id]||[]).length;const kn={klinik:"Klinik",alltag:"Alltag",grammatik:"Grammatik"}[kind];
  el.innerHTML=`<div class="head"><div class="row"><span class="pill ${kind}">${kn} · Woche ${L.week}</span>${st?`<span class="pill ${st.best>=80?"good":"o"}">${st.best} % · ${st.due<=todayKey()?"fällig":"nächste "+fmtDate(st.due)}</span>`:""}</div><h1>${esc(L.title)}</h1><p>${esc(L.sub)}</p></div>
  <div class="card prose">${L.body}</div>
  ${L.dialog&&L.dialog.length?`<div class="card stack s"><div class="row between"><h3>Dialog</h3><div class="row"><button class="sm ghost ls-tr">Übersetzung</button><button class="sm ls-all">${ic("play")} Alles</button></div></div>${dialogHTML(L.dialog)}${chunks?`<p class="muted ui" style="font-size:.85rem">${chunks} Sätze aus diesem Dialog werden nach dem Quiz als Satzkarten freigeschaltet.</p>`:""}</div>`:""}
  <div class="card ls-quiz"></div>
  ${o.session?"":`<div class="ls-write stack"></div>`}`;
  const tr=$(".ls-tr",el);if(tr)tr.onclick=()=>$$(".tr",el).forEach(x=>x.hidden=!x.hidden);
  const all=$(".ls-all",el);if(all)all.onclick=async()=>{for(const d of L.dialog){if(!document.body.contains(all))break;if(!(await say(d[1])))break}};
  const _lsDone=sc=>{completeLesson(L.id,sc);if(chunks)toast(chunks+" Satzkarten freigeschaltet");if(o.onDone)o.onDone(sc)};if(o.session&&L.ex&&L.ex.length&&typeof gramRunner==="function")gramRunner($(".ls-quiz",el),pickEx(L.ex,8),{pool:L.ex,retry:false,onDone:_lsDone});else quizRunner($(".ls-quiz",el),L.quiz,{retry:!o.session,onDone:_lsDone});
  if(!o.session&&L.dialog&&L.dialog.length){const w=$(".ls-write",el);lessonTasks(L).forEach(t=>{const box=document.createElement("div");box.className="card";w.appendChild(box);freeText(box,t)})}}
function lessonTasks(L){const kind=lessonKind(L.id);const out=[];const partners=L.dialog.map((d,i)=>[d,i]).filter(([d])=>!/^(Arzt|Du|Ärztin)$/.test(d[0]));const pick=[partners[0],partners[Math.floor(partners.length/2)]].filter((v,i,a)=>v&&a.indexOf(v)===i);
  pick.forEach(([d,i])=>{const nx=L.dialog[i+1];out.push({t:kind==="klinik"?"Antworte als Arzt":"Antworte",task:`<b>${esc(d[0])}:</b> „${esc(d[1])}“`,hint:"Schreib deine Antwort: zwei bis vier Sätze.",ctx:`Lektion „${L.title}“. ${d[0]} sagte: „${d[1]}“. ${kind==="klinik"?"Der Lernende antwortet als Arzt.":"Der Lernende antwortet natürlich, als er selbst."}`,reg:kind==="klinik"?"Arzt zu Patient: höflich, Sie, Laiensprache, keine Latinismen":"Alltag: höflich und natürlich",model:nx&&/^(Arzt|Du|Ärztin)$/.test(nx[0])?nx[1]:null,check:["Höfliche Anrede, passende Form (Sie/du)","Geht auf das Gesagte ein","Verb an zweiter Stelle bzw. am Ende im Nebensatz"]})});return out}
// ---------- reader (graded texts, Faust)
function readerView(el,item,o){o=o||{};const isF=!!item.lines;const gk=glossKey(item.gloss);const hide=isF?weekNumber()>=8:true;
  el.innerHTML=`<div class="head"><div class="row"><span class="pill ${isF?"literatur":"lesen"}">${isF?esc(item.scene)+" · "+esc(item.speaker):"Stufe "+item.level+" · Woche "+item.week}</span>${S.read[item.id]?'<span class="pill good">gelesen</span>':""}</div><h1>${esc(item.title)}</h1>${item.sub?`<p>${esc(item.sub)}</p>`:""}</div>
  <div class="row"><button class="sm rd-tr">Übersetzung</button><button class="sm rd-play">${ic("play")} Vorlesen</button><span class="muted ui" style="font-size:.82rem">Wort antippen: Bedeutung, Aussprache, ins Deck.</span></div>
  <div class="card"><div class="reader" data-gk="${gk}">${isF?item.lines.map(l=>l[0]==="— —"?`<div style="height:1rem"></div>`:`<span class="line">${glossify(l[0])}</span><div class="tr" ${hide?"hidden":""}>${esc(l[1])}</div>`).join(""):item.paras.map(p=>`<p class="para">${glossify(p.de)}</p><div class="tr" hidden>${esc(p.en)}</div>`).join("")}</div></div>
  ${isF?`<div class="tip">${esc(item.note)}</div>`:""}
  <div class="card row between"><div><b class="ui">Gelesen und verstanden?</b><div class="muted ui" style="font-size:.85rem">Erst ohne Übersetzung, dann prüfen.</div></div><button class="primary rd-done">${S.read[item.id]?ic("check")+" Gelesen":"Als gelesen markieren"}</button></div>`;
  $(".rd-tr",el).onclick=()=>$$(".tr",el).forEach(x=>x.hidden=!x.hidden);
  $(".rd-play",el).onclick=async()=>{const parts=isF?item.lines.filter(l=>l[0]!=="— —").map(l=>l[0]):item.paras.map(p=>p.de);for(const p of parts){if(!document.body.contains(el))break;if(!(await say(p)))break}};
  $(".rd-done",el).onclick=()=>{if(!S.read[item.id]){logDay("read");logEvent("read",(isF?"Literatur: ":"Text: ")+item.title)}S.read[item.id]=true;saveSoon();if(!o.onDone)toast("Gelesen");$(".rd-done",el).innerHTML=ic("check")+" Gelesen";if(o.onDone)o.onDone()}}
// ---------- tutor: correction + offline self-check
async function correct(text,ctx,reg){return SAMPLE.json(`Du bist ein erfahrener DaF-Lehrer mit medizinischem Hintergrund. ${LEARNER}
Aufgabe/Kontext: ${ctx}
Erwartetes Register: ${reg}
Der Lernende hat geschrieben:
«${text}»

Bewerte den Text. Korrekte alternative Formulierungen sind KEINE Fehler. Markiere nur echte Grammatik-, Wortwahl-, Register- und Rechtschreibfehler. Erklärungen kurz auf Englisch, mit der Regel. Wenn der Text die Aufgabe kommunikativ verfehlt, sag das in "note". Gib als Rückfrage-Übung ("followup") eine kurze neue Aufgabe, die den wichtigsten Fehler trainiert und den Lernenden selbst korrigieren lässt.
Antworte NUR mit JSON: {"ok":true|false,"corrected":"<minimal korrigiert>","natural":"<wie ein deutscher Arzt es natürlich sagen würde>","register_ok":true|false,"errors":[{"type":"<einer von: ${ERR_TYPES.join(", ")}>","original":"<fehlerhafte Stelle>","fix":"<Korrektur>","why":"<Regel, ein Satz, Englisch>"}],"note":"<ein Satz Feedback, Englisch>","followup":{"task":"<Lücken- oder Übersetzungssatz auf Deutsch>","answer":"<Lösung>"}}`,{modelTier:"default",cache:false})}
function freeText(el,t,o){o=o||{};
  el.innerHTML=`<div class="stack s"><div class="eyebrow">${esc(t.t||"Schreiben")} <span class="en">${SAMPLE?"corrected by Claude":"self-check against a model"}</span></div><div style="font-size:1.05rem">${t.task}</div>${t.hint?`<div class="muted ui" style="font-size:.88rem">${esc(t.hint)}</div>`:""}
   <textarea class="ft-in" spellcheck="false" placeholder="Schreib auf Deutsch…"></textarea>
   <div class="row"><button class="icon ft-mic need-sr" aria-label="Diktieren">${ic("mic")}</button><button class="primary ft-go">${SAMPLE?"Korrigieren":"Vergleichen"}</button><span class="muted ui ft-st" style="font-size:.88rem"></span></div><div class="ft-out"></div></div>`;
  const ftm=$(".ft-mic",el);if(ftm)ftm.onclick=()=>dictateInto(ftm,$(".ft-in",el));const inp=$(".ft-in",el),go=$(".ft-go",el),stEl=$(".ft-st",el),out=$(".ft-out",el);
  go.onclick=async()=>{const text=inp.value.trim();if(text.length<3)return toast("Erst etwas schreiben");
    if(!SAMPLE){selfCheck(out,text,t,o);return}
    go.disabled=true;stEl.textContent="Claude liest…";out.innerHTML="";
    try{const r=await correct(text,t.ctx,t.reg);stEl.textContent="";renderCorrection(out,text,r,t);addErrors(r.errors,"tutor");S.corrections.push({date:todayKey(),ok:!!r.ok,n:(r.errors||[]).length});if(S.corrections.length>150)S.corrections=S.corrections.slice(-150);logDay("write");logEvent("write",(t.t||"Schreiben")+" · "+((r.errors||[]).length?(r.errors||[]).length+" Fehler":"korrekt"));if(o.onDone)o.onDone({ok:!!r.ok})}
    catch(e){stEl.textContent="";out.innerHTML=`<p class="no">${esc(tutorMsg(e&&e.code))}</p>`;if(e&&(e.code==="not_granted"||e.code==="sampling_disabled")){SAMPLE=null;capsReady();selfCheck(out,text,t,o)}}finally{go.disabled=false}}}
function selfCheck(out,text,t,o){out.innerHTML=`<div class="stack s fade-in"><div class="card" style="background:var(--sunk)"><div class="eyebrow">Dein Text</div><div style="white-space:pre-wrap">${esc(text)}</div></div>
  ${t.model?`<div class="card tint"><div class="row between"><div class="eyebrow">Musterlösung</div><button class="icon ghost" data-say="${esc(t.model)}">${ic("vol")}</button></div><div style="white-space:pre-wrap">${esc(t.model)}</div></div>`:""}
  ${t.check?`<div class="card"><div class="eyebrow" style="margin-bottom:.5rem">Hast du das?</div><div class="check-list">${t.check.map((c,i)=>`<label class="row" style="gap:.6rem;flex-wrap:nowrap"><input type="checkbox" style="width:22px;min-height:22px;flex-shrink:0" data-c="${i}"> <span>${esc(c)}</span></label>`).join("")}</div></div>`:""}
  <div class="row"><span class="muted ui">Wie war's?</span><button class="sm sc-r" data-r="2">Gut</button><button class="sm sc-r" data-r="1">Teilweise</button><button class="sm sc-r" data-r="0">Nochmal üben</button></div></div>`;
  $$(".sc-r",out).forEach(b=>b.onclick=()=>{logDay("write");logEvent("write",(t.t||"Schreiben")+" · Selbstcheck: "+b.textContent);S.corrections.push({date:todayKey(),ok:b.dataset.r==="2",self:true});saveSoon();toast("Notiert");if(o.onDone)o.onDone({self:+b.dataset.r})})}
function renderCorrection(out,orig,r,t){const errs=Array.isArray(r.errors)?r.errors:[];
  out.innerHTML=`<div class="stack s fade-in"><div class="card ${r.ok?"":"raise"}" style="${r.ok?"border-color:var(--good)":""}"><div class="row"><span class="pill ${r.ok?"good":"o"}">${r.ok?"Korrekt":errs.length+" Fehler"}</span>${r.register_ok===false?'<span class="pill grammatik">Register</span>':""}</div>
   ${r.corrected&&r.corrected.trim()!==orig.trim()?`<div style="margin-top:.6rem"><div class="eyebrow">Korrigiert</div><div style="font-size:1.05rem">${wordDiff(orig,r.corrected)}</div></div>`:""}
   ${r.natural?`<div style="margin-top:.6rem"><div class="row between"><div class="eyebrow">Natürlich</div><button class="icon ghost" data-say="${esc(r.natural)}">${ic("vol")}</button></div><div style="font-style:italic">${esc(r.natural)}</div></div>`:""}
   ${r.note?`<p class="muted" style="margin-top:.5rem;font-size:.95rem">${esc(r.note)}</p>`:""}</div>
   ${errs.length?`<div class="list">${errs.map(e=>`<div class="li" style="cursor:default;align-items:flex-start"><span class="pill grammatik" style="flex-shrink:0">${esc(e.type||"")}</span><div class="t"><b style="font-family:var(--body);font-weight:400"><span class="d-del">${esc(e.original||"")}</span> → <span class="d-ok" style="font-weight:600">${esc(e.fix||"")}</span></b><small>${esc(e.why||"")}</small></div></div>`).join("")}</div>`:""}
   ${t.model?`<details class="card"><summary class="ui" style="cursor:pointer;font-weight:700">Musterlösung</summary><p style="margin-top:.5rem;white-space:pre-wrap">${esc(t.model)}</p></details>`:""}
   ${r.followup&&r.followup.task?`<div class="card tint stack s"><div class="eyebrow">Selbst korrigieren <span class="en">try the fix yourself</span></div><div>${esc(r.followup.task)}</div><div class="typed"><input class="fu-in" autocomplete="off" placeholder="Antwort…"><button class="primary fu-go">Prüfen</button></div><div class="fu-out"></div></div>`:""}</div>`;
  const fg=$(".fu-go",out);if(fg)fg.onclick=()=>{const g=gradeTyped($(".fu-in",out).value,String(r.followup.answer||""));$(".fu-out",out).innerHTML=`<div class="verdict ${g.q>=1?"ok":"no"}">${g.q>=1?"Richtig.":"Lösung:"} ${esc(r.followup.answer||"")}</div>`}}
// ---------- roleplay
function simRunner(el,sim,o){o=o||{};const cs=o.case||FSP_CASES[Math.floor(Math.random()*FSP_CASES.length)];const rules=sim.make(cs);const turns=[];let ctl=null,busy=false,ended=false;
  const label=sim.k==="klinik"?`${cs.name}, ${cs.age}, ${cs.job}`:sim.name;
  function draw(){el.innerHTML=`<div class="head"><div class="row"><span class="pill ${sim.k}">${esc(sim.name)}</span></div><h2>${esc(sim.who)}</h2>${sim.k==="klinik"&&sim.id!=="oa"?`<p class="muted ui">${esc(label)}</p>`:sim.id==="oa"?`<p class="muted ui">Fall: ${esc(cs.cc)}</p>`:""}</div>
    <div class="dl sim-log">${turns.map(t=>`<div class="turn ${t.role==="user"?"me":""}"><div class="who"><span>${t.role==="user"?"Du":esc(sim.who)}</span>${t.role==="assistant"?`<button data-say="${esc(t.content)}" aria-label="Anhören">${ic("vol")}</button>`:""}</div><div>${esc(t.content)}</div></div>`).join("")||`<div class="empty"><div class="big">M</div><p>Du beginnst. Begrüße dein Gegenüber${sim.k==="klinik"?" und stell dich vor":""}.</p></div>`}<div class="sim-pend"></div></div>
    ${ended?"":`<div class="card stack s"><textarea class="sim-in" style="min-height:76px" placeholder="Deine Antwort auf Deutsch… (Enter sendet)"></textarea><div class="row between"><div class="row"><button class="icon sim-mic need-sr" aria-label="Sprechen">${ic("mic")}</button><button class="primary sim-send">Senden</button><button class="sm ghost sim-stop" hidden>Stopp</button></div><button class="sm sim-end" ${turns.length<4?"disabled":""}>Beenden &amp; bewerten</button></div></div>`}<div class="sim-eval"></div>`;
    $$("[data-say]",el);const inp=$(".sim-in",el);if(inp){inp.onkeydown=e=>{if(e.key==="Enter"&&!e.shiftKey){e.preventDefault();send()}};setTimeout(()=>inp.focus(),30)}
    const sb=$(".sim-send",el);if(sb)sb.onclick=send;const smc=$(".sim-mic",el);if(smc)smc.onclick=()=>dictateInto(smc,$(".sim-in",el));const en=$(".sim-end",el);if(en)en.onclick=evaluate;const sp=$(".sim-stop",el);if(sp)sp.onclick=()=>ctl&&ctl.abort();
    const fb=$("#fBody");if(fb)fb.scrollTop=fb.scrollHeight}
  async function send(){const inp=$(".sim-in",el);const t=inp&&inp.value.trim();if(!t||busy)return;busy=true;turns.push({role:"user",content:t});draw();$(".sim-pend",el).innerHTML=`<div class="turn"><div class="who"><span>${esc(sim.who)}</span></div><div class="sim-stream muted">…</div></div>`;$(".sim-stop",el).hidden=false;ctl=new AbortController();
    try{const {text}=await SAMPLE([{role:"user",content:rules},...turns],{cache:false,modelTier:"quick",signal:ctl.signal,onText:({text})=>{const s=$(".sim-stream",el);if(s){s.textContent=text;s.classList.remove("muted")}}});turns.push({role:"assistant",content:text});busy=false;draw();say(text,{silent:true})}
    catch(e){busy=false;if(e&&e.text)turns.push({role:"assistant",content:e.text});draw();if(e&&e.code!=="cancelled")toast(tutorMsg(e.code))}}
  async function evaluate(){if(busy)return;busy=true;ended=true;draw();const ev=$(".sim-eval",el);ev.innerHTML=`<div class="card"><p class="muted">Claude bewertet das Gespräch…</p></div>`;
    const tr=turns.map(t=>(t.role==="user"?"LERNENDER: ":sim.who.toUpperCase()+": ")+t.content).join("\n");
    try{const r=await SAMPLE.json(`Du bist Prüfer der Fachsprachprüfung und DaF-Lehrer. ${LEARNER}
Situation: ${sim.name}${sim.k==="klinik"?" (Fall: "+cs.cc+"; erwartete Diagnose: "+cs.dx+")":""}. Bewerte NUR die Beiträge des LERNENDEN:
${tr}

Antworte NUR mit JSON: {"grammar":1-5,"register":1-5,"communication":1-5,"summary":"<zwei Sätze, Englisch>","strengths":["<kurz>","<kurz>"],"missed":["<wichtige vergessene Frage/Information, falls vorhanden>"],"errors":[{"type":"<einer von: ${ERR_TYPES.join(", ")}>","original":"<Zitat>","fix":"<Korrektur>","why":"<Regel, ein Satz, Englisch>"}],"next":"<ein konkreter Übungsvorschlag, Englisch>"} — höchstens 6 Fehler, die wichtigsten zuerst; korrekte Alternativen sind keine Fehler.`,{modelTier:"default",cache:false});
      const errs=Array.isArray(r.errors)?r.errors:[];addErrors(errs,"sim");const g=clamp(+r.grammar||0,0,5),rg=clamp(+r.register||0,0,5),cm=clamp(+r.communication||0,0,5);S.sims.push({date:todayKey(),sim:sim.id,g,r:rg,c:cm});logEvent("sim","Rollenspiel „"+sim.name+"“ · "+g+"/"+rg+"/"+cm,Math.round(100*(g+rg+cm)/15));if(S.sims.length>80)S.sims=S.sims.slice(-80);logDay("sim");saveSoon();
      ev.innerHTML=`<div class="card raise stack s fade-in"><h3>Bewertung</h3><div class="stats"><div class="stat"><b>${g}/5</b><span>Grammatik</span></div><div class="stat"><b>${rg}/5</b><span>Register</span></div><div class="stat"><b>${cm}/5</b><span>Kommunikation</span></div></div><p>${esc(r.summary||"")}</p>
       ${Array.isArray(r.strengths)&&r.strengths.length?`<p class="fg2"><span class="ok">Gut:</span> ${esc(r.strengths.join(" · "))}</p>`:""}${Array.isArray(r.missed)&&r.missed.filter(Boolean).length?`<p class="fg2"><span class="no">Vergessen:</span> ${esc(r.missed.filter(Boolean).join(" · "))}</p>`:""}
       ${errs.length?`<div class="list">${errs.map(e=>`<div class="li" style="cursor:default;align-items:flex-start"><span class="pill grammatik" style="flex-shrink:0">${esc(e.type||"")}</span><div class="t"><b style="font-family:var(--body);font-weight:400"><span class="d-del">${esc(e.original||"")}</span> → <span class="d-ok" style="font-weight:600">${esc(e.fix||"")}</span></b><small>${esc(e.why||"")}</small></div></div>`).join("")}</div>`:""}
       ${r.next?`<div class="why"><b>Nächster Schritt:</b> ${esc(r.next)}</div>`:""}</div>`;busy=false;if(o.onDone)o.onDone({g,r:rg,c:cm})}
    catch(e){busy=false;ev.innerHTML=`<p class="no">${esc(tutorMsg(e&&e.code))}</p>`;if(o.onDone)o.onDone(null)}}
  draw()}
// ---------- shadowing
function shadowRunner(el,lines,o){o=o||{};let i=0,auto=false,stop=false;
  function draw(){if(i>=lines.length){el.innerHTML=`<div class="celebrate fade-in"><div class="eyebrow">Schattensprechen</div><h2>${lines.length} Zeilen geschafft.</h2><p class="muted">Rhythmus vor Perfektion. Morgen dieselben Zeilen schneller.</p></div>`;logDay("flu");if(o.onDone)o.onDone();return}
    const l=lines[i];el.innerHTML=`<div class="head"><div class="eyebrow">Zeile ${i+1} / ${lines.length} <span class="en">shadowing</span></div></div>
     <div class="card raise" style="text-align:center;padding:1.8rem 1.2rem"><div style="font-family:var(--display);font-size:1.5rem;line-height:1.35">${esc(l.de)}</div><div class="muted ui" style="margin-top:.6rem">${esc(l.en||"")}</div><div class="sh-st eyebrow" style="margin-top:1rem;min-height:1.2em"></div></div>
     <div class="row"><button class="primary sh-play">${ic("play")} ${TTS_OK?"Hören & nachsprechen":"Laut lesen"}</button><button class="sm sh-auto">${auto?ic("pause")+" Auto aus":ic("bolt")+" Auto"}</button><button class="sm ghost sh-next">Nächste</button><button class="sm sh-mic need-sr">${ic("mic")} Prüfen</button></div><div class="sh-out"></div>
     <p class="muted ui" style="font-size:.88rem">${TTS_OK?"Sprich gleichzeitig oder einen halben Atemzug später mit. Kopiere Melodie und Pausen, nicht nur die Wörter.":"In dieser Ansicht gibt es keine Sprachausgabe: lies die Zeile laut, dreimal, jedes Mal flüssiger."}</p>`;
    $(".sh-play",el).onclick=()=>run(false);const shm=$(".sh-mic",el);if(shm)shm.onclick=e=>{stop=true;speakCheck(e.currentTarget,l.de,$(".sh-out",el))};$(".sh-next",el).onclick=()=>{i++;draw()};$(".sh-auto",el).onclick=()=>{auto=!auto;if(auto)run(true);else{stop=true;draw()}}}
  async function run(chain){stop=false;const l=lines[i];const st=$(".sh-st",el);if(st)st.textContent=TTS_OK?"Hör zu…":"Lies laut…";await say(l.de,{silent:true});if(stop||!document.body.contains(el))return;const wait=Math.max(1800,l.de.split(/\s+/).length*520);if(st)st.textContent="Jetzt du";await new Promise(r=>setTimeout(r,wait));if(stop||!document.body.contains(el))return;if(chain&&auto){i++;draw();if(i<lines.length)run(true)}else if(st)st.textContent="Nochmal oder weiter"}
  draw()}
// ---------- dictation
function dictationRunner(el,lines,o){o=o||{};let i=0,score=0,shown=false;
  function draw(){if(i>=lines.length){const pct=Math.round(100*score/lines.length);el.innerHTML=`<div class="celebrate fade-in"><div class="eyebrow">Diktat</div><h2>${pct} %</h2><p class="muted">${String(Math.round(score*10)/10).replace(".",",")} von ${lines.length} Sätzen.</p></div>`;logDay("flu");logEvent("flu","Diktat · "+pct+" %",pct);if(o.onDone)o.onDone(pct);return}
    const l=lines[i];el.innerHTML=`<div class="head"><div class="eyebrow">Satz ${i+1} / ${lines.length} <span class="en">${TTS_OK?"listen and type":"memory dictation"}</span></div></div>
     <div class="card raise" style="text-align:center;padding:1.4rem">${TTS_OK?`<button class="primary dc-play" style="min-height:64px;padding:0 1.6rem">${ic("vol")} Abspielen</button><div class="row" style="justify-content:center;margin-top:.6rem"><button class="sm ghost dc-slow">Langsam</button></div>`:`<div class="dc-show" style="font-family:var(--display);font-size:1.3rem">${shown?"":esc(l.de)}</div><p class="muted ui" style="margin-top:.5rem">${shown?"Jetzt aus dem Gedächtnis schreiben.":"Merk dir den Satz, dann verdecken."}</p>${shown?"":`<button class="sm dc-hide" style="margin-top:.6rem">Verdecken</button>`}`}</div>
     <textarea class="dc-in" style="min-height:80px" placeholder="Schreib, was du hörst…" spellcheck="false"></textarea><div class="row"><button class="primary dc-chk">Prüfen</button></div><div class="dc-out"></div>`;
    const p=$(".dc-play",el);if(p){p.onclick=()=>say(l.de);$(".dc-slow",el).onclick=()=>say(l.de,{rate:.7});setTimeout(()=>say(l.de,{silent:true}),250)}const h=$(".dc-hide",el);if(h)h.onclick=()=>{shown=true;draw()};
    $(".dc-chk",el).onclick=()=>{const got=$(".dc-in",el).value;const s=similarity(got,l.de);score+=s>=.95?1:s>=.75?.5:0;$(".dc-out",el).innerHTML=`<div class="verdict ${s>=.9?"ok":"no"}" data-noxp="1"><div>${Math.round(s*100)} % übereinstimmend</div><div style="font-size:1.08rem">${wordDiff(got,l.de)}</div></div>${typeof dictTeach==="function"?dictTeach(got,l.de):""}<div class="row" style="margin-top:.6rem"><button class="primary dc-nx">Weiter</button></div>`;$(".dc-nx",el).onclick=()=>{i++;shown=false;draw()};KEYS=e=>{if(e.key==="Enter"&&!e.shiftKey){e.preventDefault();i++;shown=false;draw()}}};KEYS=null}
  draw()}
// ---------- 4/3/2 fluency talk
function talk432(el,topic,o){o=o||{};const phases=[240,180,120];let ph=0,left=phases[0],run=false,t=null;
  function fmt(s){return pad(Math.floor(s/60))+":"+pad(s%60)}
  function draw(){if(ph>=3){el.innerHTML=`<div class="celebrate fade-in"><div class="eyebrow">4 / 3 / 2</div><h2>Dreimal erzählt.</h2><p class="muted" style="max-width:44ch">Beim dritten Mal hattest du nur noch zwei Minuten für dieselbe Geschichte – genau dieser Zeitdruck macht das Sprechen flüssiger. Schreib die zwei Sätze auf, die du am häufigsten gesagt hast, und prüf sie im Schreiben-Teil.</p></div><div class="card t-write"></div>`;logDay("flu");freeText($(".t-write",el),{t:"Zwei Sätze aus deinem Vortrag",task:esc(topic),ctx:"4/3/2-Vortrag: "+topic,reg:"gesprochen, natürlich",check:["Verb an Position 2","Vollständige Sätze","Fachwörter korrekt"]});if(o.onDone)o.onDone();return}
    el.innerHTML=`<div class="head"><div class="eyebrow">Runde ${ph+1} von 3 · ${phases[ph]/60} Minuten <span class="en">4/3/2 fluency</span></div><h2 style="font-size:1.3rem">${esc(topic)}</h2></div>
     <div class="card raise" style="text-align:center;padding:1.8rem"><div class="timer">${fmt(left)}</div><p class="muted ui" style="margin-top:.6rem">${ph===0?"Erzähl frei und laut. Stopp nicht für Fehler.":ph===1?"Dasselbe nochmal, in drei Minuten. Gleicher Inhalt, flüssiger.":"Und jetzt in zwei Minuten. So flüssig wie möglich."}</p></div>
     <div class="row"><button class="primary t-go">${run?ic("pause")+" Pause":ic("play")+" Start"}</button><button class="sm t-next">${ph<2?"Nächste Runde":"Fertig"}</button></div>`;
    $(".t-go",el).onclick=()=>{run=!run;if(run){t=every(()=>{left--;const tm=$(".timer",el);if(tm)tm.textContent=fmt(Math.max(0,left));if(left<=0){clearInterval(t);run=false;toast("Zeit um");ph++;left=phases[ph]||0;draw()}},1000)}else clearInterval(t);draw()};
    $(".t-next",el).onclick=()=>{clearInterval(t);run=false;ph++;left=phases[ph]||0;draw()}}
  draw()}
// ---------- drills
function drillRunner(el,kind,o){o=o||{};let n=0,right=0;const N=kind==="respond"?RESPOND.length:kind==="abbr"?10:12;const order=shuffle([...Array(200).keys()]);
  function finish(){const pct=Math.round(100*right/N);el.innerHTML=`<div class="celebrate fade-in"><div class="eyebrow">Drill</div><h2>${right} / ${N}</h2><p class="muted">${pct>=85?"Sauber.":pct>=60?"Solide. Morgen nochmal.":"Lies die Lektion dazu und versuch es erneut."}</p><button class="primary dr-again">Nochmal</button></div>`;$(".dr-again",el).onclick=()=>drillRunner(el,kind,o);logDay("drill");logEvent("drill","Drill „"+kind+"“ · "+right+"/"+N,pct);KEYS=null;if(o.onDone)o.onDone(pct)}
  function mc(html,opts,a,why){el.innerHTML=`<div class="q fade-in">${html}<div class="opts">${opts.map((x,k)=>`<button data-k="${k}"><span class="k">${k+1}</span>${x}</button>`).join("")}</div><div class="dr-why"></div></div>`;const pick=k=>{if($(".dr-why",el).innerHTML)return;if(typeof fb==="function")fb(k===a);$$("[data-k]",el).forEach(b=>{b.disabled=true;if(+b.dataset.k===a)b.classList.add("right")});if(k===a)right++;else $$("[data-k]",el)[k].classList.add("wrong");$(".dr-why",el).innerHTML=`<div class="why">${why}</div><div class="row" style="margin-top:.7rem"><button class="primary dr-nx">Weiter <span class="kbd">↵</span></button></div>`;$(".dr-nx",el).onclick=next;KEYS=e=>{if(e.key==="Enter"){e.preventDefault();next()}}};$$("[data-k]",el).forEach(b=>b.onclick=()=>pick(+b.dataset.k));KEYS=e=>{const k=+e.key;if(k>=1&&k<=opts.length)pick(k-1)}}
  function typed(html,ans,full){el.innerHTML=`<div class="q fade-in">${html}<div class="typed"><input class="dr-in" autocomplete="off" autocapitalize="off" spellcheck="false" placeholder="Antwort…"><button class="primary dr-chk">Prüfen</button></div><div class="dr-why"></div></div>`;const inp=$(".dr-in",el);setTimeout(()=>inp.focus(),30);let done=false;const chk=()=>{if(done){next();return}done=true;const ok=normT(inp.value)===normT(ans);if(ok)right++;if(typeof fb==="function")fb(ok);$(".dr-why",el).innerHTML=`<div class="verdict ${ok?"ok":"no"}">${ok?"Richtig.":"Lösung:"} ${full}</div><div class="row" style="margin-top:.7rem"><button class="primary dr-nx">Weiter <span class="kbd">↵</span></button></div>`;$(".dr-nx",el).onclick=next};$(".dr-chk",el).onclick=chk;KEYS=e=>{if(e.key==="Enter"){e.preventDefault();chk()}}}
  function next(){if(n>=N)return finish();const r=order[n];n++;if(o.onProgress)o.onProgress(n/N);const hd=t=>`<div class="eyebrow">${t} · ${n} / ${N}</div>`;
    if(kind==="artikel"){const nouns=VOCAB.filter(x=>x[2]==="n"&&/^(der|die|das) /.test(x[0]));const w=nouns[(r*7919)%nouns.length];const art=w[0].split(" ")[0],noun=w[0].slice(art.length+1);mc(hd("Artikel")+`<div class="stem">___ ${esc(noun)} <span class="muted ui" style="font-size:.9rem">(${esc(w[1])})</span></div>`,["der","die","das"].map(a=>`<span class="g-${a}">${a}</span>`),["der","die","das"].indexOf(art),genderWhy(noun,art))}
    else if(kind==="faelle"){const c=CASES[r%CASES.length];mc(hd("Fälle")+`<div class="stem">${esc(c[0])}</div>`,c[1].map(esc),c[2],esc(c[3]))}
    else if(kind==="cloze"){const c=CLOZE[r%CLOZE.length];typed(hd("Faust-Lücke · "+esc(c[3]))+`<div class="stem">${esc(c[0])}</div><p class="muted ui">Hinweis: ${esc(c[2])}</p>`,c[1],esc(c[0].replace("___",c[1])))}
    else if(kind==="verben"){const vb=CONJ[r%CONJ.length];const p=r%6;const pres=(r>>1)%2===0;const ans=pres?vb[2][p]:vb[3][p];typed(hd("Verben · "+(pres?"Präsens":"Präteritum"))+`<div class="stem">${esc(vb[0])} <span class="muted ui">(${esc(vb[1])})</span> → <b>${PERSONS[p]}</b> ___</div>`,ans,`${PERSONS[p]} ${esc(ans)} · Partizip: ${esc(vb[4])}`)}
    else if(kind==="respond"){const x=RESPOND[r%RESPOND.length];const opts=shuffle(x[1].map((t,k)=>({t,k})));mc(hd("Patient sagt")+`<div class="stem">„${esc(x[0])}“</div>`,opts.map(y=>esc(y.t)),opts.findIndex(y=>y.k===x[2]),esc(x[3]))}
    else if(kind==="abbr"){const U=el._abbrUsed||(el._abbrUsed=new Set());let ai=r%ABBR.length;for(let g=0;g<ABBR.length&&U.has(ai);g++)ai=(ai+1)%ABBR.length;U.add(ai);const a=ABBR[ai];const head=s=>s[1].split(" — ")[0];const others=shuffle(ABBR.filter(y=>y!==a)).slice(0,3).map(head);const opts=shuffle([head(a)].concat(others));mc(hd("Abkürzung")+`<div class="stem mono">${esc(a[0])}</div>`,opts.map(esc),opts.indexOf(head(a)),esc(a[1]))}}
  next()}
function genderWhy(noun,art){const rules=[[/(ung|heit|keit|schaft|ion|tät|ie|ik|ur)$/,"die","feminine suffix"],[/(chen|lein|um|ment|ma)$/,"das","neuter suffix"],[/(ling|ismus|or|ant|ist)$/,"der","masculine suffix"],[/e$/,"die","most -e nouns are feminine"]];for(const x of rules){if(x[0].test(noun))return `<span class="g-${art}">${art}</span> ${esc(noun)}: ${x[2]}${x[1]!==art?" (this one is an exception)":""}.`}return `<span class="g-${art}">${art}</span> ${esc(noun)}: no suffix rule, learn it with the article.`}
