const R={tab:"home",seg:null,id:null};
FOCUS.zertifikat={name:"Zertifikat",tag:"Goethe- / telc-B2-Sprint",desc:"Allgemeines B2 für den Approbationsantrag: fast täglich Prüfungsaufgaben in Lesen, Hören, Schreiben, Sprechen; Klinik läuft weiter.",order:["gram","med","alltag"],newOrder:["core","alltag","med","satz","faust"],mix:{review:.2,learn:.15,input:.25,output:.3,fluency:.1}};
const LVR={A1:1,A2:2,B1:3,B2:4,C1:5,C2:6};const lvlRank=s=>LVR[String(s).slice(0,2)]||3;
function pickFilm(){const max=weekNumber()<=6?3:weekNumber()<=14?4:5;const pref=S.focus==="literatur"?"literatur":"medizin";const pool=KINO.filter(k=>!(S.kino||{})[k.id]&&lvlRank(k.lvl)<=max);const best=pool.find(k=>k.tags.includes(pref))||pool[0]||KINO[dayNumber()%KINO.length];return best.id}
const TABS=[["home","Heute","home"],["learn","Lernen","learn"],["practice","Üben","practice"],["me","Ich","me"]];
function go(tab,arg){if(typeof tab!=="string"||!/^(home|learn|practice|me)$/.test(tab))tab="home";if(Focus.isOpen())Focus.close(true);closeSheet();R.tab=tab;R.id=null;if(arg){if(arg.startsWith("id:"))R.id=arg.slice(3);else if(arg.startsWith("seg:")){R.seg=arg.slice(4)}}window.scrollTo({top:0});rerender()}
function applyPrefs(){const h=document.documentElement;if(S.theme==="system")h.removeAttribute("data-theme");else h.dataset.theme=S.theme;h.classList.toggle("nohints",!S.hints);h.classList.toggle("nomotion",!S.motion)}
function chrome(){const nav=TABS.map(([k,n,i])=>`<button data-go="${k}" class="${R.tab===k?"on":""}" aria-current="${R.tab===k?"page":"false"}">${ic(i)}<span>${n}</span></button>`).join("");$("#bar").innerHTML=nav;$("#sideNav").innerHTML=nav;
  const d=Math.min(dayNumber(),TOTAL_DAYS),sk=streak();$("#topChips").innerHTML=`<span class="chip flame">${ic("flame")}${sk}</span><span class="chip">Tag ${d}</span>`;
  $("#sideWeek").innerHTML=`<div class="eyebrow">Woche ${weekNumber()} von ${WEEKS.length}</div><div style="font-family:var(--display);font-size:1.05rem;margin:.3rem 0 .6rem;line-height:1.25">${esc(WEEK().theme)}</div><div class="pbar"><i style="width:${Math.round(100*d/TOTAL_DAYS)}%"></i></div><div class="row between ui muted" style="font-size:.8rem;margin-top:.45rem"><span>Tag ${d} / ${TOTAL_DAYS}</span><span class="chip flame" style="font-size:.75rem">${ic("flame")}${sk}</span></div>`}
function rerender(){chrome();const m=$("#main");try{({home:viewHome,learn:viewLearn,practice:viewPractice,me:viewMe})[R.tab](m)}catch(e){logError(e);m.innerHTML=`<div class="view"><div class="head"><h1>Hoppla.</h1><p>Diese Seite konnte nicht geladen werden. Dein Fortschritt ist gespeichert.</p></div><div class="crash">${esc(String(e&&e.stack||e)).slice(0,900)}</div><div class="row"><button class="primary" data-go="home">Zu Heute</button></div></div>`}}
function onCapsChanged(){if(!Focus.isOpen())rerender()}
// ================= SESSION =================
function weekLessons(w){const f=FOCUS[S.focus];return f.order.flatMap(k=>k==="med"?w.med:k==="gram"?w.gram:w.alltag).filter((v,i,a)=>a.indexOf(v)===i&&lessonById(v))}
function pickLesson(){const wn=weekNumber();for(let w=wn;w<=Math.min(WEEKS.length,wn+2);w++){const id=weekLessons(WEEKS[w-1]).find(id=>!S.lessons[id]);if(w===wn&&id)return id;if(w===wn){const due=lessonsDue();if(due.length)return due.sort((a,b)=>S.lessons[a].best-S.lessons[b].best)[0]}if(w>wn&&id)return id}
  const all=Object.keys(S.lessons);return all.length?all.sort((a,b)=>S.lessons[a].best-S.lessons[b].best)[0]:"m1"}
function pickInput(){const w=WEEK(),d=weekDay(),wn=weekNumber();if(d===7)return {kind:"kino",id:pickFilm()};
  if((S.focus==="zertifikat"&&d!==4)||(wn>=6&&d===2)){const ex=targetExam();const t=nextTeilFor(ex,["Lesen","Hören"]);return {kind:"exam",ex,id:t.id}}
  if(S.focus==="literatur"){const p=POEMS.find(x=>x.week<=wn+2&&!S.read[x.id]);if(p&&d%2===0)return {kind:"poem",id:p.id}}const ids=S.focus==="literatur"?[...w.faust,...w.texts]:[...w.texts,...w.faust];let id=ids.find(x=>!S.read[x]);if(id)return {kind:id[0]==="f"?"faust":"text",id};
  const more=TEXTS.concat(FAUST).filter(x=>x.week<=weekNumber()+1&&!S.read[x.id]);if(more.length)return {kind:more[0].lines?"faust":"text",id:more[0].id};
  const done=Object.keys(S.lessons).filter(l=>(lessonById(l)||{}).dialog&&lessonById(l).dialog.length);if(done.length)return {kind:"dialog",id:done[done.length-1]};return {kind:"text",id:ids[0]||"t1"}}
function pickOutput(){const d=weekDay(),w=weekNumber(),f=S.focus;
  if(f==="zertifikat"&&[1,2,3,5,6].includes(d)){const ex=targetExam();const t=nextTeilFor(ex,[1,3,5].includes(d)?["Schreiben"]:["Sprechen"]);return {kind:"exam",ex,id:t.id}}
  if(w>=6&&d===4){const ex=targetExam();const t=nextTeilFor(ex,["Schreiben"]);return {kind:"exam",ex,id:t.id}}
  if(f==="pruefung"){if(d===7&&w>=4)return {kind:"fsp"};if(d%2===0)return {kind:"sim",id:["pat","oa","tel"][(w+d)%3]}}
  else{if(d===7&&w>=12&&f==="klinik")return {kind:"fsp"};if(d===3||d===6){const pool=f==="ankommen"?["amt","vermieter","nachbarin","lena"]:f==="literatur"?["lena","pat"]:["pat","oa","tel","lena"];return {kind:"sim",id:pool[(w+d)%pool.length]}}}
  const pref=f==="ankommen"?"alltag":"klinik";const pool=TASKS.map((t,i)=>i).filter(i=>TASKS[i].k===pref);const all=TASKS.map((t,i)=>i);const list=(dayNumber()%3===2)?all:pool;return {kind:"task",id:list[dayNumber()%list.length]}}
function shadowLines(lessonId){let L=lessonId&&lessonById(lessonId);if(!L||!L.dialog||!L.dialog.length){const ids=Object.keys(S.lessons).filter(l=>(lessonById(l)||{}).dialog&&lessonById(l).dialog.length);L=lessonById(ids[ids.length-1]||"m1")}
  return L.dialog.filter(d=>d[1].split(/\s+/).length<=18).slice(0,6).map(d=>({de:d[1],en:d[2]}))}
function pickFluency(lessonId){const d=weekDay();if(d===5)return {kind:"432",topic:TALKS[S.focus==="ankommen"?"alltag":"klinik"][weekNumber()%5]};if(d===2||d===4)return {kind:"dict",lesson:lessonId};if(S.focus==="literatur"&&WEEK().faust.length)return {kind:"shadowF",id:WEEK().faust[0]};return {kind:"shadow",lesson:lessonId}}
function pickCulture(){const w=WEEK();let i=w.kultur.find(k=>!S.kultur[k]);if(i==null){const left=KULTUR.map((_,k)=>k).filter(k=>!S.kultur[k]);i=left.length?left[0]:dayNumber()%KULTUR.length}return {idx:i}}
function buildSession(){const M=typeof effMin==="function"?effMin():S.minutes;const lesson=pickLesson();const steps=[{t:"review"},{t:"learn",ref:{id:lesson}}];if(M>=45)steps.push({t:"input",ref:pickInput()});steps.push({t:"output",ref:pickOutput()});if(M>=40)steps.push({t:"fluency",ref:pickFluency(lesson)});steps.push({t:"culture",ref:pickCulture()});
  S.today={date:todayKey(),steps:steps.map(s=>Object.assign({done:false},s)),idx:0,focus:S.focus,minutes:M,started:null,stats:{cards:0,ok:0}};saveSoon()}
function ensureSession(){const T=S.today;const M=typeof effMin==="function"?effMin():S.minutes;if(!T||T.date!==todayKey())buildSession();else if((T.focus!==S.focus||T.minutes!==M)&&!T.steps.some(s=>s.done))buildSession();return S.today}
function stepInfo(s){const n=STRAND[s.t];let sub="";try{
  if(s.t==="review"){const dk=dueKeys().length,cp=typeof revCap==="function"?revCap():S.maxReviews;const q=Math.min(dk,cp);resetNewToday();const na=typeof newAllowance==="function"?newAllowance():Math.max(0,S.newPerDay-S.newToday.n);sub=`${q} fällig · ${na?na+" neu":"neue Karten pausiert – erst aufholen"}${dk>cp?` · ${dk-cp} gestundet`:""}`}
  else if(s.t==="learn"){const L=lessonById(s.ref.id);sub=L?L.title:""}
  else if((s.t==="input"||s.t==="output")&&s.ref.kind==="exam"){const t=examTeil(s.ref.ex,s.ref.id);sub=EXAMS[s.ref.ex].short+" · "+t.m+" "+t.t+": "+t.title}
  else if(s.t==="input"&&s.ref.kind==="kino"){const k=KINO.find(x=>x.id===s.ref.id);sub="Filmabend: "+(k?k.t:"")}
  else if(s.t==="input"&&s.ref.kind==="poem"){sub="Gedicht: "+(POEMS.find(x=>x.id===s.ref.id)||{}).title}
  else if(s.t==="input"){sub=s.ref.kind==="dialog"?"Wiederhören: "+(lessonById(s.ref.id)||{}).title:((TEXTS.find(x=>x.id===s.ref.id)||FAUST.find(x=>x.id===s.ref.id)||{}).title||"")}
  else if(s.t==="output"){sub=s.ref.kind==="fsp"?"FSP-Simulation (60 min)":s.ref.kind==="sim"?(SAMPLE?"Rollenspiel: ":"Schreiben statt Rollenspiel: ")+(SIMS.find(x=>x.id===s.ref.id)||{}).name:TASKS[s.ref.id].t}
  else if(s.t==="fluency"){sub=s.ref.kind==="432"?"4/3/2: "+s.ref.topic:s.ref.kind==="dict"?"Diktat":s.ref.kind==="shadowF"?"Schattensprechen: Goethe":"Schattensprechen"}
  else if(s.t==="culture"){sub=KULTUR[s.ref.idx][0]+" · Redewendung"}}catch(e){}
  return {name:n.name,en:n.en,icon:n.icon,sub}}
function openSession(at){const T=ensureSession();if(typeof at==="number")T.idx=at;if(!T.started)T.started=Date.now();saveSoon();Focus.open({title:"Heutige Sitzung",onClose:()=>saveNow()});runStep()}
function runStep(){const T=S.today;if(T.idx>=T.steps.length||T.steps.every(s=>s.done))return finishSession();const s=T.steps[T.idx];const info=stepInfo(s);
  Focus.title(info.name,`Schritt ${T.idx+1} von ${T.steps.length} · ${info.en}`);Focus.progress({n:T.steps.length,i:T.idx,p:0});Focus.tools("");KEYS=null;const el=Focus.body();
  const done=()=>{s.done=true;saveSoon();Focus.sub(1);Focus.foot(`<button class="ghost sm" data-act="stepBack" ${T.idx===0?"disabled":""}>${ic("back")}</button><button class="primary" data-act="stepNext">${T.idx+1<T.steps.length?"Weiter: "+STRAND[T.steps[T.idx+1].t].name:"Abschließen"} ${ic("chev")}</button>`)};
  Focus.foot(`<button class="ghost sm" data-act="stepBack" ${T.idx===0?"disabled":""}>${ic("back")}</button><button class="sm" data-act="stepSkip" style="margin-left:auto">Überspringen</button>`);
  try{
  if(s.t==="review"){const cap=Math.max(15,Math.round(S.minutes*FOCUS[S.focus].mix.review*5));const q=buildQueue().slice(0,cap+S.newPerDay);if(!q.length){el.innerHTML=`<div class="empty"><div class="big">M</div><h2>Alles wiederholt.</h2><p>Keine Karten fällig. Weiter mit Neuem.</p></div>`;return done()}cardRunner(el,q,{onProgress:p=>Focus.sub(p),onDone:r=>{T.stats.cards+=r.n;T.stats.ok+=r.ok;done()}})}
  else if(s.t==="learn"){const L=lessonById(s.ref.id);lessonView(el,L,{session:true,onDone:()=>done()})}
  else if((s.t==="input"||s.t==="output")&&s.ref.kind==="exam"){const t=examTeil(s.ref.ex,s.ref.id);Focus.title(s.t==="input"?"Prüfungstraining":"Prüfung: "+t.m,`Schritt ${T.idx+1} von ${T.steps.length} · ${EXAMS[s.ref.ex].short}`);openTeil(el,s.ref.ex,t,{onDone:()=>done()})}
  else if(s.t==="input"&&s.ref.kind==="kino"){filmStep(el,KINO.find(x=>x.id===s.ref.id),done)}
  else if(s.t==="input"&&s.ref.kind==="poem"){readerView(el,POEMS.find(x=>x.id===s.ref.id),{onDone:done})}
  else if(s.t==="input"&&s.ref.kind==="hoeren"){hoerenRunner(el,HOEREN.find(x=>x.id===s.ref.id),{onDone:done})}
  else if(s.t==="input"){if(s.ref.kind==="dialog"){const L=lessonById(s.ref.id);el.innerHTML=`<div class="head"><div class="eyebrow">Wiederhören <span class="en">listen again, no translation</span></div><h2>${esc(L.title)}</h2></div><div class="row"><button class="sm in-play">${ic("play")} Alles anhören</button><button class="sm ghost in-tr">Übersetzung</button></div><div class="card">${dialogHTML(L.dialog)}</div><button class="primary in-ok">Verstanden</button>`;$$(".tr",el).forEach(x=>x.hidden=true);$(".in-tr",el).onclick=()=>$$(".tr",el).forEach(x=>x.hidden=!x.hidden);$(".in-play",el).onclick=async()=>{for(const d of L.dialog){if(!document.body.contains(el))break;if(!(await say(d[1])))break}};$(".in-ok",el).onclick=()=>{logDay("read");done()}}
    else{const item=(s.ref.kind==="faust"?FAUST:TEXTS).find(x=>x.id===s.ref.id);readerView(el,item,{onDone:done})}}
  else if(s.t==="output"){const r=s.ref;if(r.kind==="fsp"){Focus.title("FSP-Simulation");fspRunner(el,{onDone:done})}else if(r.kind==="sim"&&SAMPLE){simRunner(el,SIMS.find(x=>x.id===r.id),{onDone:()=>done()})}else{const t=TASKS[r.kind==="task"?r.id:(dayNumber()%TASKS.length)];freeText(el,t,{onDone:()=>done()})}}
  else if(s.t==="fluency"){const r=s.ref;if(r.kind==="432")talk432(el,r.topic,{onDone:done});else if(r.kind==="dict")dictationRunner(el,shadowLines(r.lesson).slice(0,4),{onDone:done});else if(r.kind==="shadowF"){const F=FAUST.find(x=>x.id===r.id);shadowRunner(el,F.lines.filter(l=>l[0]!=="— —").slice(0,6).map(l=>({de:l[0],en:l[1]})),{onDone:done})}else shadowRunner(el,shadowLines(r.lesson),{onDone:done})}
  else if(s.t==="culture"){const k=KULTUR[s.ref.idx];const idiom=IDIOMS[dayNumber()%IDIOMS.length];el.innerHTML=`<div class="head"><span class="pill kultur">Kultur · ${esc(k[2])}</span><h1>${esc(k[0])}</h1></div><div class="card" style="font-size:1.08rem;line-height:1.65">${esc(k[1])}</div><div class="card tint"><div class="row between"><div class="eyebrow">Redewendung des Tages <span class="en">idiom</span></div><button class="icon ghost" data-say="${esc(idiom[0])}">${ic("vol")}</button></div><div style="font-family:var(--display);font-size:1.35rem;font-style:italic;margin:.4rem 0 .2rem">„${esc(idiom[0])}“</div><div class="fg2">${esc(idiom[1])}</div></div><button class="primary ku-ok">Gelesen</button>`;$(".ku-ok",el).onclick=()=>{S.kultur[s.ref.idx]=true;done()}}
  }catch(e){logError(e);el.innerHTML=`<div class="crash">Dieser Schritt hat einen Fehler: ${esc(String(e&&e.message||e))}</div>`;done()}}
ACT.stepNext=()=>{const T=S.today;let nx=T.steps.findIndex((s,i)=>i>T.idx&&!s.done);if(nx<0)nx=T.steps.findIndex(s=>!s.done);T.idx=nx<0?T.steps.length:nx;saveSoon();runStep()};
ACT.stepSkip=()=>{const T=S.today;T.steps[T.idx].skipped=true;T.steps[T.idx].done=true;ACT.stepNext()};
ACT.stepBack=()=>{const T=S.today;if(T.idx>0){T.idx--;saveSoon();runStep()}};
function finishSession(){const T=S.today;KEYS=null;Focus.progress({n:T.steps.length,i:T.steps.length});Focus.title("Geschafft");Focus.tools("");studyTick();const mins=Math.max(1,minutesOn(todayKey()));if(!T.finished){T.finished=true;logDay("session");logEvent("session","Sitzung abgeschlossen · "+T.steps.filter(s=>s.done&&!s.skipped).length+" von "+T.steps.length+" Schritten · "+T.stats.cards+" Karten");saveNow();setTimeout(confetti,150)}
  const el=Focus.body();const sk=streak();const CHEER=["Es ist noch kein Meister vom Himmel gefallen.","Ich drücke dir die Daumen.","Halt die Ohren steif.","Morgenstund hat Gold im Mund.","Schwein gehabt!","Man sieht sich immer zweimal im Leben."];const idiom=IDIOMS.find(x=>x[0]===CHEER[dayNumber()%CHEER.length])||IDIOMS[0];
  el.innerHTML=`<div class="celebrate"><div class="eyebrow">${fmtDate(todayKey())} · Woche ${weekNumber()}</div><h1>Geschafft!</h1><p class="fg2" style="max-width:40ch">${sk>1?`Die Kerze brennt seit ${sk} Tagen.`:"Der erste Tag einer Serie."} ${dayNumber()<TOTAL_DAYS?`Noch ${TOTAL_DAYS-dayNumber()} Tage bis krankenhausreif.`:""}</p>
   <div class="stats" style="width:100%;max-width:460px"><div class="stat o"><b>${T.stats.cards}</b><span>Karten</span></div><div class="stat"><b>${mins}</b><span>${mins===1?"Minute":"Minuten"}</span></div><div class="stat"><b>${knownWords()}</b><span>Wörter im Deck</span></div></div>
   <div class="card tint" style="max-width:460px;width:100%;text-align:left"><div class="eyebrow">Zum Mitnehmen</div><div style="font-family:var(--display);font-size:1.25rem;font-style:italic;margin-top:.3rem">„${esc(idiom[0])}“</div><div class="fg2" style="font-size:.95rem">${esc(idiom[1])}</div></div>
   <p class="muted ui" style="font-size:.9rem">Heute noch Zeit? Ein echtes Gespräch auf Deutsch zählt mehr als jede weitere Karte.</p></div>`;
  Focus.foot(`<button class="primary" data-act="closeFocus">Bis morgen</button><button class="sm" data-act="extraRound">Extra-Runde Karten</button>`)}
ACT.extraRound=()=>{Focus.close(true);openCards()};
// ================= HOME =================
function greeting(){const h=new Date().getHours();return h<11?"Guten Morgen":h<18?"Guten Tag":"Guten Abend"}
function ring(p,label){const r=26,c=2*Math.PI*r;return `<svg class="ring" viewBox="0 0 64 64"><circle cx="32" cy="32" r="${r}" fill="none" stroke="rgba(255,255,255,.25)" stroke-width="6"/><circle cx="32" cy="32" r="${r}" fill="none" stroke="#fff" stroke-width="6" stroke-linecap="round" stroke-dasharray="${c}" stroke-dashoffset="${c*(1-p)}" transform="rotate(-90 32 32)"/><text x="32" y="37" text-anchor="middle" fill="#fff" font-size="15">${label}</text></svg>`}
function viewHome(m){const T=ensureSession();const w=WEEK();const done=T.steps.filter(s=>s.done).length,n=T.steps.length;const all=done===n;const f=FOCUS[S.focus];const nxt=T.steps.findIndex(s=>!s.done);const sk=streak(),ret=retention();
  if(LOAD_NOTE){toast(LOAD_NOTE,5000);LOAD_NOTE=""}
  m.innerHTML=`<div class="view fade-in">
  <div class="head"><div class="eyebrow">${fmtDate(todayKey())} · Tag ${Math.min(dayNumber(),TOTAL_DAYS)} von ${TOTAL_DAYS}</div><h1>${greeting()}${dayNumber()===1?"":"."}</h1></div>
  ${S.weekSeen<weekNumber()&&S.onboarded?`<div class="card tint stack s"><div class="row between"><div class="eyebrow">Neue Woche · Methode der Woche</div><button class="icon ghost" data-act="weekSeen" aria-label="Ausblenden">${ic("x")}</button></div><div style="font-size:1.02rem">${METHOD[(weekNumber()-1)%METHOD.length]}</div></div>`:""}
  <div class="hero"><div class="eyebrow">Woche ${weekNumber()} · Fokus ${esc(f.name)}</div><h1>${esc(w.theme)}</h1>
   <div class="ringrow">${ring(done/n,done+"/"+n)}<p>${all?"Heute ist erledigt. Morgen geht es weiter.":done?`Weiter bei Schritt ${nxt+1}: ${STRAND[T.steps[nxt].t].name}.`:esc(w.goal)}</p></div>
   <button class="go" data-act="${all?"extraRoundHome":"startSession"}"><span>${all?"Extra-Runde Karten":(done||T.started)?"Sitzung fortsetzen":"Heutige Sitzung starten"}<small>${all?"Fällige und neue Karten":done?`Schritt ${nxt+1} von ${n}`:`${n} Schritte · etwa ${T.minutes||S.minutes} Minuten${T.shift?" · Dienst-Modus":""}`}</small></span>${ic("chev")}</button></div>
  ${S.onboarded?"":`<div class="card raise stack s no-sig"><div class="eyebrow">Willkommen <span class="en">how this works</span></div><h2>Ein Knopf am Tag.</h2><div class="prose" style="margin:0"><ol style="margin-top:.3rem"><li><b>Heutige Sitzung</b> führt dich durch sechs kurze Schritte: Wiederholen, Neu lernen, Hören & Lesen, Schreiben & Sprechen, Flüssigkeit, Kultur.</li><li>Jeder Schritt speichert sofort. Du kannst jederzeit schließen und später weitermachen.</li><li><b>Lernen</b> ist die Bibliothek, <b>Üben</b> der Werkzeugkasten für Extra-Zeit, <b>Ich</b> zeigt Fortschritt und Einstellungen.</li></ol></div><div class="row"><button class="primary" data-act="onboardDone">Verstanden</button></div></div>`}
  ${coachHTML()}
  <div class="card"><div class="steps">${T.steps.map((s,i)=>{const inf=stepInfo(s);const curr=!s.done&&i===nxt;return `<button class="step ${s.done?"done":""} ${curr?"cur":""}" data-act="openStep" data-i="${i}"><span class="ic">${s.done?ic("check"):ic(inf.icon)}</span><span class="t"><b>${esc(inf.name)}</b><small>${esc(inf.sub)}</small></span><span class="st">${s.skipped?"übersprungen":s.done?"":curr?"jetzt":""}</span></button>`}).join("")}</div></div>
  <div class="stats"><div class="stat o"><b>${sk}</b><span>${sk===1?"Tag":"Tage"} Kerze</span></div><div class="stat"><b>${dueKeys().length}</b><span>Karten fällig</span></div><div class="stat"><b>${ret==null?"–":ret+"%"}</b><span>Behalten (30 T)</span></div></div>
  <div class="row between"><span class="muted ui" style="font-size:.85rem">Heute ${minutesOn(todayKey())} Min. gelernt${S.restDays?" · 1 Ruhetag pro Woche hält die Kerze":""}</span><button class="sm ghost" data-act="toggleShift">${S.shifts&&S.shifts[todayKey()]?ic("check")+" Dienst heute":ic("timer")+" Heute Dienst?"}</button></div>
  </div>`}
ACT.startSession=()=>openSession();ACT.openStep=el=>openSession(+el.dataset.i);ACT.extraRoundHome=()=>openCards();
ACT.onboardDone=()=>{S.onboarded=true;S.weekSeen=weekNumber();saveSoon();rerender()};ACT.weekSeen=()=>{S.weekSeen=weekNumber();saveSoon();rerender()};
// ================= LEARN =================
const SEGS=[["klinik","Klinik","var(--klinik)"],["alltag","Alltag","var(--alltag)"],["grammatik","Grammatik","var(--gram)"],["lesen","Lesen","var(--read)"],["literatur","Literatur","var(--lit)"],["kino","Kino","var(--gram)"],["kultur","Kultur","var(--kult)"]];
let litSeg="leiter",kinoF="alle";
let learnQ="";
function viewLearn(m){if(!R.seg)R.seg=S.focus==="ankommen"?"alltag":S.focus==="literatur"?"literatur":"klinik";
  if(R.id){return learnDetail(m,R.id)}
  const wk=WEEK();const thisWeek=new Set([...wk.med,...wk.gram,...wk.alltag,...wk.texts,...wk.faust]);
  m.innerHTML=`<div class="view fade-in"><div class="head"><div class="eyebrow">Lernen <span class="en">library</span></div><h1>Bibliothek</h1></div>
   <div style="position:relative"><input class="lq" placeholder="Suchen: Thema, Lektion, Wort…" value="${esc(learnQ)}" style="padding-left:2.4rem"><span style="position:absolute;left:.75rem;top:50%;transform:translateY(-50%);color:var(--muted)">${ic("search")}</span></div>
   <div class="seg">${SEGS.map(([k,n,c])=>`<button class="${R.seg===k?"on":""}" data-act="seg" data-k="${k}"><i style="background:${c}"></i>${n}</button>`).join("")}</div><div class="lres"></div></div>`;
  const draw=()=>{const box=$(".lres",m);const q=learnQ.trim().toLowerCase();if(q.length>=2){const hits=[];const push=(id,title,sub,kind)=>{if((title+" "+sub).toLowerCase().includes(q))hits.push({id,title,sub,kind})};MEDL.forEach(l=>push(l.id,l.title,l.sub,"klinik"));ALLTAG.forEach(l=>push(l.id,l.title,l.sub,"alltag"));GRAMMAR.forEach(l=>push(l.id,l.title,l.sub,"grammatik"));TEXTS.forEach(t=>push(t.id,t.title,t.sub,"lesen"));FAUST.forEach(f=>push(f.id,f.title,f.scene,"literatur"));POEMS.forEach(f=>push(f.id,f.title,f.scene,"literatur"));LADDER.forEach(l=>push(l.id,l.t,l.a+" · "+l.lvl,"literatur"));const words=allCards().filter(c=>c.kind!=="satz"&&(c.de.toLowerCase().includes(q)||c.en.toLowerCase().includes(q))).slice(0,8);
      box.innerHTML=`<div class="list">${hits.map(h=>`<button class="li" data-go="learn" data-arg="id:${h.id}"><span class="pill ${h.kind}">${h.kind}</span><span class="t"><b>${esc(h.title)}</b><small>${esc(h.sub)}</small></span><span class="chev">${ic("chev")}</span></button>`).join("")}${words.map(c=>`<div class="li" style="cursor:default"><span class="t"><b>${deHTML(c.de)}</b><small>${esc(c.en)}</small></span><span class="m"><button class="icon ghost" data-say="${esc(c.de)}">${ic("vol")}</button>${S.cards[c.id]?`<span class="pill good">im Deck</span>`:`<button class="sm" data-act="addCard" data-id="${esc(c.id)}">${ic("plus")}</button>`}</span></div>`).join("")}</div>${!hits.length&&!words.length?`<div class="empty">Nichts gefunden.</div>`:""}`;return}
    box.innerHTML=segList(R.seg,thisWeek)};
  const inp=$(".lq",m);inp.oninput=()=>{learnQ=inp.value;draw()};draw()}
ACT.seg=el=>{R.seg=el.dataset.k;learnQ="";rerender()};
ACT.addCard=el=>{S.cards[el.dataset.id]=newState();introducedNew(false);saveSoon();el.outerHTML=`<span class="pill good">im Deck</span>`;toast("Ins Deck gelegt")};
function lessonMeta(id){const L=S.lessons[id];if(!L)return "";const due=L.due<=todayKey();return `<span class="pill ${due?"o":L.best>=80?"good":""}">${due?"fällig":L.best+" %"}</span>`}
function segList(seg,thisWeek){const row=(id,n,title,sub,meta)=>`<button class="li" data-go="learn" data-arg="id:${id}"><span class="n">${n}</span><span class="t"><b>${esc(title)}</b><small>${esc(sub)}</small></span><span class="m">${thisWeek.has(id)?'<span class="pill o">diese Woche</span>':""}${meta}</span></button>`;
  if(seg==="klinik")return `<div class="list">${MEDL.map((l,i)=>row(l.id,i+1,l.title,l.sub+" · W"+l.week,lessonMeta(l.id))).join("")}</div>`;
  if(seg==="alltag")return `<div class="list">${ALLTAG.map((l,i)=>row(l.id,i+1,l.title,l.sub+" · W"+l.week,lessonMeta(l.id))).join("")}</div>`;
  if(seg==="grammatik")return `<div class="list">${GRAMMAR.map((l,i)=>row(l.id,i,l.title,l.sub+" · W"+l.week,lessonMeta(l.id))).join("")}</div>`;
  if(seg==="lesen")return `<div class="list">${TEXTS.map(t=>row(t.id,t.level,t.title,t.sub+" · W"+t.week,S.read[t.id]?'<span class="pill good">gelesen</span>':"")).join("")}</div>`;
  if(seg==="literatur")return litList();
  if(seg==="kino")return kinoList();
  if(seg==="kultur")return `<div class="grid2">${KULTUR.map((k,i)=>`<div class="card stack s" style="border-top:4px solid var(--kult)"><div class="row between"><span class="pill kultur">${esc(k[2])}</span>${S.kultur[i]?`<span class="pill good">${ic("check")}</span>`:""}</div><h3>${esc(k[0])}</h3><p class="fg2" style="font-size:.97rem">${esc(k[1])}</p>${S.kultur[i]?"":`<button class="sm" data-act="kulturRead" data-i="${i}" style="justify-self:start">Gelesen</button>`}</div>`).join("")}</div>`;
  return ""}
ACT.kulturRead=el=>{S.kultur[el.dataset.i]=true;saveSoon();rerender()};
function litList(){const sub=`<div class="seg" style="margin-bottom:.8rem">${[["leiter","Leseleiter"],["gedichte","Gedichte"],["faust","Faust"]].map(([k,n])=>`<button class="${litSeg===k?"on":""}" data-act="litSeg" data-k="${k}">${n}</button>`).join("")}</div>`;
  if(litSeg==="gedichte")return sub+`<div class="list">${POEMS.map((p,i)=>`<button class="li" data-go="learn" data-arg="id:${p.id}"><span class="n">${i+1}</span><span class="t"><b>${esc(p.title)}</b><small>${esc(p.scene)} · ${p.lines.filter(l=>l[0]!=="— —").length} Zeilen</small></span><span class="m">${S.read[p.id]?'<span class="pill good">gelesen</span>':""}</span></button>`).join("")}</div><p class="muted ui" style="font-size:.85rem;margin-top:.8rem">Alle Gedichte sind gemeinfrei; die englischen Zeilen sind sinngemäße Arbeitsübersetzungen.</p>`;
  if(litSeg==="faust")return sub+`<div class="list">${FAUST.map((f,i)=>`<button class="li" data-go="learn" data-arg="id:${f.id}"><span class="n">${i+1}</span><span class="t"><b>${esc(f.title)}</b><small>${esc(f.scene)} · ${esc(f.speaker)} · W${f.week}</small></span><span class="m">${S.read[f.id]?'<span class="pill good">gelesen</span>':""}</span></button>`).join("")}</div><div class="card prose" style="margin-top:1rem"><div class="eyebrow">Vers-Primer</div>${VERSE_NOTES}</div>`;
  const st=S.lit||{};const groups=[["B1","A2–B1 · B1"],["B2","B2"],["C1","C1"],["C2","C2"]];const lv=l=>l.lvl.startsWith("A")||l.lvl.startsWith("B1")?"B1":l.lvl.startsWith("B2")?"B2":l.lvl.startsWith("C1")?"C1":"C2";
  return sub+`<div class="card tint stack s"><div class="eyebrow">Nach Faust <span class="en">a reading ladder from B1 to C2</span></div><p class="fg2" style="font-size:.97rem">Steig Stufe für Stufe. Kurze Texte zuerst, dann Novellen, dann Romane. Mit ${ic("steth")} markiert: Werke mit Medizin, Ärzten oder Krankheit im Zentrum.</p><details><summary class="ui" style="cursor:pointer;font-weight:700">Wie man echte Literatur liest</summary><div class="prose" style="margin-top:.4rem">${READ_TIPS}</div></details></div>`+groups.map(([g,label])=>`<div class="eyebrow" style="margin:1rem 0 .5rem">Stufe ${label}</div><div class="list">${LADDER.filter(l=>lv(l)===g).map(l=>`<button class="li" data-go="learn" data-arg="id:${l.id}"><span class="t"><b>${esc(l.t)}</b><small>${esc(l.a)} · ${l.y} · ${esc(l.form)}</small></span><span class="m">${l.med?`<span class="pill klinik">${ic("steth")}</span>`:""}${l.pd?'<span class="pill">gemeinfrei</span>':""}${st[l.id]==="done"?'<span class="pill good">gelesen</span>':st[l.id]==="now"?'<span class="pill o">lese ich</span>':st[l.id]==="list"?'<span class="pill">Liste</span>':""}</span></button>`).join("")}</div>`).join("")}
ACT.litSeg=el=>{litSeg=el.dataset.k;rerender()};
function kinoList(){const F=[["alle","Alle"],["medizin","Medizin"],["anfaenger","Einstieg"],["klassiker","Klassiker"],["literatur","Literatur"],["Serie","Serien"],["merk","Meine Liste"]];const st=S.kino||{};
  const list=KINO.filter(k=>kinoF==="alle"?true:kinoF==="Serie"?/Serie/.test(k.kind):kinoF==="merk"?st[k.id]==="merk":k.tags.includes(kinoF)).sort((a,b)=>lvlRank(a.lvl)-lvlRank(b.lvl));
  return `<div class="card tint stack s"><div class="eyebrow">Kino-Methode <span class="en">how to watch to learn</span></div><details><summary class="ui" style="cursor:pointer;font-weight:700">Sechs Regeln</summary><div class="prose" style="margin-top:.4rem">${KINO_METHOD}</div></details><div class="row ui muted" style="font-size:.88rem">${Object.values(st).filter(x=>x==="seen").length} gesehen · ${Object.values(st).filter(x=>x==="merk").length} auf der Liste</div></div>
  <div class="seg" style="margin:.8rem 0">${F.map(([k,n])=>`<button class="${kinoF===k?"on":""}" data-act="kinoF" data-k="${k}">${n}</button>`).join("")}</div>
  <div class="grid2">${list.map(filmCard).join("")||'<div class="empty">Noch nichts auf deiner Liste.</div>'}</div>`}
function filmCard(k){const st=(S.kino||{})[k.id];const cls=k.tags.includes("medizin")?"med":k.tags.includes("literatur")?"lit":k.tags.includes("anfaenger")?"anf":"";return `<div class="film ${cls}"><div class="row between"><span class="y">${esc(k.kind)} · ${esc(String(k.y))}</span><span class="pill">${esc(k.lvl)}</span></div><h3>${esc(k.t)}</h3><p style="font-size:.97rem">${esc(k.de)}</p><p class="muted ui" style="font-size:.85rem">${esc(k.en)}</p><div class="row"><button class="sm ${st==="seen"?"":"primary"}" data-act="kinoSeen" data-id="${k.id}">${st==="seen"?ic("check")+" Gesehen":"Gesehen"}</button><button class="sm" data-act="kinoMerk" data-id="${k.id}">${st==="merk"?ic("check")+" Auf der Liste":"Merken"}</button><button class="sm ghost" data-act="kinoDiary" data-id="${k.id}">${ic("pen")} Tagebuch</button></div></div>`}
ACT.kinoF=el=>{kinoF=el.dataset.k;rerender()};
ACT.kinoSeen=el=>{S.kino=S.kino||{};const id=el.dataset.id;if(S.kino[id]==="seen")delete S.kino[id];else{S.kino[id]="seen";logDay("kino");logEvent("kino","Gesehen: "+(KINO.find(x=>x.id===id)||{}).t);toast("Notiert. Schreib zwei Sätze ins Filmtagebuch?")}saveSoon();if(!Focus.isOpen())rerender();else el.outerHTML=`<span class="pill good">${ic("check")} gesehen</span>`};
ACT.kinoMerk=el=>{S.kino=S.kino||{};const id=el.dataset.id;if(S.kino[id]==="merk")delete S.kino[id];else if(S.kino[id]!=="seen")S.kino[id]="merk";saveSoon();rerender()};
ACT.kinoDiary=el=>{const k=KINO.find(x=>x.id===el.dataset.id);const box=Focus.open({title:"Filmtagebuch",sub:k.t});freeText(box,{t:"Filmtagebuch: "+k.t,task:"Vier Sätze: Worum geht es? Was hat dir gefallen oder nicht? Welche Szene bleibt dir? Würdest du den Film empfehlen?",ctx:"Filmtagebuch zu „"+k.t+"“ ("+k.y+"): "+k.de,reg:"persönlich, natürlich, Präteritum/Perfekt",check:["Worum es geht (ohne Spoiler)","Eigene Meinung mit Begründung","Eine Szene beschreiben","Empfehlung"]},{})};
function filmStep(el,k,done){el.innerHTML=`<div class="head"><div class="eyebrow">Filmabend <span class="en">meaning-focused input</span></div></div>${filmCard(k)}<div class="card prose">${KINO_METHOD}</div><div class="card row between"><div><b class="ui">Heute 20–30 Minuten geschaut?</b><div class="muted ui" style="font-size:.85rem">Deutsche Tonspur, deutsche Untertitel.</div></div><button class="primary fs-ok">Geschaut</button></div>`;const fin=()=>{S.kino=S.kino||{};S.kino[k.id]="seen";logDay("kino");logEvent("kino","Film geschaut: "+k.t);saveSoon();done()};$(".fs-ok",el).onclick=fin;
  el.addEventListener("click",e=>{const b=e.target.closest('[data-act="kinoDiary"]');if(!b||!el.contains(b))return;e.preventDefault();e.stopPropagation();e.stopImmediatePropagation();let d=$(".fs-diary",el);if(!d){d=document.createElement("div");d.className="fs-diary stack s";el.appendChild(d)}
    freeText(d,{t:"Filmtagebuch: "+k.t,task:"Vier Sätze: Worum geht es? Was hat dir gefallen oder nicht? Welche Szene bleibt dir? Würdest du den Film empfehlen?",ctx:"Filmtagebuch zu „"+k.t+"“ ("+k.y+"): "+k.de,reg:"persönlich, natürlich, Präteritum/Perfekt",check:["Worum es geht (ohne Spoiler)","Eigene Meinung mit Begründung","Eine Szene beschreiben","Empfehlung"]},{});
    d.insertAdjacentHTML("beforeend",`<div class="row" style="justify-content:flex-end"><button class="primary fs-fin">Tagebuch fertig · Schritt abschließen</button></div>`);$(".fs-fin",d).onclick=fin;d.scrollIntoView({behavior:"smooth",block:"start"})},true)}
function ladderView(el,L){const st=(S.lit||{})[L.id];const gk=glossKey(Object.fromEntries(L.words.map(w=>[w[0].replace(/^(der|die|das) /,""),w[1]])));
  el.innerHTML=`<div class="head"><div class="row"><span class="pill literatur">${esc(L.form)} · ${L.y}</span><span class="pill">${esc(L.lvl)}</span>${L.med?`<span class="pill klinik">${ic("steth")} Medizin</span>`:""}</div><h1>${esc(L.t)}</h1><p>${esc(L.a)}</p></div>
  <div class="card"><div class="eyebrow" style="margin-bottom:.4rem">Worum es geht <span class="en">graded intro, tap words</span></div><div class="reader" style="font-size:1.12rem" data-gk="${gk}">${glossify(L.intro)}</div><div class="row" style="margin-top:.5rem"><button class="sm ghost" data-say="${esc(L.intro)}">${ic("vol")} Vorlesen</button></div></div>
  <div class="grid2"><div class="card"><div class="eyebrow">Warum lesen</div><p style="margin-top:.3rem">${esc(L.why)}</p></div><div class="card"><div class="eyebrow">Was schwer ist</div><p style="margin-top:.3rem">${esc(L.hard)}</p></div></div>
  <div class="card stack s"><div class="eyebrow">Schlüsselwörter <span class="en">into your deck before you start</span></div><div class="list">${L.words.map((w,i)=>{const inDeck=(S.custom||[]).some(c=>c.de===w[0]);return `<div class="li" style="cursor:default"><span class="t"><b>${deHTML(w[0])}</b><small>${esc(w[1])}</small></span><span class="m"><button class="icon ghost" data-say="${esc(w[0])}">${ic("vol")}</button>${inDeck?'<span class="pill good">im Deck</span>':`<button class="sm" data-act="litWord" data-id="${L.id}" data-i="${i}">${ic("plus")}</button>`}</span></div>`}).join("")}</div></div>
  <div class="card stack s"><div class="eyebrow">Original</div><p class="fg2">${L.pd?"Gemeinfrei: den Originaltext gibt es kostenlos bei Projekt Gutenberg-DE oder Zeno.org, Hörbücher oft bei LibriVox. Für die erste Lektüre hilft eine kommentierte Reclam-Ausgabe.":"Urheberrechtlich geschützt: als Buch, in der Bibliothek (auch Onleihe) oder als Hörbuch."}</p><div class="row">${[["list","Auf meine Liste"],["now","Lese ich gerade"],["done","Gelesen"]].map(([k,n])=>`<button class="sm ${st===k?"primary":""}" data-act="litStatus" data-id="${L.id}" data-k="${k}">${st===k?ic("check")+" ":""}${n}</button>`).join("")}</div></div>
  <div class="card lt-diary"></div>`;
  freeText($(".lt-diary",el),{t:"Lesetagebuch",task:"Schreib drei bis fünf Sätze: Was ist im Kapitel passiert, welche Figur interessiert dich, welcher Satz ist dir geblieben?",ctx:"Lesetagebuch zu „"+L.t+"“ von "+L.a,reg:"persönlich, Präteritum für die Handlung",check:["Handlung im Präteritum","Eine Figur charakterisieren","Eigene Meinung"]},{})}
ACT.litWord=el=>{const L=LADDER.find(x=>x.id===el.dataset.id);const w=L.words[+el.dataset.i];S.custom.push({de:w[0],en:w[1],ex:L.a+": "+L.t,tag:"faust"});buildDict();S.cards["c:"+(S.custom.length-1)]=newState();saveSoon();el.outerHTML='<span class="pill good">im Deck</span>'};
ACT.litStatus=el=>{S.lit=S.lit||{};const id=el.dataset.id,k=el.dataset.k;if(S.lit[id]===k)delete S.lit[id];else{S.lit[id]=k;const LB=LADDER.find(x=>x.id===id);if(k==="done"){logDay("book");logEvent("book","Buch gelesen: "+(LB?LB.t:id));confetti()}else if(k==="now")logEvent("book","Angefangen: "+(LB?LB.t:id))}saveSoon();rerender()};
function learnDetail(m,id){m.innerHTML=`<div class="view fade-in"><div><button class="ghost sm" data-go="learn">${ic("back")} Bibliothek</button></div><div class="ld stack"></div></div>`;const el=$(".ld",m);
  const L=lessonById(id);if(L){lessonView(el,L,{});if(L.dialog&&L.dialog.length){const tools=document.createElement("div");tools.className="card row";tools.innerHTML=`<b class="ui" style="margin-right:auto">Mit diesem Dialog üben</b><button class="sm" data-act="shadowLesson" data-id="${id}">${ic("wave")} Schattensprechen</button><button class="sm" data-act="dictLesson" data-id="${id}">${ic("type")} Diktat</button>`;el.insertBefore(tools,$(".ls-quiz",el))}return}
  const lad=LADDER.find(x=>x.id===id);if(lad){ladderView(el,lad);return}
  const item=TEXTS.find(x=>x.id===id)||FAUST.find(x=>x.id===id)||POEMS.find(x=>x.id===id);if(item){readerView(el,item,{});if(item.lines){const b=document.createElement("div");b.className="row";b.innerHTML=`<button class="sm" data-act="shadowFaust" data-id="${id}">${ic("wave")} Schattensprechen</button>`;el.appendChild(b)}return}
  el.innerHTML=`<div class="empty">Nicht gefunden.</div>`}
ACT.shadowLesson=el=>{const lines=shadowLines(el.dataset.id);shadowRunner(Focus.open({title:"Schattensprechen",sub:(lessonById(el.dataset.id)||{}).title}),lines,{})};
ACT.dictLesson=el=>{dictationRunner(Focus.open({title:"Diktat",sub:(lessonById(el.dataset.id)||{}).title}),shadowLines(el.dataset.id).slice(0,5),{})};
ACT.shadowFaust=el=>{const F=FAUST.find(x=>x.id===el.dataset.id)||POEMS.find(x=>x.id===el.dataset.id);shadowRunner(Focus.open({title:"Schattensprechen",sub:F.title}),F.lines.filter(l=>l[0]!=="— —").map(l=>({de:l[0],en:l[1]})),{})};
