function openCards(tag){const q=tag?buildQueue({due:false,tag}):buildQueue();cardRunner(Focus.open({title:"Karten",sub:tag?"Neue Karten":"Fällige und neue"}),q,{standalone:true})}
function viewPractice(m){const due=dueKeys().length;resetNewToday();const nw=Math.max(0,S.newPerDay-S.newToday.n);const E=Object.entries(S.errors||{}).sort((a,b)=>b[1]-a[1]);const hard=Object.keys(S.cards).filter(k=>S.cards[k].lapses>=2&&card(k.replace(/^p:/,""))).length;
  const counts={core:0,med:0,alltag:0,faust:0,satz:0,custom:0},tot={core:0,med:0,alltag:0,faust:0,satz:0,custom:0};allCards().forEach(c=>{const t=c.kind==="satz"?"satz":c.tag;tot[t]=(tot[t]||0)+1;if(S.cards[c.id])counts[t]=(counts[t]||0)+1});
  const tile=(act,icon,title,sub,extra,cls)=>`<button class="tile ${cls||""}" data-act="${act}" ${extra||""}><span class="ic">${ic(icon)}</span><b>${title}</b><small>${sub}</small></button>`;
  m.innerHTML=`<div class="view fade-in"><div class="head"><div class="eyebrow">Üben <span class="en">toolbox for extra time</span></div><h1>Werkzeugkasten</h1></div>
  <div class="tiles"><button class="tile big" data-act="cards"><span class="ic">${ic("cards")}</span><span><b style="display:block">Karten</b><small>${due} fällig · ${nw} neu heute</small></span>${ic("chev")}</button></div>
  <div class="eyebrow">Prüfungen <span class="en">exam training & mock tests</span></div>
  <div class="tiles">${["goethe","telc","med"].map(ex=>{const E=EXAMS[ex];const sc=E.mods.map(md=>modScore(ex,md.m)).filter(x=>x!=null);const avg=sc.length?Math.round(sc.reduce((a,b)=>a+b,0)/sc.length):null;return `<button class="tile" data-act="examHub" data-ex="${ex}"><span class="ic" style="background:color-mix(in srgb,${E.color} 18%,transparent);color:${E.color}">${ic("target")}</span><b>${esc(E.short)}</b><small>${avg==null?"Format, Übungen, Modelltests":"Ø "+avg+" % · Grenze 60 %"}</small></button>`}).join("")}${tile("fsp","steth","FSP Ärztekammer","3 × 20 Minuten",'',"tutor")}</div>
  <div class="eyebrow">Schreiben &amp; Sprechen <span class="en">output</span></div>
  <div class="tiles">${tile("write","pen","Schreiben",SAMPLE?"Mit Korrektur durch Claude":"Mit Musterlösung")}${tile("roleplay","chat","Rollenspiel","Patient, Oberarzt, Amt…",'',"tutor need-tutor")}${tile("talk","timer","4 / 3 / 2","Dreimal erzählen, schneller")}</div>
  <p class="muted ui tutor-off" style="font-size:.88rem">Ohne Claude prüft der Offline-Coach deine Texte auf die 2–3 wichtigsten Fehler. Für freie Rollenspiele und volle Korrektur: öffne die claude.ai-Version oder trag deinen API-Schlüssel ein. <span class="en">offline coach checks key errors; Claude gives full correction</span></p>
  <div class="eyebrow">Hören <span class="en">listening & pronunciation</span></div>
  <div class="tiles">${tile("shadow","wave","Schattensprechen","Nachsprechen im Rhythmus")}${tile("dict","type","Diktat",TTS_OK?"Hören und schreiben":"Aus dem Gedächtnis")}${SR?tile("pronCheck","mic","Aussprache prüfen","Sprich, das Handy hört zu"):""}${tile("pron","ear","Aussprache-Lektion","p/b, ü/ö, Konsonanten")}</div>
  <div class="eyebrow">Drills <span class="en">quick, focused</span></div>
  <div class="tiles">${tile("blitz","bolt","Artikel-Blitz","60 Sekunden, Rekord "+(S.blitzBest||0))}${tile("numbers","timer","Zahlen im Dienst","RR, Laborwerte, Dosen hören")}${tile("terms","steth","Begriffe","Laie ↔ Fachsprache")}${tile("drill","grid","Artikel","der · die · das",'data-k="artikel"')}${tile("drill","grid","Fälle","Akk., Dat., Gen.",'data-k="faelle"')}${tile("drill","grid","Verben","Präsens, Präteritum",'data-k="verben"')}${tile("drill","steth","Antwort-Drill","Patient sagt…",'data-k="respond"')}${tile("drill","book","Abkürzungen","V.a., Z.n., o.B.…",'data-k="abbr"')}${tile("drill","flame","Faust-Lücken","Goethe ergänzen",'data-k="cloze"')}</div>
  <div class="card stack s"><div class="row between"><h3>Schwachstellen</h3><span class="muted ui">${E.reduce((a,b)=>a+b[1],0)} Fehler erfasst</span></div>
   ${E.length?`<div class="list">${E.slice(0,5).map(([t,n])=>`<div class="li" style="cursor:default"><span class="t"><b>${esc(t)}</b><small>${ERR_LESSON[t]?esc((lessonById(ERR_LESSON[t])||{}).title||""):"Sammle die Sätze im Deck"}</small></span><span class="m"><span class="pill grammatik">${n}</span>${ERR_LESSON[t]?`<button class="sm ghost" data-go="learn" data-arg="id:${ERR_LESSON[t]}">Lektion</button>`:""}${typeof ERR_RULE!=="undefined"&&ERR_RULE[t]?`<button class="sm ghost" data-act="explain" data-k="${ERR_RULE[t]}">Regel</button>`:""}<button class="sm need-tutor" data-act="errDrill" data-t="${esc(t)}">5 Aufgaben</button></span></div>`).join("")}</div>`:`<p class="muted">Noch leer. Getippte Karten, Korrekturen und Rollenspiele füllen es; dann stehen hier deine häufigsten Fehlertypen mit passenden Übungen.</p>`}
   ${hard?`<button class="sm" data-act="hardCards" style="justify-self:start">${ic("target")} ${hard} schwierige Karten üben</button>`:""}</div>
  <div class="card stack s"><h3>Deck</h3><div class="list">${[["satz","Sätze aus Lektionen"],["core","Kernwortschatz"],["med","Klinik"],["alltag","Alltag"],["faust","Literatur"]].map(([k,n])=>`<div class="li" style="cursor:default"><span class="t"><b>${n}</b><small>${counts[k]||0} von ${tot[k]||0} gelernt${k==="satz"?" · werden mit jeder Lektion freigeschaltet":""}</small></span><span class="m"><button class="sm" data-act="newTag" data-k="${k}">${ic("plus")} Neue</button></span></div>`).join("")}</div>
   <details><summary class="ui" style="cursor:pointer;font-weight:700;padding:.3rem 0">Eigene Karte anlegen</summary><div class="stack s" style="margin-top:.6rem"><input class="cc-de" placeholder="Deutsch (Nomen mit Artikel)"><input class="cc-en" placeholder="Englisch"><input class="cc-ex" placeholder="Beispielsatz (optional)"><button class="sm primary cc-add" style="justify-self:start">Anlegen</button></div></details></div></div>`;
  const add=$(".cc-add",m);add.onclick=()=>{const de=$(".cc-de",m).value.trim(),en=$(".cc-en",m).value.trim();if(!de||!en)return toast("Deutsch und Englisch eingeben");S.custom.push({de,en,ex:$(".cc-ex",m).value.trim()});buildDict();S.cards["c:"+(S.custom.length-1)]=newState();saveSoon();toast("Karte angelegt");rerender()}}
ACT.cards=()=>openCards();
ACT.newTag=el=>{const k=el.dataset.k;if(k==="satz"){const q=newPool().filter(c=>c.kind==="satz").map(c=>({key:c.id,id:c.id,mode:"rec",isNew:true}));if(!q.length)return toast("Schließ eine Klinik- oder Alltagslektion ab, um Satzkarten freizuschalten.",3500);cardRunner(Focus.open({title:"Karten",sub:"Sätze"}),q,{standalone:true});return}openCards(k)};
ACT.hardCards=()=>{const q=Object.keys(S.cards).filter(k=>S.cards[k].lapses>=2&&card(k.replace(/^p:/,""))).slice(0,30).map(k=>({key:k,id:k.replace(/^p:/,""),mode:k.startsWith("p:")?"prod":"rec"}));cardRunner(Focus.open({title:"Schwierige Karten"}),shuffle(q),{standalone:true})};
ACT.write=()=>{const el=Focus.open({title:"Schreiben"});const today=dayNumber()%TASKS.length;el.innerHTML=`<div class="head"><div class="eyebrow">Aufgabe wählen <span class="en">pick a task</span></div></div><div class="list">${TASKS.map((t,i)=>`<button class="li" data-act="pickTask" data-i="${i}"><span class="pill ${t.k}">${t.k}</span><span class="t"><b>${esc(t.t)}</b><small>${esc(t.task)}</small></span>${i===today?'<span class="pill o">heute</span>':""}</button>`).join("")}</div>`};
ACT.pickTask=el=>{const t=TASKS[+el.dataset.i];Focus.title("Schreiben",t.t);freeText(Focus.body(),t,{})};
ACT.roleplay=()=>{if(!SAMPLE)return toast("Rollenspiel braucht Claude: öffne den claude.ai-Link dieser Seite.",4000);const el=Focus.open({title:"Rollenspiel"});el.innerHTML=`<div class="head"><div class="eyebrow">Mit wem sprichst du? <span class="en">pick a counterpart</span></div><p>Schreib in ganzen Sätzen. Antworten werden vorgelesen. Am Ende: Bewertung und Fehler ins Log.</p></div><div class="list">${SIMS.map(s=>`<button class="li" data-act="pickSim" data-id="${s.id}"><span class="pill ${s.k}">${s.k}</span><span class="t"><b>${esc(s.name)}</b><small>${esc(s.who)}</small></span><span class="chev">${ic("chev")}</span></button>`).join("")}</div>`};
ACT.pickSim=el=>{const s=SIMS.find(x=>x.id===el.dataset.id);Focus.title("Rollenspiel",s.name);simRunner(Focus.body(),s,{})};
ACT.fsp=()=>{fspRunner(Focus.open({title:"FSP-Simulation",sub:"Teil 1"}),{})};
ACT.talk=()=>{const pool=TALKS[S.focus==="ankommen"?"alltag":"klinik"].concat(TALKS[S.focus==="ankommen"?"klinik":"alltag"]);const el=Focus.open({title:"4 / 3 / 2"});el.innerHTML=`<div class="head"><div class="eyebrow">Thema wählen <span class="en">same story, three times, faster</span></div><p>Erzähl dasselbe in vier, dann drei, dann zwei Minuten. Die bekannteste Technik für Sprechflüssigkeit; genau das brauchst du für die Patientenvorstellung.</p></div><div class="list">${pool.map((t,i)=>`<button class="li" data-act="pickTalk" data-i="${i}"><span class="t"><b style="font-family:var(--body);font-weight:400">${esc(t)}</b></span><span class="chev">${ic("chev")}</span></button>`).join("")}</div>`;ACT.pickTalk=b=>talk432(Focus.body(),pool[+b.dataset.i],{})};
ACT.shadow=()=>{shadowRunner(Focus.open({title:"Schattensprechen"}),shadowLines(null),{})};
ACT.dict=()=>{dictationRunner(Focus.open({title:"Diktat"}),shuffle(shadowLines(null)).slice(0,5),{})};
ACT.pron=()=>{go("learn","id:g0")};
