// ================= PHONE FEATURES (v10): speech check, Artikel-Blitz, numbers, terms, undo, haptics, coach, PWA =================
const APP_VERSION="13.1.0";
const IS_PWA=!!window.MEPHISTO_PWA;
const IS_STANDALONE=(()=>{try{return matchMedia("(display-mode: standalone)").matches||navigator.standalone===true}catch(e){return false}})();
const IS_IOS=/iPhone|iPad|iPod/.test(navigator.userAgent)||(navigator.platform==="MacIntel"&&navigator.maxTouchPoints>1);
const APP_URL="https://mephisto-deutsch.github.io/Mephisto/";
// ---------- feedback: haptics + soft chime
let AC=null;
function chime(ok){if(!S.sound)return;try{AC=AC||new (window.AudioContext||window.webkitAudioContext)();const t=AC.currentTime;const o=AC.createOscillator(),g=AC.createGain();o.type="sine";o.frequency.setValueAtTime(ok?880:220,t);if(ok)o.frequency.exponentialRampToValueAtTime(1320,t+.12);g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(.12,t+.015);g.gain.exponentialRampToValueAtTime(.0001,t+(ok?.22:.3));o.connect(g).connect(AC.destination);o.start(t);o.stop(t+.32)}catch(e){}}
function fb(ok){if(S.haptic){try{navigator.vibrate&&navigator.vibrate(ok?12:[25,40,25])}catch(e){}}chime(ok)}
// ---------- wake lock while a session or tool is open
let WL=null;
async function wakeOn(){try{if("wakeLock" in navigator&&!WL){WL=await navigator.wakeLock.request("screen");WL.addEventListener("release",()=>{WL=null})}}catch(e){WL=null}}
function wakeOff(){try{if(WL){WL.release();WL=null}}catch(e){}}
document.addEventListener("visibilitychange",()=>{if(document.visibilityState==="visible"&&Focus.isOpen())wakeOn()});
// ---------- speech recognition (device-side, de-DE)
const SR=window.SpeechRecognition||window.webkitSpeechRecognition||null;
if(SR)document.documentElement.classList.add("has-sr");
let SR_ACTIVE=null;
function listen(o){o=o||{};return new Promise((res,rej)=>{if(!SR)return rej({code:"unsupported"});try{if(SR_ACTIVE)SR_ACTIVE.abort()}catch(e){}stopSpeech();const r=new SR();SR_ACTIVE=r;r.lang="de-DE";r.interimResults=true;r.continuous=!!o.continuous;r.maxAlternatives=3;let fin="",cur="";
  r.onresult=e=>{fin="";cur="";for(let i=0;i<e.results.length;i++){const x=e.results[i];if(x.isFinal)fin+=x[0].transcript+" ";else cur+=x[0].transcript}if(o.onPartial)o.onPartial((fin+cur).trim())};
  r.onerror=e=>{SR_ACTIVE=null;rej({code:e.error||"error"})};r.onend=()=>{SR_ACTIVE=null;res((fin+cur).trim())};try{r.start()}catch(e){rej({code:"start"})}})}
function srMsg(code){return code==="not-allowed"||code==="service-not-allowed"?"Mikrofon nicht erlaubt. In der installierten App bzw. in Safari/Chrome freigeben.":code==="no-speech"?"Nichts gehört. Noch einmal, etwas lauter.":code==="unsupported"?"Spracherkennung gibt es auf diesem Gerät nicht.":code==="network"?"Spracherkennung braucht hier eine Internetverbindung.":"Spracherkennung unterbrochen."}
function micListen(btn,o){if(SR_ACTIVE){try{SR_ACTIVE.stop()}catch(e){}return Promise.resolve(null)}btn.classList.add("rec");const label=btn.innerHTML;if(!btn.classList.contains("icon"))btn.innerHTML=ic("mic")+" Hört zu…";return listen(o).then(t=>{btn.classList.remove("rec");btn.innerHTML=label;return t}).catch(e=>{btn.classList.remove("rec");btn.innerHTML=label;if(e&&e.code!=="aborted")toast(srMsg(e&&e.code),3500);return null})}
function dictateInto(btn,ta,after){const base=ta.value?ta.value.replace(/\s*$/," "):"";micListen(btn,{onPartial:t=>{ta.value=base+t;ta.dispatchEvent(new Event("input",{bubbles:true}))}}).then(t=>{if(t!=null){ta.value=base+t;ta.dispatchEvent(new Event("input",{bubbles:true}));if(after)after(t)}})}
function speakCheck(btn,target,out){micListen(btn,{onPartial:t=>{out.innerHTML=`<div class="verdict"><span class="muted ui">${esc(t)}</span></div>`}}).then(t=>{if(t==null)return;const s=similarity(t,target);const pct=Math.round(s*100);fb(pct>=80);logDay("speak");logEvent("speak","Aussprache · "+pct+" % · „"+target.slice(0,50)+"“",pct);
  out.innerHTML=`<div class="verdict ${pct>=80?"ok":"no"}" data-noxp="1"><div class="row between"><b class="ui">${pct>=90?"Sehr klar.":pct>=80?"Gut verständlich.":pct>=60?"Fast. Achte auf die rot markierten Wörter.":"Noch einmal, langsamer."}</b><span class="pill ${pct>=80?"good":"o"}">${pct} %</span></div><div style="font-size:1.05rem">${wordDiff(t,target)}</div>${pct<90&&typeof pronHelp==="function"?pronHelp(t,target):""}<div class="muted ui" style="font-size:.8rem">Grün: erkannt · rot durchgestrichen: anders gehört · grün hinterlegt: nicht gehört. Die Erkennung prüft Verständlichkeit, nicht deinen Akzent.</div></div>`})}
// ---------- snackbar with undo
let SNACK_T=null;
function snack(msg,label,fn,ms){const el=$("#snack");if(!el)return;el.innerHTML=`<span>${esc(msg)}</span>${label?`<button class="sm">${esc(label)}</button>`:""}`;el.hidden=false;void el.offsetWidth;el.classList.add("show");clearTimeout(SNACK_T);const b=el.querySelector("button");if(b)b.onclick=()=>{hideSnack();fn&&fn()};SNACK_T=setTimeout(hideSnack,ms||5000)}
function hideSnack(){const el=$("#snack");if(!el)return;el.classList.remove("show");clearTimeout(SNACK_T);setTimeout(()=>{if(!el.classList.contains("show"))el.hidden=true},250)}
// ---------- streak with rest days and shifts
function weekKey(k){const [y,m,d]=k.split("-").map(Number);const dt=new Date(y,m-1,d);const day=(dt.getDay()+6)%7;dt.setDate(dt.getDate()-day);return keyOf(dt)}
streak=function(){let n=0,k=todayKey();const has=x=>S.log[x]&&S.log[x].act;const shift=x=>S.shifts&&S.shifts[x];const used={};if(!has(k))k=addDays(k,-1);let guard=0;
  while(guard++<800){if(has(k)){n++;k=addDays(k,-1);continue}if(shift(k)){k=addDays(k,-1);continue}const wk=weekKey(k);if(S.restDays&&!used[wk]&&has(addDays(k,-1))){used[wk]=1;k=addDays(k,-1);continue}break}return n};
function toggleShift(){S.shifts=S.shifts||{};const t=todayKey();if(S.shifts[t])delete S.shifts[t];else S.shifts[t]=1;saveSoon();toast(S.shifts[t]?"Dienst eingetragen: Die Kerze ist heute geschützt.":"Dienst entfernt");rerender()}
ACT.toggleShift=toggleShift;
// ---------- Artikel-Blitz: 60 seconds of der / die / das
function blitz(el){const nouns=VOCAB.filter(x=>x[2]==="n"&&/^(der|die|das) /.test(x[0])&&x[4]!=="faust");let pool=shuffle(nouns),pi=0,score=0,combo=0,best=0,left=60,run=false,missed=[],cur=null,t=null,lock=false;
  const pick=()=>{if(pi>=pool.length){pool=shuffle(nouns);pi=0}cur=pool[pi++]};
  function intro(){el.innerHTML=`<div class="celebrate fade-in"><div class="eyebrow">Artikel-Blitz <span class="en">60 seconds · der · die · das</span></div><h1>Wie viele schaffst du?</h1><p class="fg2" style="max-width:40ch">Tippe den Artikel. Oder wische: <b class="g-der">links der</b> · <b class="g-das">unten das</b> · <b class="g-die">rechts die</b>. Tasten 1 · 2 · 3.</p><p class="muted ui">Rekord: ${S.blitzBest||0}</p><button class="primary bz-go" style="min-height:56px;padding:0 2rem">${ic("bolt")} Los</button></div>`;$(".bz-go",el).onclick=start}
  function start(){score=0;combo=0;best=0;left=60;missed=[];run=true;pick();draw();t=every(()=>{left--;const x=$(".bz-t",el);if(x){x.textContent=left;x.parentElement.style.setProperty("--p",(left/60*100)+"%")}if(left<=0){clearInterval(t);end()}},1000)}
  function draw(){const noun=cur[0].replace(/^(der|die|das) /,"");el.innerHTML=`<div class="bz"><div class="row between"><div class="bz-timer" style="--p:${left/60*100}%"><b class="bz-t">${left}</b></div><div class="ui" style="text-align:right"><b style="font-family:var(--display);font-size:1.8rem">${score}</b><div class="muted" style="font-size:.8rem">${combo>=3?`${ic("flame")} ${combo}er-Serie`:"Punkte"}</div></div></div>
    <div class="bz-card"><div class="bz-word">${esc(noun)}</div><div class="muted ui">${esc(cur[1])}</div><div class="bz-fb"></div></div>
    <div class="bz-btns"><button class="bz-b der" data-a="der">der</button><button class="bz-b das" data-a="das">das</button><button class="bz-b die" data-a="die">die</button></div></div>`;
    $$(".bz-b",el).forEach(b=>b.onclick=()=>answer(b.dataset.a));swipe($(".bz-card",el))}
  function answer(a){if(!run||lock)return;const want=cur[0].split(" ")[0];const ok=a===want;fb(ok);if(ok){combo++;best=Math.max(best,combo);score+=1+(combo>=5?1:0);pick();draw()}else{combo=0;missed.push(cur);lock=true;const f=$(".bz-fb",el);if(f)f.innerHTML=`<div class="verdict no" style="margin-top:.6rem"><b class="g-${want}">${want}</b> ${esc(cur[0].slice(want.length+1))} · <span class="muted">${genderWhy(cur[0].slice(want.length+1),want).replace(/<[^>]+>/g,"")}</span></div>`;setTimeout(()=>{lock=false;if(run){pick();draw()}},1100)}}
  function swipe(card){let x0=null,y0=null;card.addEventListener("pointerdown",e=>{x0=e.clientX;y0=e.clientY});card.addEventListener("pointerup",e=>{if(x0==null)return;const dx=e.clientX-x0,dy=e.clientY-y0;x0=null;if(Math.max(Math.abs(dx),Math.abs(dy))<50)return;if(Math.abs(dx)>Math.abs(dy))answer(dx<0?"der":"die");else if(dy>0)answer("das")})}
  function end(){run=false;KEYS=null;const rec=score>(S.blitzBest||0);if(rec){S.blitzBest=score;confetti()}logDay("drill");logEvent("blitz","Artikel-Blitz · "+score+" Punkte"+(rec?" (Rekord)":""),score);saveSoon();const uniq=[...new Map(missed.map(m=>[m[0],m])).values()];
    el.innerHTML=`<div class="celebrate fade-in"><div class="eyebrow">Zeit um</div><h1>${score} Punkte</h1><p class="fg2">${rec?"Neuer Rekord!":"Rekord: "+S.blitzBest} · längste Serie ${best}</p></div>${uniq.length?`<div class="card stack s"><div class="eyebrow">Verwechselt</div><div class="list">${uniq.map(m=>{const id="w:"+m[0];return `<div class="li" style="cursor:default"><span class="t"><b>${deHTML(m[0])}</b><small>${esc(m[1])}${typeof genderWhy==="function"&&/^(der|die|das) /.test(m[0])?" · "+genderWhy(m[0].split(" ").slice(1).join(" "),m[0].split(" ")[0]):""}</small></span><span class="m">${S.cards[id]?'<span class="pill good">im Deck</span>':`<button class="sm" data-act="addCard" data-id="${esc(id)}">${ic("plus")}</button>`}</span></div>`}).join("")}</div>${typeof xpBtn==="function"?xpBtn("genus","Die Regeln"):""}</div>`:""}<div class="row" style="justify-content:center"><button class="primary bz-again">${ic("bolt")} Nochmal</button></div>`;$(".bz-again",el).onclick=start}
  KEYS=e=>{if(!run)return;if(e.key==="1"||e.key==="ArrowLeft")answer("der");else if(e.key==="2"||e.key==="ArrowDown")answer("das");else if(e.key==="3"||e.key==="ArrowRight")answer("die")};
  intro()}
ACT.blitz=()=>blitz(Focus.open({title:"Artikel-Blitz",sub:"der · die · das"}));
// ---------- Zahlen im Dienst: numbers and units by ear
const MON=["Januar","Februar","März","April","Mai","Juni","Juli","August","September","Oktober","November","Dezember"];
const rnd=(a,b)=>a+Math.floor(Math.random()*(b-a+1));
function numItem(){const k=rnd(0,9);if(k===0){const a=rnd(9,22)*10,b=rnd(5,12)*10;return {say:`Der Blutdruck ist ${a} zu ${b}.`,ans:`${a}/${b}`,hint:"RR, z. B. 140/90",alt:[`${a} ${b}`,`${a}-${b}`]}}
  if(k===1){const n=rnd(42,168);return {say:`Puls ${n} pro Minute.`,ans:String(n),hint:"Herzfrequenz"}}
  if(k===2){const a=rnd(35,40),d=rnd(0,9);return {say:`Die Temperatur ist ${a},${d} Grad.`,ans:`${a},${d}`,hint:"°C, mit Komma"}}
  if(k===3){const a=rnd(6,16),d=rnd(0,9);return {say:`Das Hämoglobin liegt bei ${a},${d}.`,ans:`${a},${d}`,hint:"Hb in g/dl"}}
  if(k===4){const n=[25,50,100,125,250,400,500,600,1000][rnd(0,8)];return {say:`Geben Sie ${n} Milligramm.`,ans:String(n),hint:"Dosis in mg"}}
  if(k===5){const d=rnd(1,28),m=rnd(0,11);return {say:`Der Termin ist am ${d}. ${MON[m]}.`,ans:`${pad(d)}.${pad(m+1)}.`,hint:"Datum TT.MM.",alt:[`${d}.${m+1}.`,`${d}.${m+1}`,`${pad(d)}.${pad(m+1)}`]}}
  if(k===6){const h=rnd(6,23),mi=[0,15,30,45,10,20,40,50][rnd(0,7)];return {say:mi?`Die Visite ist um ${h} Uhr ${mi}.`:`Die Visite ist um ${h} Uhr.`,ans:`${pad(h)}:${pad(mi)}`,hint:"Uhrzeit HH:MM",alt:[`${h}:${pad(mi)}`,`${h}.${pad(mi)}`]}}
  if(k===7){const n=rnd(2000,8999);return {say:`Meine Durchwahl ist ${String(n).split("").join(" ")}.`,ans:String(n),hint:"Telefon-Durchwahl"}}
  if(k===8){const n=rnd(82,100);return {say:`Die Sättigung liegt bei ${n} Prozent.`,ans:String(n),hint:"SpO₂ in %"}}
  const n=rnd(3,35),d=rnd(0,9);return {say:`Das Kalium ist ${Math.min(n,7)},${d}.`,ans:`${Math.min(n,7)},${d}`,hint:"mmol/l, mit Komma"}}
const normNum=s=>String(s||"").toLowerCase().replace(/\s+/g,"").replace(/\.(?=\d)/g,",").replace(/uhr|grad|mg|prozent|%|°c?/g,"").replace(/,$/,"").replace(/^0(?=\d)/,"");
function numbersRunner(el){const N=10;let i=0,right=0,it=null;
  if(!TTS_OK){el.innerHTML=`<div class="empty"><div class="big">M</div><p>Dieser Drill braucht Sprachausgabe. Öffne die App bzw. den Link in Safari oder Chrome.</p></div>`;return}
  function step(){if(i>=N){el.innerHTML=`<div class="celebrate fade-in"><div class="eyebrow">Zahlen im Dienst</div><h1>${right} / ${N}</h1><p class="fg2">${right>=8?"Sitzt. Morgen etwas schneller (Tempo in den Einstellungen).":"Zahlen sind am Telefon am schwersten. Morgen nochmal."}</p><button class="primary nm-again">Nochmal</button></div>`;$(".nm-again",el).onclick=()=>{i=0;right=0;step()};logDay("drill");logEvent("drill","Zahlen im Dienst · "+right+"/"+N,Math.round(100*right/N));KEYS=null;return}
    it=numItem();el.innerHTML=`<div class="head"><div class="eyebrow">Zahl ${i+1} / ${N} <span class="en">listen and type the number</span></div></div><div class="card raise" style="text-align:center;padding:1.6rem"><button class="primary nm-play" style="min-height:64px;padding:0 1.8rem">${ic("vol")} Abspielen</button><div class="row" style="justify-content:center;margin-top:.6rem"><button class="sm ghost nm-slow">Langsam</button></div><p class="muted ui" style="margin-top:.6rem">${esc(it.hint)}</p></div><div class="typed"><input class="nm-in" inputmode="decimal" autocomplete="off" placeholder="z. B. ${esc(it.hint.includes("RR")?"140/90":it.hint.includes("Uhr")?"14:30":it.hint.includes("Datum")?"14.03.":"38,5")}"><button class="primary nm-chk">Prüfen</button></div><div class="nm-out"></div>`;
    $(".nm-play",el).onclick=()=>say(it.say);$(".nm-slow",el).onclick=()=>say(it.say,{rate:.72});setTimeout(()=>say(it.say,{silent:true}),250);const inp=$(".nm-in",el);setTimeout(()=>inp.focus(),300);let done=false;
    const chk=()=>{if(done){i++;step();return}done=true;const g=normNum(inp.value);const ok=[it.ans].concat(it.alt||[]).some(a=>normNum(a)===g);if(ok)right++;fb(ok);$(".nm-out",el).innerHTML=`<div class="verdict ${ok?"ok":"no"}" data-noxp="1"><b>${ok?"Richtig.":"Lösung: "+esc(it.ans)}</b><div class="muted">„${esc(it.say)}“</div></div>${ok||typeof numTeach!=="function"?"":numTeach(it.ans)}<div class="row" style="margin-top:.6rem"><button class="primary nm-nx">Weiter <span class="kbd">↵</span></button></div>`;$(".nm-nx",el).onclick=chk};
    $(".nm-chk",el).onclick=chk;KEYS=e=>{if(e.key==="Enter"){e.preventDefault();chk()}}}
  step()}
ACT.numbers=()=>numbersRunner(Focus.open({title:"Zahlen im Dienst",sub:"RR, Puls, Laborwerte, Dosen, Daten"}));
// ---------- Begriffe: lay ↔ medical
const TERMS=[["Blinddarmentzündung","Appendizitis","appendicitis"],["Herzinfarkt","Myokardinfarkt","myocardial infarction"],["Schlaganfall","Apoplex / Hirninfarkt","stroke"],["Zucker","Diabetes mellitus","diabetes"],["Bluthochdruck","arterielle Hypertonie","hypertension"],["Wassertabletten","Diuretika","diuretics"],["Blutverdünner","Antikoagulanzien","anticoagulants"],["Lungenentzündung","Pneumonie","pneumonia"],["Gallenblasenentzündung","Cholezystitis","cholecystitis"],["Nierensteine","Nephrolithiasis","kidney stones"],["Gelbsucht","Ikterus","jaundice"],["Drehschwindel","Vertigo","vertigo"],["Ohnmacht","Synkope","syncope"],["Herzrasen","Tachykardie","tachycardia"],["Herzstolpern","Extrasystolen","palpitations / ectopics"],["Luftnot","Dyspnoe","dyspnoea"],["Durchfall","Diarrhö","diarrhoea"],["Verstopfung","Obstipation","constipation"],["Sodbrennen","Refluxbeschwerden","heartburn"],["Bauchspeicheldrüse","Pankreas","pancreas"],["Schilddrüse","Glandula thyreoidea","thyroid"],["Wasser in den Beinen","Beinödeme","leg oedema"],["Krampfadern","Varizen","varicose veins"],["Thrombose im Bein","tiefe Beinvenenthrombose (TVT)","DVT"],["Lungenembolie","Lungenarterienembolie (LAE)","pulmonary embolism"],["Bruch","Fraktur","fracture"],["Prellung","Kontusion","contusion"],["Gehirnerschütterung","Commotio cerebri","concussion"],["Mandelentzündung","Tonsillitis","tonsillitis"],["Blasenentzündung","Zystitis","cystitis"],["Blutvergiftung","Sepsis","sepsis"],["Hexenschuss","Lumbago","acute low back pain"],["Magenspiegelung","Gastroskopie","gastroscopy"],["Darmspiegelung","Koloskopie","colonoscopy"],["Ultraschall","Sonographie","ultrasound"],["Speiseröhre","Ösophagus","oesophagus"],["Kehlkopf","Larynx","larynx"],["Schienbein","Tibia","shin bone"],["Oberschenkelhalsbruch","Schenkelhalsfraktur","hip fracture"],["Zuckerschock","Hypoglykämie","hypoglycaemia"]];
function termsRunner(el){const qs=shuffle(TERMS).slice(0,10).map((t,i)=>{const toMed=i%2===0;const others=shuffle(TERMS.filter(x=>x!==t)).slice(0,3);const opts=[t].concat(others).map(x=>toMed?x[1]:x[0]);return {q:toMed?`Patient sagt „${t[0]}“. Fachbegriff für Akte und Oberarzt?`:`In der Akte steht „${t[1]}“. Wie sagst du es dem Patienten?`,o:opts,a:0,why:`${t[0]} = ${t[1]} (${t[2]}). Mit Patienten: ${t[0]}. Mit Kollegen und in der Akte: ${t[1]}.`}});
  el.innerHTML=`<div class="head"><div class="eyebrow">Begriffe <span class="en">lay ↔ medical register</span></div><p>In der Fachsprachprüfung zählt, dass du mit dem Patienten Laiensprache und mit dem Oberarzt Fachsprache sprichst.</p></div><div class="card bt-q"></div>`;quizRunner($(".bt-q",el),qs,{onDone:()=>logDay("drill")})}
ACT.terms=()=>termsRunner(Focus.open({title:"Begriffe",sub:"Laie ↔ Fachsprache"}));
// ---------- Aussprache prüfen: say lesson lines, the device checks intelligibility
function pronCheckRunner(el){const lines=shuffle(shadowLines(null).concat(shuffle(allCards().filter(c=>c.kind==="satz"&&S.cards[c.id])).slice(0,4).map(c=>({de:c.de,en:c.en})))).slice(0,6);let i=0;
  function step(){if(i>=lines.length){el.innerHTML=`<div class="celebrate fade-in"><div class="eyebrow">Aussprache</div><h2>${lines.length} Sätze gesprochen.</h2><p class="muted">Sprich die rot markierten Wörter morgen noch einmal.</p></div>`;return}
    const l=lines[i];el.innerHTML=`<div class="head"><div class="eyebrow">Satz ${i+1} / ${lines.length} <span class="en">say it, the phone listens</span></div></div><div class="card raise" style="text-align:center;padding:1.5rem 1.2rem"><div style="font-family:var(--display);font-size:1.4rem;line-height:1.35">${esc(l.de)}</div><div class="muted ui" style="margin-top:.5rem">${esc(l.en||"")}</div></div><div class="row"><button class="sm pc-hear">${ic("vol")} Vorsprechen</button><button class="primary pc-mic" style="flex:1">${ic("mic")} Jetzt sprechen</button></div><div class="pc-out"></div><div class="row end"><button class="sm ghost pc-nx">Nächster Satz ${ic("chev")}</button></div>`;
    $(".pc-hear",el).onclick=()=>say(l.de);$(".pc-mic",el).onclick=e=>speakCheck(e.currentTarget,l.de,$(".pc-out",el));$(".pc-nx",el).onclick=()=>{i++;step()}}
  if(!SR){el.innerHTML=`<div class="empty"><div class="big">M</div><p>${esc(srMsg("unsupported"))} Nutze Schattensprechen oder öffne die installierte App in Chrome bzw. Safari.</p></div>`;return}step()}
