let INSTALL_EVT=null;
window.addEventListener("beforeinstallprompt",e=>{e.preventDefault();INSTALL_EVT=e;if(!Focus.isOpen())rerender()});
window.addEventListener("appinstalled",()=>{INSTALL_EVT=null;toast("Mephisto ist installiert.");S.installedAt=todayKey();saveSoon()});
function coachItems(){const out=[],t=todayKey();const dis=(S.coachDismiss||{})[t]||[];const add=(id,ic_,title,sub,act,arg)=>{if(!dis.includes(id))out.push({id,ic:ic_,title,sub,act,arg})};
  if(IS_PWA&&!IS_STANDALONE&&(INSTALL_EVT||IS_IOS))add("install","download","Als App installieren","Eigenes Symbol, offline, Spracherkennung und Ton.","installApp");
  if(!IS_PWA&&!S.appHint)add("app","download","Mephisto als App aufs Handy","Offline, mit Ton und Mikrofon. Fortschritt per Backup mitnehmen.","meData");
  const lb=S.lastBackup||"";if(Object.keys(S.cards).length>30&&(!lb||diffDays(lb,t)>=30))add("backup","download","Backup fällig",lb?`Letztes Backup ${fmtDate(lb)}.`:"Noch nie gesichert. Eine Datei genügt.","meData");
  const due=dueKeys().length;if(due>=80)add("due","cards",`${due} Karten fällig`,"Eine kurze Extra-Runde jetzt verhindert die Lawine.","cards");
  ["goethe","telc","med"].forEach(ex=>{(EXAMS[ex].mods||[]).forEach(md=>{const rs=(S.examRes||[]).filter(r=>r.ex===ex&&r.m===md.m);const sc=modScore(ex,md.m);if(rs.length>=3&&sc!=null&&sc<60)add("ex-"+ex+md.m,"target",`${EXAMS[ex].short} ${md.m}: Ø ${sc} %`,"Unter der Grenze. Ein Modelltest zeigt, wo es hakt.","examHubCoach",ex)})});
  const E=Object.entries(S.errors||{}).sort((a,b)=>b[1]-a[1])[0];if(E&&E[1]>=5&&ERR_LESSON[E[0]])add("err","target",`Häufigster Fehler: ${E[0]} (${E[1]}×)`,"Die passende Lektion dauert zehn Minuten.","lessonCoach",ERR_LESSON[E[0]]);
  const now=Object.entries(S.lit||{}).find(([,v])=>v==="now");if(now){const L=LADDER.find(x=>x.id===now[0]);if(L)add("book","learn",`Du liest: ${L.t}`,"Zwei Sätze ins Lesetagebuch?","bookCoach",L.id)}
  return out.slice(0,3)}
function coachHTML(){const items=coachItems();if(!items.length)return "";return `<div class="coach">${items.map(c=>`<div class="coach-i"><span class="ic">${ic(c.ic)}</span><button class="t" data-act="${c.act}" ${c.arg?`data-arg2="${esc(c.arg)}"`:""}><b>${esc(c.title)}</b><small>${esc(c.sub)}</small></button><button class="icon ghost" data-act="coachX" data-id="${c.id}" aria-label="Für heute ausblenden">${ic("x")}</button></div>`).join("")}</div>`}
