// ---------- Tutor with your own Anthropic API key (installed app only; key stays on this device)
const KEY_LS="mephisto_api_key";
const apiKey=()=>lsGet(KEY_LS)||"";
function looseJSON(t){t=String(t||"").trim();try{return JSON.parse(t)}catch(e){}const f=t.match(/```(?:json)?\s*([\s\S]*?)```/);if(f){try{return JSON.parse(f[1])}catch(e){}}const a=Math.min(...["{","["].map(c=>{const i=t.indexOf(c);return i<0?1e9:i})),b=Math.max(t.lastIndexOf("}"),t.lastIndexOf("]"));if(a<b){try{return JSON.parse(t.slice(a,b+1))}catch(e){}}throw {code:"invalid_json",text:t}}
async function apiSample(input,o){o=o||{};const key=apiKey();if(!key)throw {code:"not_granted"};let msgs=typeof input==="string"?[{role:"user",content:input}]:input.map(m=>({role:m.role,content:m.content}));const merged=[];msgs.forEach(m=>{const l=merged[merged.length-1];if(l&&l.role===m.role)l.content+="\n\n"+m.content;else merged.push({role:m.role,content:m.content})});if(o.json)merged[merged.length-1].content+="\n\nAntworte ausschließlich mit gültigem JSON, ohne weiteren Text.";
  const model=o.modelTier==="quick"?"claude-haiku-5-5":"claude-sonnet-5-5";let r;
  try{r=await fetch("https://api.anthropic.com/v1/messages",{method:"POST",signal:o.signal,headers:{"content-type":"application/json","x-api-key":key,"anthropic-version":"2023-06-01","anthropic-dangerous-direct-browser-access":"true"},body:JSON.stringify({model,max_tokens:o.json?2500:900,messages:merged})})}catch(e){throw {code:e&&e.name==="AbortError"?"cancelled":"upstream_error"}}
  if(!r.ok){const code=r.status===401||r.status===403?"not_granted":r.status===429||r.status===529?"rate_limited":"upstream_error";let m="";try{m=(await r.json()).error.message}catch(e){}if(code==="not_granted")toast("API-Schlüssel abgelehnt. Prüfe ihn unter Ich → Einstellungen.",4500);throw {code,message:m}}
  const j=await r.json();const text=(j.content||[]).filter(c=>c.type==="text").map(c=>c.text).join("").trim();if(!text)throw {code:"empty_completion"};if(o.onText)o.onText({text,delta:text});return {text,truncated:j.stop_reason==="max_tokens",modelTierApplied:o.modelTier||"default"}}
apiSample.json=async(input,o)=>{const r=await apiSample(input,Object.assign({},o,{json:true}));return looseJSON(r.text)};
apiSample.limits=async()=>({maxPromptBytes:262144});
const _capsReady=capsReady;
capsReady=function(){if(!SAMPLE&&SAMPLE_STATE==="absent"&&apiKey()){SAMPLE=apiSample;SAMPLE_STATE="key"}_capsReady()};
ACT.saveKey=()=>{const v=($(".k-in")||{}).value||"";if(v&&!/^sk-ant-/.test(v.trim()))return toast("Ein Anthropic-Schlüssel beginnt mit „sk-ant-“.");lsSet(KEY_LS,v.trim());if(!v.trim()){if(SAMPLE===apiSample){SAMPLE=null;SAMPLE_STATE="absent"}}else if(!SAMPLE||SAMPLE===apiSample){SAMPLE=apiSample;SAMPLE_STATE="key"}capsReady();toast(v.trim()?"Schlüssel gespeichert (nur auf diesem Gerät).":"Schlüssel entfernt.");rerender()};
ACT.testKey=async el=>{if(!apiKey())return toast("Erst einen Schlüssel speichern.");el.disabled=true;el.textContent="Teste…";try{const r=await apiSample("Antworte nur mit: Alles klar.",{modelTier:"quick"});toast("Verbindung steht: "+r.text.slice(0,40))}catch(e){toast(tutorMsg(e&&e.code)||"Fehler")}el.disabled=false;el.textContent="Testen"};
function tutorSettingsHTML(){const inViewer=SAMPLE&&SAMPLE!==apiSample;return `<div class="card stack s"><h3>Tutor (Claude)</h3>${inViewer?`<p class="fg2" style="font-size:.95rem"><span class="pill good">${ic("check")} aktiv</span> über dein claude.ai-Konto in dieser Ansicht.</p>`:`<p class="fg2" style="font-size:.95rem">In der installierten App gibt es keinen claude.ai-Zugang. Mit einem eigenen API-Schlüssel (console.anthropic.com) funktionieren Korrektur, Rollenspiel und Prüfungsbewertung trotzdem; jede Anfrage kostet ein paar Cent API-Guthaben. Ohne Schlüssel gibt es Musterlösungen und Checklisten.</p><input class="k-in" type="password" autocomplete="off" placeholder="sk-ant-…" value="${esc(apiKey())}"><div class="row"><button class="sm primary" data-act="saveKey">Speichern</button><button class="sm" data-act="testKey">Testen</button>${apiKey()?`<span class="pill good">Schlüssel gesetzt</span>`:""}</div><p class="muted ui" style="font-size:.8rem">Der Schlüssel bleibt nur auf diesem Gerät, wird nie in Backups oder den Yuzu-Pack exportiert und geht nur an api.anthropic.com. Am sichersten: ein eigener Schlüssel mit Ausgabenlimit nur für Mephisto.</p>`}</div>`}
// ---------- service worker: offline + update when the user taps
let SW_WAITING=null;
function swUpdateReady(w){SW_WAITING=w;snack("Neue Version von Mephisto bereit.","Aktualisieren",()=>{try{w.postMessage({type:"SKIP_WAITING"})}catch(e){}},60000)}
if(IS_PWA&&"serviceWorker" in navigator&&window.isSecureContext){const hadCtl=!!navigator.serviceWorker.controller;window.addEventListener("load",()=>{navigator.serviceWorker.register("./sw.js").then(reg=>{if(reg.waiting&&navigator.serviceWorker.controller)swUpdateReady(reg.waiting);reg.addEventListener("updatefound",()=>{const n=reg.installing;if(!n)return;n.addEventListener("statechange",()=>{if(n.state==="installed"&&navigator.serviceWorker.controller)swUpdateReady(n)})});setInterval(()=>reg.update().catch(()=>{}),60*60*1000)}).catch(e=>logError(e))});let reloaded=false;navigator.serviceWorker.addEventListener("controllerchange",()=>{if(reloaded||!hadCtl)return;reloaded=true;saveNow();location.reload()})}
ACT.repairApp=async()=>{saveNow();try{if(navigator.serviceWorker){const regs=await navigator.serviceWorker.getRegistrations();await Promise.all(regs.map(r=>r.unregister()))}if(window.caches){const ks=await caches.keys();await Promise.all(ks.map(k=>caches.delete(k)))}}catch(e){}toast("Zwischenspeicher geleert. Lädt neu…");setTimeout(()=>location.reload(),700)};
function diagHTML(){return `<details class="card"><summary class="ui" style="cursor:pointer;font-weight:700">Diagnose &amp; Reparatur</summary><div class="kv" style="margin-top:.6rem"><b>Version</b><span>${APP_VERSION}${IS_PWA?" · App":" · claude.ai"}</span><b>Installiert</b><span>${IS_STANDALONE?"ja":"nein"}</span><b>Offline</b><span>${navigator.serviceWorker&&navigator.serviceWorker.controller?"bereit":"nein"}</span><b>Speicher</b><span>${STORAGE_OK?"ok":"blockiert"}</span><b>Sprachausgabe</b><span>${TTS_OK?(DE_VOICE?esc(DE_VOICE.name):"keine deutsche Stimme"):"nicht verfügbar"}</span><b>Spracherkennung</b><span>${SR?"verfügbar":"nicht verfügbar"}</span><b>Tutor</b><span>${SAMPLE?(SAMPLE===apiSample?"eigener Schlüssel":"claude.ai"):"aus"}</span><b>Karten</b><span>${Object.keys(S.cards).length}</span></div>${IS_PWA?`<div class="row" style="margin-top:.6rem"><button class="sm" data-act="repairApp">App reparieren</button><span class="muted ui" style="font-size:.8rem">Leert nur den App-Zwischenspeicher. Dein Fortschritt bleibt.</span></div>`:""}</details>`}
// ---------- deep links from app shortcuts (?a=…)
function runDeepLink(){let a=null;try{a=new URLSearchParams(location.search).get("a")}catch(e){}if(!a)return;try{history.replaceState(null,"",location.pathname+location.hash)}catch(e){}setTimeout(()=>{if(a==="session")openSession();else if(a==="cards")openCards();else if(a==="blitz")ACT.blitz();else if(a==="numbers")ACT.numbers()},120)}
// ---------- wire up
capsReady();
document.addEventListener("click",()=>{if(AC&&AC.state==="suspended")AC.resume().catch(()=>{})},{passive:true});

// ---------- Verlauf: what you did, day by day
const EV_IC={session:"check",cards:"cards",lesson:"book",read:"learn",write:"pen",sim:"chat",fsp:"steth",exam:"target",mock:"target",drill:"grid",blitz:"bolt",speak:"mic",flu:"wave",kino:"play",book:"learn",backup:"download"};
function meHistory(el){const t=todayKey();const days=[];for(let i=27;i>=0;i--)days.push(addDays(t,-i));const mins=days.map(minutesOn);const maxM=Math.max(30,...mins);
  const allDays=Object.keys(S.log).filter(k=>S.log[k].act).sort();const totMin=Object.keys(S.log).reduce((a,k)=>a+minutesOn(k),0);const totRev=Object.values(S.log).reduce((a,L)=>a+(L.rev||0),0),totOk=Object.values(S.log).reduce((a,L)=>a+(L.ok||0),0);
  const wk=d=>{const s=weekKey(d);return s};const weeks={};Object.keys(S.log).forEach(k=>{const w=wk(k);const L=S.log[k];const W=weeks[w]=weeks[w]||{min:0,rev:0,les:0,write:0,exam:0,days:0,sess:0};W.min+=minutesOn(k);W.rev+=L.rev||0;W.les+=L.les||0;W.write+=L.write||0;W.exam+=L.exam||0;W.sess+=L.session||0;if(L.act)W.days++});
  const wkeys=Object.keys(weeks).sort().reverse().slice(0,8);
  const evs=(S.events||[]).slice().reverse();const byDay={};evs.forEach(e=>{(byDay[e.d]=byDay[e.d]||[]).push(e)});const evDays=Object.keys(byDay).sort().reverse().slice(0,14);
  el.innerHTML=`<div class="stats"><div class="stat o"><b>${totMin>=120?(totMin/60).toFixed(1)+" h":totMin+" min"}</b><span>Lernzeit gesamt</span></div><div class="stat"><b>${allDays.length}</b><span>aktive Tage</span></div><div class="stat"><b>${totRev?Math.round(100*totOk/totRev)+"%":"–"}</b><span>Karten gewusst</span></div></div>
  <div class="card stack s"><div class="row between"><h3>Lernzeit, 28 Tage</h3><span class="muted ui" style="font-size:.82rem">Ziel ${S.minutes} Min.</span></div>
   <div class="mbars">${days.map((d,i)=>{const m=mins[i];const L=S.log[d]||{};const shift=S.shifts&&S.shifts[d];return `<div class="mb${d===t?" today":""}${m?"":" z"}" data-hint="${fmtDate(d)}|${m} Min.${L.rev?" · "+L.rev+" Karten":""}${L.session?" · Sitzung fertig":""}${shift?" · Dienst":""}"><i style="height:${Math.round(100*m/maxM)}%;${m>=S.minutes?"background:var(--good)":""}"></i>${shift?'<s></s>':""}</div>`}).join("")}<div class="goal" style="bottom:${Math.round(100*S.minutes/maxM)}%"></div></div>
   <div class="row between muted ui" style="font-size:.75rem"><span>${fmtDate(days[0])}</span><span>grün: Ziel erreicht · Punkt darunter: Dienst</span><span>heute</span></div></div>
  <div class="card stack s"><h3>Wochen</h3>${wkeys.length?`<div class="tw"><table class="wtab"><thead><tr><th>Woche ab</th><th>Min.</th><th>Tage</th><th>Karten</th><th>Lekt.</th><th>Schreib.</th><th>Prüf.</th></tr></thead><tbody>${wkeys.map(w=>{const W=weeks[w];return `<tr><td>${fmtDate(w)}</td><td>${W.min}</td><td>${W.days}</td><td>${W.rev}</td><td>${W.les}</td><td>${W.write}</td><td>${W.exam}</td></tr>`}).join("")}</tbody></table></div>`:'<p class="muted">Noch keine Daten.</p>'}</div>
  <div class="card stack s"><div class="row between"><h3>Protokoll</h3><button class="sm" data-act="exportLog">${ic("download")} CSV</button></div>${evDays.length?evDays.map(d=>`<div class="evday"><div class="eyebrow">${fmtDate(d)}${d===t?" · heute":""} · ${minutesOn(d)} Min.</div>${byDay[d].map(e=>`<div class="ev"><span class="tm mono">${esc(e.t)}</span><span class="ic">${ic(EV_IC[e.type]||"check")}</span><span>${esc(e.text)}</span></div>`).join("")}</div>`).join(""):'<p class="muted">Noch nichts protokolliert. Jede Sitzung, Lektion, Prüfungsaufgabe, Karte und jedes Gespräch erscheint hier mit Uhrzeit.</p>'}</div>`}
ACT.exportLog=async()=>{const rows=[["Datum","Zeit","Typ","Eintrag","Wert"]].concat((S.events||[]).map(e=>[fmtDate(e.d),e.t,e.type,e.text,e.val==null?"":e.val]));const days=Object.keys(S.log).sort().map(k=>{const L=S.log[k];return [fmtDate(k),minutesOn(k),L.rev||0,L.ok||0,L.new||0,L.les||0,L.read||0,L.write||0,L.sim||0,L.exam||0,L.session||0]});
  const csv=rows.map(r=>r.map(x=>'"'+String(x).replace(/"/g,'""')+'"').join(";")).join("\n")+"\n\n"+[["Datum","Minuten","Karten","gewusst","neu","Lektionen","gelesen","geschrieben","Rollenspiele","Prüfungsaufgaben","Sitzung"]].concat(days).map(r=>r.join(";")).join("\n");
  const r=await saveFile("mephisto-verlauf-"+todayKey().split("-").reverse().join("-")+".csv","﻿"+csv);if(r===null)copyText(csv)};

// ---------- hold to translate: tap = word, hold = whole sentence, hold + slide = any phrase (with literal meaning)
const XL={timer:null,start:null,anchor:null,on:false,blk:null,words:[],idx:0,sel:null,mode:"",swallow:false,done:false};
const XL_KEY="mephisto_xl";let XLC={};try{XLC=JSON.parse(localStorage.getItem(XL_KEY)||"{}")||{}}catch(e){XLC={}}
function xlCacheSave(){try{const ks=Object.keys(XLC);if(ks.length>300)ks.slice(0,ks.length-300).forEach(k=>delete XLC[k]);localStorage.setItem(XL_KEY,JSON.stringify(XLC))}catch(e){}}
const XL_ABBR=/^(Dr|Prof|Fr|Hr|Nr|St|ca|bzw|usw|evtl|ggf|z|B|u|a|d|h|i|v|s|o|ä|vs|Std|Min|Tel|Abs|Str|mg|ml|kg|Jh|Mio|Mrd|etc)$/;
const xlNorm=s=>String(s||"").replace(/[„“"‚‘'«»()\[\]–—…]/g,"").replace(/\s+/g," ").trim().toLowerCase();
// which German text this module owns (the hand kit skips these)
function xlEligible(t){if(!t||!t.closest)return false;if(t.closest("input,textarea,select,button,a,label,.opts,.chip,.fc,.kit-sheet,.sheet,[data-act],[data-go],[data-say]"))return false;
  const w=t.closest(".w");if(w)return true;const de=t.closest(".de");return !!(de&&!de.querySelector("*")&&/\p{L}/u.test(de.textContent))}
window.xlOwns=xlEligible;
function xlWordAt(x,y){const el=document.elementFromPoint(x,y);return el&&el.closest?el.closest(".w"):null}
function xlBlock(w){return w.closest(".xl-blk,.line,.para,p,li,div")||w.parentElement}
function xlEnds(w){const n=w.nextSibling;if(!n||n.nodeType!==3)return false;if(!/^\S*[.!?…:]/.test(n.textContent))return false;return !XL_ABBR.test(w.dataset.w||w.textContent)}
function xlSentence(i){let a=i,b=i;while(a>0&&!xlEnds(XL.words[a-1]))a--;while(b<XL.words.length-1&&!xlEnds(XL.words[b]))b++;return [a,b]}
function xlPaint(){XL.words.forEach((w,k)=>w.classList.toggle("xl-on",!!XL.sel&&k>=XL.sel[0]&&k<=XL.sel[1]))}
function xlClear(){$$(".w.xl-on").forEach(w=>w.classList.remove("xl-on"))}
function xlText(a,b,withPunct){const r=document.createRange();r.setStartBefore(XL.words[a]);r.setEndAfter(XL.words[b]);let s=r.toString();if(withPunct){const n=XL.words[b].nextSibling;if(n&&n.nodeType===3){const m=n.textContent.match(/^[^\s\p{L}]*/u);if(m)s+=m[0]}}return s.replace(/\s+/g," ").trim()}
function xlLineText(){return XL.words.length?xlText(0,XL.words.length-1,true):""}
function xlLineTr(){const b=XL.blk;if(!b)return "";const n=b.nextElementSibling;return n&&n.classList.contains("tr")?n.textContent.trim():""}

function xlBegin(){XL.timer=null;const w=XL.anchor;if(!w||!document.body.contains(w))return;XL.on=true;XL.done=false;XL.blk=xlBlock(w);XL.words=[...XL.blk.querySelectorAll(".w")].filter(x=>!x.closest(".fc"));XL.idx=XL.words.indexOf(w);if(XL.idx<0){XL.on=false;return}
  XL.sel=xlSentence(XL.idx);XL.mode="sentence";xlPaint();try{getSelection().removeAllRanges()}catch(e){}if(typeof vib==="function")vib(12);else if(navigator.vibrate&&S.haptic)navigator.vibrate(12)}
function xlMove(x,y){if(XL.timer&&XL.start&&Math.hypot(x-XL.start.x,y-XL.start.y)>10){clearTimeout(XL.timer);XL.timer=null;return}
  if(!XL.on)return;const w=xlWordAt(x,y);if(!w)return;const j=XL.words.indexOf(w);if(j<0)return;if(j===XL.idx&&XL.mode==="sentence")return;XL.mode="range";XL.sel=[Math.min(XL.idx,j),Math.max(XL.idx,j)];xlPaint()}
function xlEnd(){clearTimeout(XL.timer);XL.timer=null;if(!XL.on||XL.done)return;XL.on=false;XL.done=true;XL.swallow=true;setTimeout(()=>{XL.swallow=false},450);
  const [a,b]=XL.sel;const sentence=XL.mode==="sentence";const text=xlText(a,b,sentence||xlEnds(XL.words[b]));
  const ws=XL.words.slice(a,b+1).map(w=>w.dataset.w||w.textContent);const box=XL.anchor.closest("[data-gk]");const map=box?GL[box.dataset.gk]:null;
  const line=xlLineText(),tr=xlLineTr();const whole=tr&&xlNorm(text)===xlNorm(line);
  xlShow({text,ws,map,mode:sentence?"Satz":"Auswahl",lineTr:tr,whole,line})}

document.addEventListener("pointerdown",e=>{if(e.button>0||XL.on)return;const t=e.target;if(!xlEligible(t))return;
  let w=t.closest(".w");if(!w){const de=t.closest(".de");de.innerHTML=glossify(de.textContent);de.classList.add("xl-blk");w=xlWordAt(e.clientX,e.clientY);if(!w)return}
  XL.anchor=w;XL.start={x:e.clientX,y:e.clientY};clearTimeout(XL.timer);XL.timer=setTimeout(xlBegin,420)},{passive:true});
document.addEventListener("pointermove",e=>xlMove(e.clientX,e.clientY),{passive:true});
document.addEventListener("touchmove",e=>{if(XL.on){e.preventDefault();const p=e.touches[0];if(p)xlMove(p.clientX,p.clientY)}},{passive:false});
document.addEventListener("pointerup",xlEnd,{passive:true});
document.addEventListener("touchend",xlEnd,{passive:true});
document.addEventListener("pointercancel",()=>{if(XL.on)return;clearTimeout(XL.timer);XL.timer=null},{passive:true});
document.addEventListener("scroll",()=>{if(!XL.on){clearTimeout(XL.timer);XL.timer=null}},{passive:true,capture:true});
document.addEventListener("click",e=>{if(XL.swallow){XL.swallow=false;e.preventDefault();e.stopImmediatePropagation()}},true);
document.addEventListener("contextmenu",e=>{if(typeof holdMode==="function"&&holdMode()==="system")return;if(XL.on||XL.timer||(e.target.closest&&e.target.closest(".xl-blk,.w")))e.preventDefault()});
