function xlGloss(w,map){if(map){const g=map[w]||map[w.toLowerCase()];if(g)return g}return XL_COMMON[w]||XL_COMMON[w.toLowerCase()]||lookup(w,null).en||""}
function xlLitHTML(ws,map,tutorWords){const tw={};(tutorWords||[]).forEach(p=>{if(Array.isArray(p)&&p[0])tw[String(p[0]).toLowerCase()]=p[1]});
  return ws.map(w=>{const g=tw[w.toLowerCase()]||xlGloss(w,map);const short=g.split(/[;,(]/)[0].trim();return `<button class="xl-w" data-w="${esc(w)}"><b>${esc(w)}</b><small${short?"":' class="unk"'}>${esc(short||"·")}</small></button>`}).join("")}
async function xlShow(o){const sh=$("#sheet"),inn=$("#sheetIn");const key=xlNorm(o.text);const cached=XLC[key];
  const offlineEn=o.whole?o.lineTr:(cached&&cached.en)||"";
  inn.innerHTML=`<div class="row between"><div class="eyebrow">${o.mode} <span class="en">${o.ws.length} ${o.ws.length===1?"Wort":"Wörter"}</span></div><button class="icon ghost" data-act="closeSheet" aria-label="Schließen">${ic("x")}</button></div>
   <div class="xl-de">${esc(o.text)}</div>
   <div class="xl-en">${offlineEn?esc(offlineEn):(SAMPLE?'<span class="muted ui xl-wait">Übersetze…</span>':o.lineTr?`<span class="muted ui">Ganze Zeile:</span> ${esc(o.lineTr)}`:'<span class="muted ui">Wörtliche Bedeutung unten. Für eine freie Übersetzung beliebiger Stellen den Tutor einschalten (Ich → Einstellungen).</span>')}</div>
   <div class="xl-lit-h eyebrow">Wörtlich <span class="en">word by word · tap a word</span></div>
   <div class="xl-lit">${xlLitHTML(o.ws,o.map,cached&&cached.words)}</div>
   <div class="xl-lit-en muted">${cached&&cached.lit?"„"+esc(cached.lit)+"“":""}</div>
   <div class="xl-note muted ui">${cached&&cached.note?esc(cached.note):""}</div>
   <div class="row wrap"><button class="sm" data-say="${esc(o.text)}">${ic("vol")} Anhören</button><button class="sm xl-slow">${ic("vol")} Langsam</button><button class="sm xl-copy">${ic("pen")} Kopieren</button>${o.ws.length>1?`<button class="sm primary xl-add">${ic("plus")} Ins Deck</button>`:""}</div>`;
  sh.hidden=false;const done=()=>{xlClear()};const obs=new MutationObserver(()=>{if(sh.hidden){done();obs.disconnect()}});obs.observe(sh,{attributes:true,attributeFilter:["hidden"]});
  $$(".xl-w",inn).forEach(b=>b.onclick=()=>showGloss(b.dataset.w,o.map));
  $(".xl-slow",inn).onclick=()=>say(o.text,{rate:.7});$(".xl-copy",inn).onclick=()=>copyText(o.text);
  const add=$(".xl-add",inn);if(add)add.onclick=()=>{const en=($(".xl-en",inn).textContent||"").replace(/^Ganze Zeile:\s*/,"").trim();if(!en||/Übersetze…|Wörtliche Bedeutung/.test(en))return toast("Erst die Übersetzung abwarten");
    S.custom.push({de:o.text,en,ex:o.line&&o.line!==o.text?o.line:""});buildDict();S.cards["c:"+(S.custom.length-1)]=newState();introducedNew(false);saveSoon();logEvent("card","Ins Deck: "+o.text.slice(0,60));add.innerHTML=ic("check")+" Im Deck";add.disabled=true;toast("Ins Deck gelegt")};
  if(S.autoplay)say(o.text,{silent:true});
  // fetch a contextual translation + literal meaning when the tutor is available and nothing better is known
  if(!SAMPLE||(cached&&cached.en&&cached.lit))return;
  try{const r=await SAMPLE.json(`Du hilfst einem arabischsprachigen Arzt (Englisch fließend, Deutsch A2–B1) beim Lesen.
Übersetze die markierte deutsche Stelle ins Englische.
Stelle: «${o.text}»
${o.line&&o.line!==o.text?`Ganzer Satz/Zeile als Kontext: «${o.line}»`:""}
${o.lineTr?`Vorhandene Übersetzung der ganzen Zeile: «${o.lineTr}»`:""}
Antworte NUR mit JSON:
{"en":"natürliche englische Übersetzung der Stelle","lit":"wörtliche, Wort-für-Wort-Übersetzung ins Englische (holprig erlaubt)","words":[["deutsches Wort genau wie im Text","kurze englische Bedeutung im Kontext"]],"note":"ein kurzer Hinweis auf Englisch zu Grammatik, Redewendung oder Register, falls nützlich, sonst leer"}`,{modelTier:"quick",cache:false});
    if(!r||!r.en)throw 0;XLC[key]={en:o.whole?o.lineTr:String(r.en),lit:String(r.lit||""),words:Array.isArray(r.words)?r.words.slice(0,40):[],note:String(r.note||"")};xlCacheSave();
    if(sh.hidden||!document.body.contains(inn)||!$(".xl-de",inn)||$(".xl-de",inn).textContent!==o.text)return;
    const c=XLC[key];$(".xl-en",inn).textContent=c.en;$(".xl-lit",inn).innerHTML=xlLitHTML(o.ws,o.map,c.words);$$(".xl-w",inn).forEach(b=>b.onclick=()=>showGloss(b.dataset.w,o.map));
    $(".xl-lit-en",inn).textContent=c.lit?"„"+c.lit+"“":"";$(".xl-note",inn).textContent=c.note}
  catch(e){const en=$(".xl-en",inn);if(en&&$(".xl-wait",en))en.innerHTML=o.lineTr?`<span class="muted ui">Ganze Zeile:</span> ${esc(o.lineTr)}`:'<span class="muted ui">Gerade keine Übersetzung möglich. Die wörtliche Bedeutung steht unten.</span>'}}
// one-time tip the first time a word is tapped
{MOD.after("showGloss","xlate",function(w,m){let seen=1;try{seen=localStorage.getItem("mephisto_xl_tip")}catch(e){}if(!seen){try{localStorage.setItem("mephisto_xl_tip","1")}catch(e){}setTimeout(()=>snack("Tipp: Wort gedrückt halten = ganzer Satz auf Englisch. Halten und ziehen = eigene Auswahl.","OK",()=>{},6500),600)}})}

