// ---- German lexicon built from the app's own German text (cards, dialogues, lessons, readings, exams)
const TCH={lex:null};
const T_DE=new Set("der die das und ist ich sie nicht mit ein eine zu den dem auf es wir haben sind bitte wie was er habe hat bei von im für auch noch sich mein ihr ihnen ihre wird kann wenn dass oder aber seit sehr wo wann heute".split(" "));
const T_EN=new Set("the and is you of to a your with it that for are this be have not on as at by from was were will can or but if he she they what how".split(" "));
function tIsDe(s){const t=s.toLowerCase().match(/[a-zäöüß]+/g)||[];let d=0,e=0;t.forEach(w=>{if(T_DE.has(w))d++;if(T_EN.has(w))e++});if(/[äöüß]/i.test(s))d++;return d>e}
