  if(/\bdu\b|du-Form/.test(reg)){text.replace(/(?<=[a-zäöüß,]\s)(Sie|Ihnen)\b/g,(m,off)=>{add({key:"reg_sie",type:"Register",title:"Unter Kollegen: du",orig:m,fix:m==="Ihnen"?"dir":"du"},off,off+m.length,null);return m})}
  if(/fachsprach|Oberarzt|Arzt zu Arzt/i.test(reg)){text.replace(/\bich glaube\b/gi,(m,off)=>{add({key:"reg_glaube",type:"Register",title:"Fachsprache: vermuten statt glauben",orig:m,fix:m[0]==="I"?"Ich vermute":"ich vermute"},off,off+m.length,m[0]==="I"?"Ich vermute":"ich vermute");return m});
    text.replace(/\bich habe (ein|einen|eine)\b/i,(m,a,off)=>{if(off<4)add({key:"reg_intro",type:"Register",title:"So beginnt eine Vorstellung",orig:m,fix:"Ich stelle Ihnen … vor"},off,off+m.length,null);return m})}
  if(/Laien|keine Latinismen|verständlich/i.test(reg)&&!/fachsprach|Oberarzt|Arzt zu Arzt|Kolleg/i.test(reg)){const m=text.match(T_LATIN);if(m)add({key:"reg_latin",type:"Register",title:"Laiensprache für Patienten",orig:m[0],fix:"einfaches Wort"},m.index,m.index+m[0].length,null)}
