function tCharDiff(a,b){let i=0;while(i<a.length&&i<b.length&&a[i].toLowerCase()===b[i].toLowerCase()&&a[i]===b[i])i++;let j=0;while(j<a.length-i&&j<b.length-i&&a[a.length-1-j]===b[b.length-1-j])j++;return esc(b.slice(0,i))+`<u>${esc(b.slice(i,b.length-j))||"·"}</u>`+esc(b.slice(b.length-j))}

// ---- render: the feedback page
const TCH_ATT=new WeakMap();
// split into sentences without breaking at abbreviations (Z. n., ca., i.v., z. B., Dr.) or numbers (3. Tag)
function tSplitSents(x){const out=[];let cur="";String(x).split(/(\n+)/).forEach(block=>{if(/^\n+$/.test(block)){if(cur.trim())out.push(cur.trim());cur="";return}const parts=block.split(/(?<=[.!?])\s+/);
    parts.forEach(p=>{cur=cur?cur+" "+p:p;const last=(cur.match(/(\S+)$/)||[])[1]||"";const brk=/[!?]$/.test(last)||(/\.$/.test(last)&&!T_ABBR_RE.test(last)&&!/^\(?\d+\.$/.test(last)&&!/^\(?(ca|vgl|bzw|evtl|ggf|inkl|zzgl|sog|Nr|Abb|Tab|Std|Min|Mio|Mrd|Jh|St|Z|n|p|i|v|o|B|z|u|a|d|h|s|m|Pat|Hr|Fr|Dr|Prof)\.$/.test(last.split(/\./).slice(-2).join(".")));
      if(brk){out.push(cur.trim());cur=""}})});if(cur.trim())out.push(cur.trim());return out.filter(Boolean)}
function teachRender(out,text,t,o,tutor){o=o||{};let A;try{A=teachAnalyze(text,t)}catch(e){logError&&logError(e);return _selfCheckOld(out,text,t,o)}
  const T=A.T;let moments=tMoments(A.F);
  // tutor errors become moments too (they see what rules can't)
  if(tutor&&Array.isArray(tutor.errors)&&tutor.errors.length){const tm=tutor.errors.map(e=>({k:"tutor",type:e.type||"",title:e.title||e.type||"Korrektur",count:1,pairs:`<span class="tch-pair"><del>${esc(e.original||"")}</del><span class="ar">→</span><ins>${esc(e.fix||"")}</ins></span>`,rule:esc(e.why||""),demo:e.bad&&e.good?`<div class="tch-say"><del>${esc(e.bad)}</del><ins>${esc(e.good)}</ins></div>`:"",merke:esc(e.merke||""),tip:esc(e.tip||"")}));
    const offlineKeep=moments.filter(m=>["len","age","v2","reg_intro","reg_glaube"].includes(m.k));moments=tm.concat(offlineKeep)}
  const corrected=tutor&&tutor.corrected?tutor.corrected:A.corrected;const content=A.content;
  const cOk=content?content.filter(c=>c.ok).length:null,cN=content?content.length:null;const nIssues=tutor&&Array.isArray(tutor.errors)?tutor.errors.length:A.F.filter(f=>f.key!=="len").length;
  // progress across attempts on the same task box
  const box=out.closest(".stack")||out;const prev=TCH_ATT.get(box);TCH_ATT.set(box,{n:nIssues,c:cOk,text});
  // what went well
  const good=[];if(tutor&&Array.isArray(tutor.good))tutor.good.slice(0,3).forEach(g=>good.push(esc(g)));
  if(!good.length){if(content)content.filter(c=>c.ok).slice(0,2).forEach(c=>good.push(esc(c.label)));
    if(/\bseit\s+(?:(?:zwei|drei|vier|fünf|sechs|sieben|acht|neun|zehn|\d+)\s+\w+n\b|(?:einem|einer)\s+\w+)/i.test(text)&&!A.F.some(f=>f.key==="seit"))good.push("<i>seit</i> + Zeitangabe richtig benutzt");
    if(/salbutamol|antibio|sauerstoff|ibuprofen|metoprolol|röntgen|labor|ekg/i.test(text)&&!/\b(unklar|keine Ahnung|weiß nicht)\b/i.test(text)&&(!A.T||/plan|procedere|therapie|vorschlag/i.test(JSON.stringify(A.T.checks||"")+String((t&&t.task)||""))))good.push("Konkreter Plan mit Maßnahme/Medikament");
    if(!A.F.some(f=>["v2","vend","comma","age","perfsein","vich","akk","lok","dat","imp"].includes(f.key))&&A.sents>=2&&!/(^|[.!?]\s+)(?:Dann|Danach|Heute|Gestern|Morgen|Jetzt|Am \w+|Im \w+|Um \d+ Uhr)\s+(ich|er|sie|wir|du|es)\s/.test(text))good.push("Satzbau: Verb an der richtigen Stelle");
    good.splice(3);if(!good.length)good.push("Du hast es versucht – genau so lernt man. Jetzt die Lernmomente.")}
  const lenShort=A.F.some(f=>f.key==="len");const contentMiss=cN!=null&&cOk<cN;const sum=lenShort?`Gut – aber noch nicht vollständig (${A.sents}/${A.want} Sätze).`:nIssues===0&&!contentMiss?"Sehr gut – sauber und vollständig.":nIssues===0?"Sprachlich sauber – inhaltlich fehlt noch etwas:":nIssues===1?"Gut gemacht. Eine Feinheit:":nIssues<=3?"Guter Versuch. Das schauen wir uns an:":"Hier sind deine Lernmomente:";
  // tips for next time
  const tips=[];if(tutor&&Array.isArray(tutor.tips))tutor.tips.slice(0,3).forEach(x=>tips.push(esc(x)));
  if(tips.length<3&&content){const miss=content.find(c=>!c.ok);if(miss)tips.push(`Inhalt: <b>${esc(miss.res.filter(r=>!r.ok).map(r=>r.n).join(", "))}</b> fehlte – plane vorher mit der Checkliste.`)}
  moments.forEach(m=>{if(tips.length<3&&m.tip&&!tips.includes(m.tip))tips.push(m.tip)});
  // model, sentence by sentence
  const modelSents=t.model?tSplitSents(String(t.model)):[];
  const roleOf=s=>{if(!T)return "";const r=T.roles.find(([re])=>re.test(s));return r?r[1]:""};
  const prog=prev?`<div class="tch-prog"><div class="eyebrow">Versuch ${prev.att?prev.att+1:2}</div><div class="row" style="gap:1rem;flex-wrap:wrap"><span><b>${prev.n}</b> → <b class="${nIssues<prev.n?"good":""}">${nIssues}</b> Lernpunkte</span>${cN?`<span>Inhalt <b>${prev.c}/${cN}</b> → <b class="${cOk>prev.c?"good":""}">${cOk}/${cN}</b></span>`:""}</div>${nIssues<prev.n||cOk>prev.c?'<div class="good ui" style="font-weight:700">Besser geworden. Genau so funktioniert Lernen.</div>':'<div class="muted ui">Noch einmal ruhig Satz für Satz mit den Bausteinen.</div>'}</div>`:"";
  if(prev)TCH_ATT.get(box).att=(prev.att||1)+1;
  out.innerHTML=`<div class="stack s fade-in tch">${prog}
   <div class="card tch-hero"><div class="row between" style="align-items:flex-start;gap:1rem"><div><div class="eyebrow">Feedback <span class="en">${tutor?"Claude + rules":"offline coach"}</span></div><h3 style="margin:.25rem 0 .4rem">${sum}</h3></div>
     <div class="tch-rings">${cN!=null?tRing(cOk,cN,"Inhalt"):""}${tRing(Math.max(0,8-nIssues),8,"Lernpunkte",true,nIssues)}</div></div>
     <div class="tch-good">${good.map(g=>`<div>${ic("check")}<span>${g}</span></div>`).join("")}</div></div>
   <div class="card"><div class="row between"><div class="eyebrow">Dein Text, verbessert <span class="en">red = remove · green = new</span></div><button class="icon ghost" data-say="${esc(corrected)}" aria-label="Anhören">${ic("vol")}</button></div>
     <div class="tch-diff">${corrected.trim()!==text.trim()?wordDiff(text,corrected):esc(text)}</div>${tutor&&tutor.natural?`<div class="tch-nat"><span class="eyebrow">So klingt es natürlich</span><div>${glossify(tutor.natural)}</div></div>`:""}</div>
   ${moments.length?`<div class="eyebrow" style="margin-top:.4rem">Lernmomente <span class="en">${moments.length} · what to learn from this text</span></div>
     ${moments.map((m,i)=>`<div class="card tch-m${i>=4?" more":""}" ${i>=4?"hidden":""}><div class="row between" style="gap:.5rem"><h4>${i+1}. ${esc(m.title)}${m.count>1?` <span class="pill">${m.count}×</span>`:""}</h4>${m.type?`<span class="pill grammatik">${esc(m.type)}</span>`:""}</div>
       ${m.pairs?`<div class="tch-pairs">${m.pairs}</div>`:""}${m.rule?`<div class="tch-rule">${m.rule}</div>`:""}${m.demo?`<div class="tch-demo">${m.demo}</div>`:""}${m.merke?`<div class="tch-merke"><b>Merke:</b> ${m.merke}</div>`:""}</div>`).join("")}
     ${moments.length>4?`<button class="ghost sm tch-more">+ ${moments.length-4} weitere Lernmomente</button>`:""}`:""}
   ${content?`<div class="card"><div class="eyebrow" style="margin-bottom:.5rem">Inhalt <span class="en">checked automatically</span></div><div class="tch-content">${content.map(c=>`<div class="tch-ci ${c.ok?"ok":c.part?"part":"no"}"><span class="tch-dot">${c.ok?ic("check"):c.part?"½":"–"}</span><div><b>${esc(c.label)}</b>${!c.ok?`<small>fehlt: ${esc(c.res.filter(r=>!r.ok).map(r=>r.n).join(", "))}</small>`:""}</div></div>`).join("")}</div></div>`
     :t.check?`<div class="card"><div class="eyebrow" style="margin-bottom:.5rem">Hast du das?</div><div class="check-list">${t.check.map((c,i)=>`<label class="row" style="gap:.6rem;flex-wrap:nowrap"><input type="checkbox" style="width:22px;min-height:22px;flex-shrink:0" data-c="${i}"> <span>${esc(c)}</span></label>`).join("")}</div></div>`:""}
   ${modelSents.length?`<div class="card tint"><div class="row between"><div class="eyebrow">${/^Alltag/i.test(String(t.reg||""))?"So klingt es natürlich":"So macht es ein Arzt"} <span class="en">sentence by sentence · hold to translate</span></div><button class="icon ghost" data-say="${esc(t.model)}" aria-label="Anhören">${ic("vol")}</button></div>
     <div class="tch-model">${modelSents.map(s=>{const r=roleOf(s);return `<div class="tch-ms">${r?`<span class="tch-role">${esc(r)}</span>`:""}<div class="tch-mt">${glossify(s)}</div></div>`}).join("")}</div></div>`:""}
   ${T?`<div class="card"><div class="eyebrow">Bausteine <span class="en">reuse these frames next time</span></div><ol class="tch-frames">${T.frames.map(f=>`<li>${esc(f)}</li>`).join("")}</ol>
     <div class="tch-words">${T.words.map(w=>`<button class="tch-wd" data-de="${esc(w[0])}" data-en="${esc(w[1])}"><b>${esc(w[0])}</b><small>${esc(w[1])}</small></button>`).join("")}</div><div class="muted ui" style="font-size:.8rem">Wort antippen = ins Deck.</div></div>`:""}
   ${tips.length?`<div class="card tch-next"><div class="eyebrow">Nächstes Mal</div><ol>${tips.slice(0,3).map(x=>`<li>${x}</li>`).join("")}</ol></div>`:""}
   ${tutor&&tutor.followup&&tutor.followup.task?`<div class="card tint stack s"><div class="eyebrow">Selbst korrigieren <span class="en">try the fix yourself</span></div><div>${esc(tutor.followup.task)}</div><div class="typed"><input class="fu-in" autocomplete="off" placeholder="Antwort…"><button class="primary fu-go">Prüfen</button></div><div class="fu-out"></div></div>`:""}
   <div class="row wrap tch-act"><button class="primary tch-retry">${ic("pen")} Nochmal schreiben${T?" mit Bausteinen":""}</button><button class="tch-done">Weiter ${ic("right")}</button></div></div>`;
  // wiring
  const more=$(".tch-more",out);if(more)more.onclick=()=>{$$(".tch-m.more",out).forEach(x=>x.hidden=false);more.remove()};
  $$(".tch-wd",out).forEach(b=>b.onclick=()=>{const de=b.dataset.de,en=b.dataset.en;const k=de.replace(/^(der|die|das) /,"").toLowerCase();const c=DICT[k];if(c&&S.cards[c.id]){toast("Schon im Deck");return}if(c)S.cards[c.id]=newState();else{S.custom.push({de,en,ex:t.model?String(t.model).split(/(?<=[.!?])\s+/).find(s=>s.toLowerCase().includes(k.split(" ")[0]))||"":""});buildDict();S.cards["c:"+(S.custom.length-1)]=newState()}introducedNew(false);saveSoon();b.classList.add("on");toast("Ins Deck: "+de)});
  const fg=$(".fu-go",out);if(fg)fg.onclick=()=>{const v=$(".fu-in",out).value;const g=gradeTyped(v,tutor.followup.answer);$(".fu-out",out).innerHTML=`<p class="${g.q>=2?"ok":"no"}">${g.q>=2?"Richtig.":"Lösung: "+esc(tutor.followup.answer)}</p>`;fb(g.q>=2)};
  const score=(cN==null||cOk===cN)&&nIssues<=1?2:(cN==null||cOk>=cN/2)&&nIssues<=5?1:0;
  if(!tutor){addErrors(A.F.filter(f=>f.orig&&f.fix&&f.key!=="punct"&&f.key!=="len").slice(0,8).map(f=>({type:f.type,original:f.orig,fix:f.fix,why:f.title})),"coach")}
  if(!tutor)logEvent("write",(t.t||"Schreiben")+` · ${nIssues} Lernpunkt${nIssues===1?"":"e"}${cN?` · Inhalt ${cOk}/${cN}`:""}${prev?" · Versuch "+(TCH_ATT.get(box).att||2):""}`,score*50);
  $(".tch-retry",out).onclick=()=>{const ta=box.querySelector(".ft-in");const help=box.querySelector(".tch-help");if(help){help.hidden=false;const fr=help.querySelector('[data-h="frames"]');if(fr&&!fr.classList.contains("on"))fr.click()}if(ta){ta.scrollIntoView({behavior:"smooth",block:"center"});setTimeout(()=>ta.focus(),350)}toast("Verbessere deinen Text – die Bausteine helfen.")};
  let doneOnce=false;$(".tch-done",out).onclick=()=>{if(doneOnce)return;doneOnce=true;logDay("write");S.corrections.push({date:todayKey(),ok:score===2,self:!tutor,n:nIssues});if(S.corrections.length>150)S.corrections=S.corrections.slice(-150);saveSoon();if(o.onDone)o.onDone(tutor?{ok:score===2}:{self:score});else toast("Gespeichert")};
  fb(score>=1)}
function tRing(v,n,label,inv,shown){const p=n?Math.max(0,Math.min(1,v/n)):0;const r=20,c=2*Math.PI*r;const col=p>=.99?"var(--good)":p>=.5?"var(--accent)":"var(--bad,#c0392b)";
  return `<div class="tch-ring"><svg viewBox="0 0 48 48" width="56" height="56"><circle cx="24" cy="24" r="${r}" fill="none" stroke="var(--line)" stroke-width="5"/><circle cx="24" cy="24" r="${r}" fill="none" stroke="${col}" stroke-width="5" stroke-linecap="round" stroke-dasharray="${(c*p).toFixed(1)} ${c.toFixed(1)}" transform="rotate(-90 24 24)"/><text x="24" y="28" text-anchor="middle" font-size="12" font-weight="700" fill="currentColor">${inv?(shown!=null?shown:""):v+"/"+n}</text></svg><small>${esc(label)}</small></div>`}

// ---- before writing: a help ladder (hidden by default, so the task stays a challenge)
const _freeTextOld=freeText;
freeText=function(el,t,o){_freeTextOld(el,t,o);const T=TEACH_TASKS[t&&t.t];const inp=$(".ft-in",el);if(!inp)return;
  const parts=[];if(t.check)parts.push(["plan","Plan",`<ol class="tch-frames">${t.check.map(c=>`<li>${esc(c)}</li>`).join("")}</ol><div class="muted ui" style="font-size:.82rem">Ein Satz pro Punkt.</div>`]);
  if(T)parts.push(["frames","Bausteine",`<ol class="tch-frames">${T.frames.map(f=>`<li>${esc(f)}</li>`).join("")}</ol><button class="sm tch-ins">${ic("plus")} Als Gerüst einfügen</button>`]);
  if(T)parts.push(["words","Wörter",`<div class="tch-words">${T.words.map(w=>`<span class="tch-wd static"><b>${esc(w[0])}</b><small>${esc(w[1])}</small></span>`).join("")}</div>`]);
  if(/vorstell|übergab|Anamnese|Akte/i.test(t.t||""))parts.push(["tips","Tipps",`<ul class="tch-frames"><li>Nomen groß: der <b>P</b>atient, die <b>L</b>uftnot.</li><li>Alter: <b>ein 44-jähriger Patient</b> / <b>Herr X, 44 Jahre</b>.</li><li>Verb an Position 2: <b>Seit zwei Tagen hat er …</b></li><li>Verdacht + DD: <b>Ich vermute …, differentialdiagnostisch …</b></li></ul>`]);
  else parts.push(["tips","Tipps",`<ul class="tch-frames"><li>Nomen groß, Satzanfang groß, Punkt am Ende.</li><li>Verb an Position 2; nach dass/weil/wenn ans Ende.</li><li>${/du/.test(t.reg||"")?"du-Form, locker.":"Sie-Form: Sie, Ihnen, Ihr."}</li></ul>`]);
  const h=document.createElement("div");h.className="tch-help";h.innerHTML=`<div class="row wrap" style="gap:.4rem"><span class="muted ui" style="font-size:.85rem">Hilfe, wenn du sie brauchst:</span>${parts.map(p=>`<button class="sm ghost" data-h="${p[0]}">${p[1]}</button>`).join("")}</div>${parts.map(p=>`<div class="tch-hp" data-hp="${p[0]}" hidden>${p[2]}</div>`).join("")}`;
  inp.parentNode.insertBefore(h,inp);
  $$("[data-h]",h).forEach(b=>b.onclick=()=>{const p=h.querySelector(`[data-hp="${b.dataset.h}"]`);const on=p.hidden;p.hidden=!on;b.classList.toggle("on",on)});
  const ins=$(".tch-ins",h);if(ins)ins.onclick=()=>{if(inp.value.trim()&&!confirmSoft(inp))return;inp.value=T.frames.join("\n");inp.focus();inp.setSelectionRange(inp.value.indexOf("…"),inp.value.indexOf("…")+1)}};
function confirmSoft(inp){if(inp.dataset.sure)return true;inp.dataset.sure="1";toast("Nochmal tippen: dein Text wird durch das Gerüst ersetzt.");return false}

// ---- offline: replace the bare self-check with the coach
const _selfCheckOld=selfCheck;
selfCheck=function(out,text,t,o){teachRender(out,text,t,o,null)};
// ---- tutor: ask for teaching material too, and render through the same page
correct=async function(text,ctx,reg){return SAMPLE.json(`Du bist ein erfahrener, geduldiger DaF-Lehrer mit medizinischem Hintergrund. ${LEARNER} Er ist noch Anfänger: sei klar, konkret und ermutigend, aber ehrlich.
Aufgabe/Kontext: ${ctx}
Erwartetes Register: ${reg}
Der Lernende hat geschrieben:
«${text}»

Korrigiere und LEHRE. Korrekte alternative Formulierungen sind KEINE Fehler. Fasse gleiche Fehler zusammen (z. B. alle kleingeschriebenen Nomen = ein Eintrag). Erklärungen auf Englisch, einfach, mit der Regel.
Antworte NUR mit JSON:
{"ok":true|false,"corrected":"<minimal korrigiert, Bedeutung des Lernenden behalten>","natural":"<so würde es ein deutscher Arzt natürlich sagen>","register_ok":true|false,
"good":["<1–3 konkrete Dinge, die gut waren, Deutsch, kurz>"],
"errors":[{"type":"<einer von: ${ERR_TYPES.join(", ")}>","title":"<kurzer Titel der Regel auf Deutsch>","original":"<fehlerhafte Stelle>","fix":"<Korrektur>","why":"<Regel, 1–2 Sätze, Englisch>","bad":"<kurzer falscher Beispielsatz>","good":"<derselbe Satz richtig>","merke":"<Merksatz, Deutsch, max. 8 Wörter>"}],
"tips":["<genau 3 konkrete Dinge für das nächste Mal, Deutsch, je ein Satz>"],
"note":"<ein Satz Feedback, Englisch>","followup":{"task":"<Lücken- oder Übersetzungssatz auf Deutsch, der den wichtigsten Fehler trainiert>","answer":"<Lösung>"}}`,{modelTier:"default",cache:false})};
const _renderCorrectionOld=renderCorrection;
renderCorrection=function(out,orig,r,t){teachRender(out,orig,t,{onDone:out._onDone},r||{})};

// ================= EXPLAIN (10.3): every answer can be elaborated =================
// One rules library (RULES) that every feedback point can open ("Mehr dazu"), a "Frag nach" tutor question,
// a review of your mistakes at the end of every round, and targeted teaching for dictation, pronunciation,
// typed cards, numbers, exam items, roleplay errors and weak spots. Also browsable: Lernen → Regeln.
const D=(de,en)=>[de,en];
const tbl=(head,rows)=>`<div class="tw"><table class="xp-t"><thead><tr>${head.map(h=>`<th>${h}</th>`).join("")}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map((c,i)=>i?`<td>${c}</td>`:`<th>${c}</th>`).join("")}</tr>`).join("")}</tbody></table></div>`;
const chip=(t,c,l)=>`<span class="dg ${c||""}">${t}${l?`<small>${l}</small>`:""}</span>`;
const RULES={
genus:{g:"Grammatik",t:"Der, die oder das?",en:"Noun gender: learn every noun with its article, but use the endings that predict it.",
 body:`<p>German has three genders. The article is part of the word: learn <b>die Lunge</b>, never just <i>Lunge</i>. The <b>ending</b> often tells you:</p>`+tbl(["","Endungen / Gruppen","Beispiele"],[["<span class='g-die'>die</span>","-ung, -heit, -keit, -schaft, -ion, -tät, -ik, -ie, -ur, most -e","die Untersuchung, die Übelkeit, die Infektion, die Lunge, die Niere"],["<span class='g-das'>das</span>","-chen, -lein, -um, -ment, -ma, Ge-…, verbs as nouns","das Medikament, das Trauma, das Gelenk, das Atmen"],["<span class='g-der'>der</span>","-er (people/tools), -ling, -ismus, -or, -ant, -ent, -ist, days, months, men","der Notarzt, der Monitor, der Montag, der Patient"]])+`<p class="muted">Body parts to know cold: der Arm, das Bein, die Hand, der Fuß, der Bauch, die Brust, das Herz, die Leber, der Magen, das Blut.</p>`,
 ex:[D("Die Untersuchung dauert zehn Minuten.","The examination takes ten minutes."),D("Das Röntgenbild ist unauffällig.","The X-ray is unremarkable."),D("Der Schmerz strahlt in den Arm aus.","The pain radiates into the arm.")],
 pit:["<b>der Magen</b> (-en, masculine), <b>das Herz</b> (irregular: dem Herzen)","<b>das Problem</b>, <b>das Thema</b> (Greek -ma = neuter)","Plural is always <b>die</b>: die Patienten, die Medikamente"],
 merke:"Endung prüfen: -ung/-heit/-keit = die · -chen/-um/-ment = das.",lesson:"g1",drill:"artikel"},
kasus:{g:"Grammatik",t:"Die vier Fälle",en:"Case shows the job of a noun in the sentence; the article changes, mostly in the masculine.",
 body:tbl(["","m","f","n","Plural"],[["Nominativ <small>wer?</small>","der / ein","die / eine","das / ein","die"],["Akkusativ <small>wen? was?</small>","<b>den / einen</b>","die / eine","das / ein","die"],["Dativ <small>wem?</small>","<b>dem / einem</b>","<b>der / einer</b>","<b>dem / einem</b>","<b>den</b> + -n"],["Genitiv <small>wessen?</small>","des / eines + -s","der / einer","des / eines + -s","der"]])+`<div class="dg-row" style="margin-top:.5rem">${chip("Der Arzt","dg-subj","Nom · wer")}${chip("gibt","dg-verb","Verb")}${chip("dem Patienten","dg-p1","Dat · wem")}${chip("eine Tablette","dg-rest","Akk · was")}</div>`,
 ex:[D("Der Arzt untersucht den Patienten.","The doctor examines the patient."),D("Ich gebe dem Patienten eine Tablette.","I give the patient a tablet."),D("Die Werte des Patienten sind stabil.","The patient's values are stable.")],
 pit:["<b>der Patient → den/dem/des Patienten</b> (n-Deklination: also Kollege, Mensch, Herr → Herrn)","Akkusativ changes only the masculine: <i>der → den</i>","Dativ plural adds -n: <i>mit den Kindern</i>"],
 merke:"Nur das Maskulinum ändert sich im Akkusativ: der → den.",lesson:"g4",drill:"faelle"},
praep:{g:"Grammatik",t:"Präpositionen und ihr Fall",en:"Each preposition takes a fixed case; nine 'two-way' prepositions switch between location and movement.",
 body:tbl(["Fall","Präpositionen"],[["Akkusativ","durch, für, gegen, ohne, um"],["Dativ","aus, bei, mit, nach, <b>seit</b>, von, zu, gegenüber"],["Genitiv","wegen, während, trotz, statt"],["Wo? → Dativ<br>Wohin? → Akk.","an, auf, hinter, in, neben, über, unter, vor, zwischen"]])+`<p>Short forms: <b>im</b> (in dem), <b>am</b>, <b>zum</b> (zu dem), <b>zur</b> (zu der), <b>beim</b>, <b>vom</b>, <b>ins</b> (in das).</p>`,
 ex:[D("Seit einer Woche habe ich Husten.","I've had a cough for a week."),D("Legen Sie sich bitte auf die Liege.","Please lie down on the couch. (wohin → Akk.)"),D("Sie liegt auf der Liege.","She is lying on the couch. (wo → Dat.)"),D("Er kommt mit dem Rettungswagen.","He's coming by ambulance.")],
 pit:["<b>seit</b> + Dativ: seit einer Woche, seit zwei Tagen","<b>zum Röntgen</b>, <b>zur Toilette</b>, <b>ins Krankenhaus</b>","Time 'for': <i>seit</i> (still going), <i>für</i> (planned), <i>vor</i> (ago)"],
 merke:"Wo? → Dativ. Wohin? → Akkusativ.",lesson:"g6"},
v2:{g:"Satzbau",t:"Das Verb an Position 2",en:"In a main clause the conjugated verb is the second element, whatever comes first.",
 body:`<div class="dg-row">${chip("Ich","dg-p1","1")}${chip("habe","dg-verb","Verb · 2")}${chip("heute Dienst.","dg-rest","Rest")}</div><div class="dg-row">${chip("Heute","dg-p1","1")}${chip("habe","dg-verb","Verb · 2")}${chip("ich","dg-subj","Subjekt")}${chip("Dienst.","dg-rest","Rest")}</div><div class="dg-row">${chip("Seit gestern","dg-p1","1")}${chip("hat","dg-verb","Verb · 2")}${chip("er","dg-subj","Subjekt")}${chip("Fieber.","dg-rest","Rest")}</div><p>Questions: W-question → verb 2 (<i>Wo tut es weh?</i>); yes/no question → verb 1 (<i>Haben Sie Fieber?</i>). Second verbs (infinitive, participle) go to the <b>end</b>: <i>Ich <b>muss</b> Sie kurz <b>untersuchen</b>.</i></p>`,
 ex:[D("Heute Nacht haben wir drei Zugänge.","Tonight we have three admissions."),D("Im Labor fehlt noch das Kalium.","The potassium is still missing in the lab."),D("Gleich kommt der Oberarzt.","The senior is coming shortly.")],
 pit:["<s>Seit zwei Tagen er hat …</s> → Seit zwei Tagen <b>hat er</b> …","<s>Heute ich bin müde</s> → Heute <b>bin ich</b> müde"],
 merke:"Egal was vorne steht: das Verb ist Nummer 2.",lesson:"g3"},
vend:{g:"Satzbau",t:"Nebensatz: Verb am Ende",en:"After dass, weil, wenn, ob, obwohl, damit, als, nachdem, bevor … the conjugated verb goes to the end, after a comma.",
 body:`<div class="dg-row">${chip("Ich glaube,","dg-rest","")}${chip("dass","dg-p1","Konjunktion")}${chip("er","dg-subj","")}${chip("eine Pneumonie","dg-rest","")}${chip("hat.","dg-verb","Verb am Ende")}</div><div class="dg-row">${chip("…, weil er nicht","dg-rest","")}${chip("atmen","dg-rest","")}${chip("kann.","dg-verb","Modalverb ganz am Ende")}</div><div class="dg-row">${chip("…, dass sie","dg-rest","")}${chip("gestürzt","dg-rest","")}${chip("ist.","dg-verb","Hilfsverb am Ende")}</div><p>If the Nebensatz comes <b>first</b>, the main clause starts with the verb: <i>Wenn die Schmerzen stärker werden, <b>kommen</b> Sie bitte wieder.</i></p>`,
 ex:[D("Rufen Sie mich an, wenn der Blutdruck unter 90 fällt.","Call me if the blood pressure drops below 90."),D("Ich frage, ob Sie Allergien haben.","I'm asking whether you have allergies."),D("Weil er Blutverdünner nimmt, machen wir ein CT.","Because he takes blood thinners, we're doing a CT.")],
 pit:["<s>dass er hat Fieber</s> → dass er Fieber <b>hat</b>","Always a comma before dass/weil/wenn/ob"],
 merke:"dass / weil / wenn / ob → Komma, Verb ans Ende.",lesson:"g11"},
modal:{g:"Grammatik",t:"Modalverben & Satzklammer",en:"können, müssen, dürfen, sollen, wollen, möchten: conjugated in position 2, the main verb as infinitive at the end.",
 body:`<div class="dg-row">${chip("Ich","dg-p1","1")}${chip("muss","dg-verb","Modal · 2")}${chip("Ihnen Blut","dg-rest","Mitte")}${chip("abnehmen.","dg-verb","Infinitiv · Ende")}</div>`+tbl(["","können","müssen","dürfen","sollen"],[["ich","kann","muss","darf","soll"],["Sie / wir","können","müssen","dürfen","sollen"],["er / sie","kann","muss","darf","soll"]])+`<p>Polite: <b>Könnten Sie …?</b> <b>Dürfte ich …?</b> <b>Ich würde gern …</b> (Konjunktiv II). <i>nicht dürfen</i> = must not; <i>nicht müssen</i> = don't have to.</p>`,
 ex:[D("Sie dürfen ab jetzt nichts mehr essen.","From now on you must not eat anything."),D("Sie müssen nicht nüchtern bleiben.","You don't have to stay fasted."),D("Können Sie den Arm heben?","Can you lift your arm?")],
 pit:["<b>nicht dürfen</b> ≠ <b>nicht müssen</b>","ich/er <b>kann</b> (no -t), ich/er <b>muss</b>"],
 merke:"Modalverb Position 2, Infinitiv ans Ende.",lesson:"g7"},
trenn:{g:"Grammatik",t:"Trennbare Verben & Imperativ",en:"Verbs with prefixes like auf-, ein-, ab-, an-, aus-, mit-, zu- split: the prefix goes to the end.",
 body:`<div class="dg-row">${chip("Atmen","dg-verb","Verb · 1")}${chip("Sie bitte tief","dg-rest","")}${chip("ein.","dg-verb","Präfix · Ende")}</div><p>Imperativ (Sie-Form): verb first + <b>Sie</b>: <i>Machen Sie bitte den Mund auf. Legen Sie sich hin.</i> Perfekt: <i>ein<b>ge</b>nommen, auf<b>ge</b>standen</i>. Inseparable (be-, er-, ver-, zer-, ent-, emp-, ge-) never split: <i>Ich untersuche Sie.</i></p>`,
 ex:[D("Machen Sie bitte den Oberkörper frei.","Please undress your upper body."),D("Nehmen Sie die Tablette morgens ein.","Take the tablet in the morning."),D("Halten Sie kurz die Luft an.","Hold your breath for a moment.")],
 pit:["<s>Sie einatmen bitte</s> → Atmen Sie bitte ein","Perfekt: eingenommen (not geeinnommen)"],
 merke:"Präfix ans Ende; Imperativ: Verb + Sie.",lesson:"g8"},
perfekt:{g:"Grammatik",t:"Perfekt: haben oder sein",en:"Spoken past tense = haben/sein (position 2) + participle (end). sein for movement and change of state.",
 body:tbl(["","Hilfsverb","Beispiele"],[["meist","<b>haben</b>","Ich habe ihn untersucht. Er hat erbrochen."],["Bewegung / Veränderung","<b>sein</b>","Er ist gestürzt / gefallen / gekommen / bewusstlos geworden. Sie ist gestorben."]])+`<p>Participle: <i>ge-…-t</i> (gemacht), <i>ge-…-en</i> (genommen); no ge- for <b>-ieren</b> (operiert, intubiert) and <b>be-/er-/ver-/zer-</b> (untersucht, verschrieben); separable: auf<b>ge</b>standen.</p>`,
 ex:[D("Er ist die Treppe heruntergefallen.","He fell down the stairs."),D("Haben Sie heute schon Tabletten genommen?","Have you taken any tablets today?"),D("Wir haben ihn gestern operiert.","We operated on him yesterday.")],
 pit:["<s>Er hat gestürzt</s> → Er <b>ist</b> gestürzt","<s>geoperiert</s> → operiert"],
 merke:"Bewegung oder Veränderung → sein.",lesson:"g9"},
praet:{g:"Grammatik",t:"Präteritum",en:"Written past tense (reports, books). In speech mostly only war, hatte and the modals.",
 body:tbl(["","sein","haben","können"],[["ich / er","war","hatte","konnte"],["wir / sie","waren","hatten","konnten"]])+`<p>Arztbrief and literature use Präteritum: <i>Der Patient stellte sich mit Thoraxschmerzen vor.</i></p>`,
 ex:[D("Der Patient war bei Aufnahme wach und orientiert.","On admission the patient was awake and oriented."),D("Die Schmerzen begannen gestern Abend.","The pain began last night.")],pit:["In conversation say <i>Ich habe es gesehen</i>, not <i>Ich sah es</i>."],merke:"Sprechen: Perfekt · Schreiben: Präteritum.",lesson:"g10"},
gen:{g:"Grammatik",t:"Genitiv & Possessiv",en:"Possession: des/der + noun (masc./neut. add -s); in speech often von + Dativ.",
 body:tbl(["","Possessiv (Nom.)"],[["ich","mein / meine"],["Sie","Ihr / Ihre"],["er","sein / seine"],["sie","ihr / ihre"]])+`<p>Genitiv: <i>die Werte <b>des</b> Patient<b>en</b></i>, <i>die Tochter <b>der</b> Patientin</i>. Spoken: <i>die Tochter von der Patientin</i>.</p>`,
 ex:[D("Ist das Ihre Tochter?","Is that your daughter?"),D("Der Zustand des Patienten ist stabil.","The patient's condition is stable.")],pit:["Formal Sie → <b>Ihr</b> with capital I"],merke:"Sie → Ihr, Ihre (groß).",lesson:"g12"},
adj:{g:"Grammatik",t:"Adjektivendungen",en:"Adjectives before a noun take an ending; after der/die/das mostly -e/-en, after ein/kein the ending shows the gender.",
 body:tbl(["","nach der/die/das","nach ein/kein","ohne Artikel"],[["m Nom","der akut<b>e</b> Schmerz","ein akut<b>er</b> Schmerz","akut<b>er</b> Schmerz"],["f Nom","die stark<b>e</b> Blutung","eine stark<b>e</b> Blutung","stark<b>e</b> Blutung"],["n Nom","das neu<b>e</b> EKG","ein neu<b>es</b> EKG","neu<b>es</b> EKG"],["m Akk","den akut<b>en</b> Schmerz","einen akut<b>en</b> Schmerz","akut<b>en</b> Schmerz"],["Dativ / Plural","-en","-en","Dat -en / Pl Nom -e"]])+`<p>Age: <b>ein 44-jährig<span class="g-der">er</span> Patient</b>, <b>eine 44-jährig<span class="g-die">e</span> Patientin</b>, <b>einen 44-jährig<span class="g-der">en</span> Patienten</b>.</p>`,
 ex:[D("Ein 67-jähriger Patient mit akuter Luftnot.","A 67-year-old patient with acute shortness of breath."),D("Bekannt ist eine arterielle Hypertonie.","Known: arterial hypertension.")],pit:["Zahl + -jährig + Endung + Nomen"],merke:"Nach ein: die Endung zeigt das Genus (-er/-e/-es).",lesson:"g13"},
k2:{g:"Grammatik",t:"Konjunktiv II: höflich & hypothetisch",en:"würde + infinitive, könnte, dürfte, hätte, wäre: polite requests and 'would'.",
 body:tbl(["Direkt","Höflich"],[["Machen Sie den Mund auf.","<b>Könnten</b> Sie bitte den Mund aufmachen?"],["Ich will Sie untersuchen.","Ich <b>würde</b> Sie gern untersuchen."],["Darf ich?","<b>Dürfte</b> ich kurz …?"],["Haben Sie Zeit?","<b>Hätten</b> Sie kurz Zeit?"]]),
 ex:[D("Ich würde Ihnen gern ein paar Fragen stellen.","I'd like to ask you a few questions."),D("Wäre es möglich, dass Ihre Tochter dolmetscht?","Would it be possible for your daughter to interpret?")],pit:["Too many würde sounds clumsy: use könnte, hätte, wäre"],merke:"Bitte an Patienten: Könnten Sie …?",lesson:"g14"},
passiv:{g:"Grammatik",t:"Passiv",en:"Focus on the action: werden + participle. Typical in reports and Aufklärung.",
 body:`<div class="dg-row">${chip("Der Patient","dg-subj","")}${chip("wird","dg-verb","werden · 2")}${chip("morgen","dg-rest","")}${chip("operiert.","dg-verb","Partizip · Ende")}</div><p>Past: <i>wurde operiert</i>; with modal: <i>muss operiert werden</i>.</p>`,
 ex:[D("Es wurde eine Blutkultur abgenommen.","A blood culture was taken."),D("Die Wunde muss genäht werden.","The wound has to be stitched.")],pit:["werden (process) vs. sein (state): wird operiert / ist operiert"],merke:"werden + Partizip.",lesson:"g15"},
gross:{g:"Schreiben",t:"Groß- und Kleinschreibung",en:"Nouns, names, the formal Sie/Ihr and sentence beginnings are capitalised. Everything else is small.",
 body:`<div class="dg-row">${chip("der <u>P</u>atient","dg-add","Nomen")}${chip("die <u>L</u>uftnot","dg-add","Nomen")}${chip("seit zwei <u>T</u>agen","dg-add","Nomen")}${chip("<u>S</u>ie / <u>I</u>hnen","dg-add","Sie-Form")}</div><p>Test: if you can put <b>der/die/das</b> or an adjective in front, it's a noun. Verbs used as nouns too: <i>beim <b>A</b>tmen</i>, <i>das <b>E</b>ssen</i>.</p>`,
 ex:[D("Der Patient hat seit gestern Fieber.","The patient has had a fever since yesterday."),D("Haben Sie Schmerzen beim Atmen?","Do you have pain when breathing?")],pit:["Adjectives stay small: <i>akute</i> Luftnot","<i>du</i> small, <i>Sie</i> (you) capital, <i>sie</i> (she/they) small"],merke:"Artikel davor möglich → groß.",lesson:"g1"},
schreib:{g:"Schreiben",t:"Rechtschreibung: ä ö ü ß, ie/ei, Doppelkonsonant",en:"The spellings that change meaning or look careless in a chart.",
 body:tbl(["","Regel","Beispiel"],[["ä ö ü","without a German keyboard: ae, oe, ue","Übelkeit = Uebelkeit"],["ß","after a long vowel or ei/au/eu; after a short vowel ss","Fuß, heiß · Wasser, muss"],["ie / ei","ie = long i, ei = 'ai'","Fieber, Niere · Eiter, weich"],["Doppelkonsonant","double consonant → short vowel before","Bett, kommen, Schnitt"],["h nach Vokal","silent, makes vowel long","sehr, Zahn, Stuhl"]]),
 ex:[D("Die Patientin hat seit heute früh Übelkeit.","The patient has had nausea since this morning."),D("Der Fuß ist geschwollen und heiß.","The foot is swollen and hot.")],pit:["Fieber (ie) · Eiter (ei)","muss (ss) · Fuß (ß)"],merke:"ie = langes i, ei = ai.",lesson:"g1"},
register:{g:"Gespräch",t:"Sie oder du · Fachsprache oder Laiensprache",en:"Choose the form for the person: Sie + everyday words for patients; Fachsprache with colleagues.",
 body:tbl(["Mit …","Form","Wörter"],[["Patienten, Angehörigen, Ämtern","<b>Sie</b>, Herr/Frau + Nachname","Laiensprache: Luftnot, Bluthochdruck, Lungenentzündung"],["Kolleg:innen (Stationsteam)","meist <b>du</b> (wenn angeboten)","Fachsprache: Dyspnoe, Hypertonie, Pneumonie"],["Oberarzt / Chefarzt","<b>Sie</b> bis angeboten","Fachsprache, knapp"]])+`<p>The older or more senior person offers <i>du</i>.</p>`,
 ex:[D("Haben Sie Luftnot?","Are you short of breath? (patient)"),D("Der Patient ist dyspnoisch, SpO₂ 89 %.","The patient is dyspnoeic, SpO₂ 89%. (colleague)")],pit:["Latin with patients sounds cold and is not understood","du with a patient is rude"],merke:"Patient → Sie + Alltagswort.",lesson:"m1"},
gespraech:{g:"Gespräch",t:"Gute Gesprächsführung mit Patienten",en:"Open question first, then specific ones; simple words; show empathy; check understanding.",
 body:tbl(["Schritt","So klingt es"],[["Offen anfangen","Was führt Sie zu uns? Erzählen Sie mal."],["Gezielt nachfragen","Seit wann? Wo genau? Wie stark von 0 bis 10?"],["Gefühl benennen","Ich sehe, dass Sie sich Sorgen machen."],["Laienwörter","Lungenentzündung statt Pneumonie"],["Verständnis prüfen","Können Sie mir mit eigenen Worten sagen, wie Sie die Tabletten nehmen?"],["Zusammenfassen","Ich fasse kurz zusammen: …"]]),
 ex:[D("Erzählen Sie mal, was passiert ist.","Tell me what happened."),D("Das klingt sehr belastend.","That sounds very stressful.")],pit:["Too early conclusion: ask first, then explain","Yes/no questions too early close the conversation"],merke:"Offen → gezielt → zusammenfassen.",lesson:"m2"},
vorstellung:{g:"Gespräch",t:"Patientenvorstellung an den Oberarzt",en:"Fixed order, one sentence each: who, age, main symptom + duration, history, findings, working diagnosis + DD, plan.",
 body:`<ol class="xp-ol"><li><b>Ich stelle Ihnen</b> Herrn/Frau … <b>vor</b>, … Jahre,</li><li>der/die sich <b>mit seit</b> … <b>zunehmender</b> … <b>vorstellt</b>.</li><li><b>Bekannt sind</b> eine … und ein …</li><li><b>Klinisch fanden sich</b> …, <b>bei</b> einer Sättigung von … %.</li><li><b>Ich vermute</b> eine …, <b>differentialdiagnostisch</b> eine …</li><li><b>Ich schlage</b> … <b>vor</b>.</li></ol>`,
 ex:[D("Ich stelle Ihnen Frau Wagner vor, 72 Jahre, die sich mit seit heute Morgen bestehender Verwirrtheit vorstellt.","Let me present Mrs Wagner, 72, who presents with confusion since this morning.")],pit:["Not 'ich habe einen Patienten'","Verdacht without DD sounds unsure"],merke:"Wer · Leitsymptom · Vorgeschichte · Befund · Verdacht + DD · Procedere.",lesson:"m5"},
doku:{g:"Schreiben",t:"Nominalstil für die Akte",en:"Charts use noun phrases and abbreviations, no full sentences, no 'ich'.",
 body:tbl(["Gesprochen","Akte"],[["Er hat seit zwei Tagen Bauchschmerzen.","Seit 2 d Bauchschmerzen."],["Ich habe den Bauch untersucht, er war weich.","Abdomen weich, kein Druckschmerz."],["Wir machen ein Labor und einen Ultraschall.","Procedere: Labor, Sono Abdomen."]]),
 ex:[D("Anamnese: seit 12 h zunehmende Schmerzen re. Unterbauch.","History: increasing RLQ pain for 12 h.")],pit:["No 'ich/er hat' in the chart"],merke:"Akte: Nomen, Zahlen, Abkürzungen.",lesson:"m7"},
zahlen:{g:"Wortschatz",t:"Zahlen im Dienst",en:"German says units before tens: 47 = sieben-und-vierzig. Decimals use a comma.",
 body:`<div class="dg-row">${chip("47","dg-p1","")}<span class="ar">→</span>${chip("sieben","dg-verb","Einer zuerst")}${chip("und","dg-rest","")}${chip("vierzig","dg-subj","Zehner")}</div>`+tbl(["Schreiben","Sagen"],[["RR 120/80","hundertzwanzig zu achtzig"],["37,8 °C","siebenunddreißig Komma acht"],["K⁺ 3,2","Kalium drei Komma zwei"],["14:30","vierzehn Uhr dreißig · halb drei"],["5 mg","fünf Milligramm"],["01.11.","der erste Elfte"]]),
 ex:[D("Der Blutdruck ist hundertfünfundsechzig zu fünfundneunzig.","Blood pressure is 165 over 95."),D("Die Sättigung liegt bei vierundachtzig Prozent.","Saturation is 84 percent.")],pit:["halb drei = 2:30 (half before three)","Komma, not point: 37,5"],merke:"Einer vor Zehner: einundzwanzig.",drill:"numbers"},
frage:{g:"Satzbau",t:"Fragen stellen",en:"W-questions: W-word + verb + subject. Yes/no: verb first.",
 body:tbl(["Typ","Struktur","Beispiel"],[["W-Frage","W-Wort · Verb · Subjekt","Wo tut es weh? Seit wann haben Sie das?"],["Ja/Nein","Verb · Subjekt · …","Haben Sie Fieber? Nehmen Sie Blutverdünner?"],["Höflich","Könnten Sie … ?","Könnten Sie mir zeigen, wo?"]]),
 ex:[D("Wann hat es angefangen?","When did it start?"),D("Strahlt der Schmerz aus?","Does the pain radiate?")],pit:["Seit wann? (since when) for ongoing symptoms"],merke:"Ja/Nein-Frage: Verb zuerst.",lesson:"m2"},
negation:{g:"Grammatik",t:"nicht oder kein",en:"kein negates nouns with ein/no article; nicht negates everything else.",
 body:tbl(["","Beispiel"],[["kein + Nomen","Ich habe <b>keine</b> Schmerzen. <b>Kein</b> Fieber."],["nicht","Das tut <b>nicht</b> weh. Ich rauche <b>nicht</b>."],["doch","Antwort auf negative Frage: Haben Sie keine Allergien? – <b>Doch</b>, gegen Penicillin."]]),
 ex:[D("Haben Sie keine Allergien? – Doch, gegen Penicillin.","No allergies? – Yes, to penicillin.")],pit:["<s>Ich habe nicht Fieber</s> → kein Fieber"],merke:"Nomen → kein, sonst nicht.",lesson:"g2"},
aussprache:{g:"Aussprache",t:"Aussprache für Arabischsprechende",en:"The sounds that most often make words hard to understand, and how to make them.",
 body:tbl(["Laut","So geht's","Wörter"],[["ü","say 'i', round the lips (whistle)","Übelkeit, müde, für"],["ö","say 'e', round the lips","hören, Röntgen"],["ich-Laut","whisper 'y' (like 'huge') — not خ, not ش","ich, Milch, Bauch<b>ch</b>en"],["ach-Laut","like a soft خ","Bauch, acht, Nacht"],["p ≠ b","p with a puff of air","Patient, Puls, Papier"],["e / i","short i in 'bitte', long ie in 'Fieber'","bitte, Fieber, Niere"],["Auslaut","final b/d/g sound p/t/k","Tag [k], Hand [t]"],["sp/st","at the start: schp/scht","Stuhl, Spritze"],["z","= ts","Zimmer, Herz"],["-e / -er","-e = short 'uh', -er ≈ 'a'","Lunge, Fieber"]]),
 ex:[D("Haben Sie Übelkeit?","Do you have nausea?"),D("Ich höre Ihr Herz ab.","I'm listening to your heart.")],pit:["Patient ≠ Batient","ich ≠ isch / ikh"],merke:"ü = i mit runden Lippen.",lesson:"g0"},
abk:{g:"Wortschatz",t:"Abkürzungen in der Klinik",en:"Common chart abbreviations; say them in full to patients.",
 body:tbl(["Abk.","Bedeutung"],[["Z. n.","Zustand nach (status post)"],["V. a.","Verdacht auf"],["DD","Differentialdiagnose"],["o. B.","ohne Befund (unremarkable)"],["AZ / EZ","Allgemein- / Ernährungszustand"],["RR","Blutdruck (Riva-Rocci)"],["AF","Atemfrequenz (not atrial fibrillation!)"],["VHF","Vorhofflimmern"],["BGA","Blutgasanalyse"]]),
 ex:[D("Z. n. Sturz, cCT o. B.","Status post fall, CT head unremarkable.")],pit:["AF = Atemfrequenz in German charts"],merke:"Zur Akte: Abk. · Zum Patienten: ausgeschrieben.",drill:"abbr",lesson:"m7"},
satzbau_lit:{g:"Literatur",t:"Wortstellung in Versen",en:"Poetry bends word order for rhythm and rhyme; read it back into normal order.",
 body:`<p>Goethe: <i>Habe nun, ach! Philosophie … durchaus studiert</i> = Ich habe nun leider Philosophie … gründlich studiert. Subjects can drop, verbs move to the end, old forms appear (<i>ward</i> = wurde, <i>itzt</i> = jetzt).</p>`,ex:[D("Verweile doch, du bist so schön!","Stay a while, you are so beautiful!")],pit:["Don't copy verse word order into speech"],merke:"Vers erst in normale Wortstellung bringen.",lesson:"g16"}
};
// map error types / feedback text → rule
const ERR_RULE={"Kasus":"kasus","Artikel/Genus":"genus","Konjugation":"modal","Wortstellung":"v2","Präposition":"praep","Nebensatz":"vend","Adjektivendung":"adj","Wortwahl":"register","Register":"register","Rechtschreibung":"schreib","Sonstiges":""};
const RULE_RX=[[/\b(gender|genus|feminine|neuter|masculine|article|artikel)\b|-ung|-chen|suffix/i,"genus"],[/wechsel|location|motion|wo\?|wohin/i,"praep"],[/\b(seit|mit|für|durch|gegen|ohne|aus|bei|nach|von|zu|wegen)\b\s*\+|preposition|präposition/i,"praep"],
 [/akkusativ|accusative|dativ|dative|genitiv|genitive|nominativ|case\b|kasus/i,"kasus"],[/nebensatz|subordinate|verb.{0,12}end|dass|weil|relative/i,"vend"],[/position 2|v2|word order|wortstellung|inversion/i,"v2"],
 [/perfekt|participle|partizip|present perfect/i,"perfekt"],[/präteritum|simple past|preterite/i,"praet"],[/konjunktiv ii|würde|polite|höflich|könnten/i,"k2"],[/modal|können|müssen|dürfen|sollen/i,"modal"],[/separable|trennbar|imperativ|imperative/i,"trenn"],
 [/adjective|adjektiv|-jährig/i,"adj"],[/passiv|passive/i,"passiv"],[/genitive|possessive|possessiv/i,"gen"],[/capital|großschreib|kleinschreib/i,"gross"],[/spelling|rechtschreib|umlaut|ß/i,"schreib"],
 [/\bsie\b.*formal|formal|register|\bdu\b|latin|lay (word|term)|laien|jargon/i,"register"],[/abbreviation|abkürz|^\s*[A-Z]{2,4}\s*$/i,"abk"],[/number|zahl|blutdruck|rr |komma/i,"zahlen"],
 [/open question|empath|patient says|patient sagt|patienten|conclusion|reassur|feeling|understand/i,"gespraech"],[/presentation|vorstellung|oberarzt/i,"vorstellung"],[/kein|nicht|negat/i,"negation"],[/faust|goethe|vers|poem|gedicht/i,"satzbau_lit"]];
