// 11.4: "Fast!" only for a real typo – one word, one letter, not an ending or a participle form (getrinkt ≠ getrunken)
function nearTypo(got,ans){const T=x=>String(x||"").toLowerCase().replace(/[.,!?;:"„“]/g," ").trim().split(/\s+/).filter(Boolean);const a=T(got),b=T(ans);if(a.length!==b.length)return false;const d=[];for(let i=0;i<a.length;i++)if(a[i]!==b[i])d.push([a[i],b[i]]);if(d.length!==1)return false;const [x,y]=d[0];
  const U=w=>w.replace(/ä/g,"a").replace(/ö/g,"o").replace(/ü/g,"u").replace(/ß/g,"ss");if(U(x)===U(y)&&x.length!==y.length)return true;if(U(x)===U(y))return true;
  if(/^ge/.test(y)&&/^ge/.test(x))return false;if(Math.min(x.length,y.length)<4)return false;
  let p=0;while(p<x.length&&p<y.length&&x[p]===y[p])p++;if(p>=Math.min(x.length,y.length)-2){const E=/^(e|en|er|es|em|n|s|t|st|et|te|ten)?$/;if(E.test(x.slice(p))&&E.test(y.slice(p)))return false} // an ending difference is grammar, not a typo
  const lev=(s,t)=>{const m=[...Array(t.length+1).keys()];for(let i=1;i<=s.length;i++){let pr=m[0];m[0]=i;for(let j=1;j<=t.length;j++){const tmp=m[j];m[j]=Math.min(m[j]+1,m[j-1]+1,pr+(s[i-1]===t[j-1]?0:1));pr=tmp}}return m[t.length]};return lev(x,y)<=1}

// ================= CITRUS HUB + GOOGLE DRIVE (11.1) =================
// Mephisto joins the Citrus hub (claude/hub-contract.md): one shared Google Cloud project, no backend.
//   My Apps/hub/mephisto/state.json   — the learner's whole progress (Drive is the master copy; every device syncs it)
//   My Apps/hub/mephisto/status.json  — the hub snapshot every app writes (summary, today, week, asks, pending, extra)
//   My Apps/hub/citrus/plan.json (fallback hub/scheduler/) — Citrus's answer: today's blocks per app (read, shown on Heute)
//   Google Calendar                   — shift events → duty days (streak protection, planning)
// Sign-in: Google Identity Services token client (same client id as the other apps, pasted once in Settings).
// Only in the installed app / GitHub Pages copy: the claude.ai artifact origin cannot sign in to Google.
