function gSet(a){try{if(a)localStorage.setItem(HUB.KEY,JSON.stringify(a));else localStorage.removeItem(HUB.KEY)}catch(e){}}
function gToken(){const a=gAuth();return a&&a.token&&a.exp>Date.now()+30000?a.token:null}
function gConf(){S.google=S.google||{};return S.google}
const syncedAt=()=>{try{return localStorage.getItem("mephisto_synced_at")||""}catch(e){return ""}};const setSynced=v=>{try{localStorage.setItem("mephisto_synced_at",v||"")}catch(e){}};
