function labLaut(box){let i=0;const draw=()=>{const p=PAIRS[i%PAIRS.length];box.innerHTML=`<div class="stack s"><div class="eyebrow">Minimalpaar ${i%PAIRS.length+1} / ${PAIRS.length} · <span class="en">${esc(p[2])}</span></div><div class="lp-pair"><button class="lp-w" data-say="${esc(p[0])}"><span>${esc(p[0])}</span><small>${ic("vol")}</small></button><button class="lp-w" data-say="${esc(p[1])}"><span>${esc(p[1])}</span><small>${ic("vol")}</small></button></div>
    <div class="card stack s"><div class="eyebrow">Hörtest <span class="en">which one did you hear?</span></div><div class="row"><button class="sm lp-play">${ic("play")} Eins abspielen</button><span class="muted ui lp-st"></span></div><div class="row lp-ans" hidden><button class="sm" data-g="0">${esc(p[0])}</button><button class="sm" data-g="1">${esc(p[1])}</button></div></div>
    ${SR?`<div class="card stack s"><div class="eyebrow">Sprechtest <span class="en">say one, the phone guesses</span></div><div class="row"><button class="icon lp-mic need-sr">${ic("mic")}</button><span class="muted ui lp-heard"></span></div></div>`:""}
    <div class="row wrap"><button class="sm lp-prev">${ic("back")}</button><button class="sm lp-next">Nächstes Paar ${ic("chev")}</button>${typeof xpBtn==="function"?xpBtn("aussprache"):""}</div></div>`;
    let target=-1;$(".lp-play",box).onclick=()=>{target=Math.random()<.5?0:1;say(p[target],{silent:true});$(".lp-ans",box).hidden=false;$(".lp-st",box).textContent=""};$$(".lp-ans button",box).forEach(b=>b.onclick=()=>{if(target<0)return;const ok=+b.dataset.g===target;fb(ok);$(".lp-st",box).textContent=ok?"Richtig gehört.":"Es war „"+p[target]+"“.";$(".lp-ans",box).hidden=true;S.lp=S.lp||{n:0,ok:0};S.lp.n++;if(ok)S.lp.ok++;saveSoon()});
    const mic=$(".lp-mic",box);if(mic)mic.onclick=()=>micListen(mic,{}).then(t=>{if(t==null)return;const h=String(t).toLowerCase();const a=similarity(h,p[0]),b=similarity(h,p[1]);$(".lp-heard",box).textContent=`Gehört: „${t}“ → ${a>=b?p[0]:p[1]}`;fb(true)});
    $(".lp-prev",box).onclick=()=>{i=(i+PAIRS.length-1)%PAIRS.length;draw()};$(".lp-next",box).onclick=()=>{i++;draw()}};draw()}
