// ---- 0. round-2 audit corrections (x_fix.js TEXT_FIX): exact-substring replacements inside one content area
//         (tag-tolerant for HTML bodies). ADD_ALT adds an accepted answer; PATH: sets one exam field by position.
//         Runs once now and once more at the end of this file for items created later in it.
function applyTextFix(list){const AREA={kompass:()=>[typeof KOMPASS!=="undefined"?KOMPASS:[]],grammar:()=>[GRAMMAR],rules:()=>[RULES],texts:()=>[TEXTS],hoeren:()=>[typeof HOEREN!=="undefined"?HOEREN:[]],lessons_med:()=>[MEDL],lessons_alltag:()=>[ALLTAG],abzw:()=>[typeof ABZW!=="undefined"?ABZW:[]],fsp_cases:()=>[FSP_CASES],exams:()=>[EXAMS],tasks:()=>[TASKS],kultur:()=>[typeof KULTUR!=="undefined"?KULTUR:[]],terms:()=>[TERMS],abbr:()=>[ABBR],conj:()=>[CONJ,typeof CONJ_EXTRA!=="undefined"?CONJ_EXTRA:[]],misc:()=>[typeof RESPOND!=="undefined"?RESPOND:[],typeof CASES!=="undefined"?CASES:[],typeof TALKS!=="undefined"?TALKS:{},typeof PAIRS!=="undefined"?PAIRS:[],typeof TEACH_Q!=="undefined"?TEACH_Q:[],(()=>{try{return SATZ2}catch(e){return []}})()]};
  const esc2=s=>s.replace(/[.*+?^${}()|[\]\\]/g,"\\$&");let ok=0;const miss=[];
  const walk=(o,old,neu,seen,loose)=>{let n=0;if(!o||typeof o!=="object"||seen.has(o))return 0;seen.add(o);for(const k of Object.keys(o)){const v=o[k];if(typeof v==="string"){if(v.includes(old)){o[k]=v.split(old).join(neu);n++}else if(loose&&/</.test(v)){const re=new RegExp(old.trim().split(/\s+/).map(esc2).join("(?:\\s|<[^>]+>|&nbsp;)+"));if(re.test(v)){o[k]=v.replace(re,neu);n++}}}else if(v&&typeof v==="object")n+=walk(v,old,neu,seen,loose)}return n};
  list.forEach(row=>{const [area,id,old,neu]=row;
    if(area==="PATH:exams"){const [tid,...rest]=id.split("/");let o=null;Object.values(EXAMS).forEach(E=>{const tt=E.teile.find(x=>x.id===tid);if(tt)o=tt});for(let i=0;o&&i<rest.length-1;i++)o=o[isNaN(rest[i])?rest[i]:+rest[i]];const last=rest[rest.length-1];if(o&&o[last]===old){o[last]=neu;ok++}else miss.push(row);return}
    if(/^ADD_ALT:/.test(neu)){const alt=neu.replace(/^ADD_ALT:\s*/,"");let hit=0;GRAMMAR.forEach(g=>[].concat(g.ex||[],g.quiz||[]).forEach(e=>{if(e&&(e.q===old||e.a===old)&&!(e.alt||[]).includes(alt)){e.alt=(e.alt||[]).concat([alt]);hit++}}));hit?ok++:miss.push(row);return}
    const roots=(AREA[area]||(()=>[]))();let n=0;roots.forEach(r=>n+=walk(r,old,neu,new Set(),false));if(!n)roots.forEach(r=>n+=walk(r,old,neu,new Set(),true));n?ok++:miss.push(row)});return {ok,miss}}
if(typeof TEXT_FIX!=="undefined"&&TEXT_FIX.length){const r=applyTextFix(TEXT_FIX);TEXT_FIX._ok=r.ok;TEXT_FIX._miss=r.miss}

// ---- 1. the learner's level: the higher of the word-based estimate and the placement the learner chose
function learnerLv(){let e=0;try{e=LV(levelEstimate().stufe)}catch(x){}const p=S.placement?LV(S.placement):0;return Math.max(e,p)}
levelCap=function(){return Math.min(4,learnerLv()+1)};

