function placeHTML(){const cur=S.placement||"";return `<div class="card stack s place-card no-sig"><div class="eyebrow">Einstufung <span class="en">where do you stand?</span></div><h3>Wo stehst du gerade?</h3><p class="muted ui" style="font-size:.9rem">Die App startet den Plan an der passenden Stelle und gibt dir nur Aufgaben, die zu deinem Niveau passen. Du kannst das jederzeit ändern.<br><span class="en">Pick your level; the plan starts at the right week and you can change it any time. Between two levels? Choose the lower one.</span></p>
  <div class="place-opts">${PLACE.map(p=>`<button class="place-o ${cur===p[0]?"on":""}" data-l="${p[0]}"><b>${p[0]}</b><span>${p[1]}</span><small>${p[2]}</small><small class="en">${({A1:"a few words, first sentences",A2:"simple conversations, dative",B1:"daily life works, subordinate clauses",B2:"B2 exam in sight",C1:"B2 passed, FSP soon"})[p[0]]||""}</small></button>`).join("")}</div>
  <div class="eyebrow">Zeit pro Tag</div><div class="seg place-min">${[20,40,60,90].map(n=>`<button data-n="${n}" class="${S.minutes===n?"on":""}">${n} Min.</button>`).join("")}</div>
  <div class="row"><button class="primary place-go" ${cur?"":"disabled"}>Los geht's</button>${S.placed?`<button class="sm ghost place-x">Abbrechen</button>`:""}</div></div>`}
function placeWire(root,done){let lv=S.placement||"",mn=S.minutes;const go=$(".place-go",root);
  $$(".place-o",root).forEach(b=>b.onclick=()=>{lv=b.dataset.l;$$(".place-o",root).forEach(x=>x.classList.toggle("on",x===b));go.disabled=false});
  $$(".place-min button",root).forEach(b=>b.onclick=()=>{mn=+b.dataset.n;$$(".place-min button",root).forEach(x=>x.classList.toggle("on",x===b))});
  const x=$(".place-x",root);if(x)x.onclick=()=>done&&done(false);
  go.onclick=()=>{const P=PLACE.find(p=>p[0]===lv);if(!P)return;const prev=S.placement;S.placement=lv;S.placed=todayKey();S.minutes=mn;
    if(weekNumber()<P[3]||(prev&&prev!==lv)){const keepDay=weekDay();S.startDate=addDays(todayKey(),-((P[3]-1)*7+keepDay-1))}
    if(lv==="C1"&&S.focus!=="pruefung")S.focus="pruefung";S.today=null;logEvent("plan","Einstufung "+lv+" · "+mn+" Min./Tag · Woche "+weekNumber());saveSoon();toast("Plan ab Woche "+weekNumber()+" · "+lv);if(done)done(true)}}
