// ---- 6. "Mehr dazu" from the mistake: the feedback text first, then the lesson the exercise belongs to, then the question stem
xpEnhance=function(node){if(!node||node.dataset.xp)return;node.dataset.xp="1";const q=node.closest(".q")||node.parentElement;
  const why=node.innerText||"";const stem=((q&&q.querySelector(".stem"))||{}).innerText||"";const lid=((node.closest("[data-lesson]")||{}).dataset||{}).lesson||"";
  let k="";const fromWhy=ruleFor(why);const lr=lid?lessonRules(lid):[];
  if(lr.length)k=lr.find(x=>x===fromWhy)||(fromWhy&&RULES[fromWhy]&&RULES[fromWhy].lesson&&LV((lessonById(RULES[fromWhy].lesson)||{}).level||"B2")<=LV((lessonById(lid)||{}).level||"B2")?fromWhy:"")||lr[0];
  if(!k)k=fromWhy||ruleFor(stem);
  const wrong=node.classList.contains("no")||!!(q&&q.querySelector("button.wrong"));
  if(wrong&&q&&q.parentElement){const el=q.parentElement;const L=XP.miss.get(el)||[];const right=(q.querySelector("button.right")||{}).innerText||"";
    if(stem)L.push({stem:stem.slice(0,160),right:right.replace(/^\d\s*/,"").slice(0,120),why:why.slice(0,200),k});XP.miss.set(el,L)}
  const bar=document.createElement("div");bar.className="row wrap xp-bar";bar.innerHTML=(k?xpBtn(k):"")+(SAMPLE?`<button class="sm ghost" data-act="askWhy">${ic("chat")} Frag nach</button>`:"");
  if(bar.innerHTML){if(q)q.classList.add("xp-ctx");node.after(bar)}};
