fspModel=function(c){const w=c.sex==="w"||/^Frau/.test(c.name);return `Anamnese: ${c.age}-jährige${w?" Patientin":"r Patient"}, ${c.job}. Vorstellung wegen: ${c.cc}.\nVorerkrankungen: ${c.pmh}.\nMedikation: ${c.meds}.\nAllergien: ${c.all}.\nSozial- und Noxenanamnese: ${c.soc}.\nFamilienanamnese: ${c.fam||"unauffällig"}.\nVerdachtsdiagnose / DD: ${c.dx}.\nProcedere: ${c.plan}.`};
