labSatz=function(box){let i=0;const draw=()=>{const s=SATZ2[i%SATZ2.length];const toks=shuffle(s.c.map((w,k)=>({w,k})));let line=[];
  box.innerHTML=`<div class="stack s"><div class="eyebrow">Satz ${i%SATZ2.length+1} / ${SATZ2.length} <span class="en">tap the pieces in order</span></div><div class="gr-line sb-line"></div><div class="gr-pool sb-pool"></div><div class="row wrap"><button class="sm ghost sb-undo">${ic("back")} Zurück</button><button class="primary sb-chk">Prüfen</button><button class="sm sb-next">Nächster</button></div><div class="sb-why"></div><p class="muted ui" style="font-size:.85rem">Hauptsatz: <b>ein</b> Element vor dem Verb (das Vorfeld – oft gibt es mehrere richtige Möglichkeiten), Verb an Position 2, zweiter Verbteil ans Ende. Nebensatz (dass/weil/wenn): Verb ganz ans Ende. Großbuchstaben am Satzanfang setzt die App selbst.</p></div>`;
  const L=$(".sb-line",box),P=$(".sb-pool",box);const paint=()=>{L.innerHTML=line.map(t=>`<button class="gr-tok on" data-k="${t.k}">${esc(t.w)}</button>`).join("")||'<span class="muted ui">…</span>';P.innerHTML=toks.filter(t=>!line.includes(t)).map(t=>`<button class="gr-tok" data-k="${t.k}">${esc(t.w)}</button>`).join("");$$(".gr-tok",P).forEach(b=>b.onclick=()=>{line.push(toks.find(t=>t.k===+b.dataset.k));paint()});$$(".gr-tok",L).forEach(b=>b.onclick=()=>{line=line.filter(t=>t.k!==+b.dataset.k);paint()})};paint();
  $(".sb-undo",box).onclick=()=>{line.pop();paint()};$(".sb-next",box).onclick=()=>{i++;draw()};
  $(".sb-chk",box).onclick=()=>{if(line.length<s.c.length)return toast("Erst alle Teile verwenden");let got=line.map(t=>t.w).join(" ").replace(/\s+([.,!?])/g,"$1");got=got[0].toUpperCase()+got.slice(1);
    const ok=[s.a].concat(s.alt).some(x=>normT(x)===normT(got))||(typeof v2Same==="function"&&v2Same(s.a,got));fb(ok);
    const fields=`<div class="dg-row" style="flex-wrap:wrap">${s.f.map(([t,l],k)=>`<span class="dg ${/Verb/.test(l)?"dg-verb":/Vorfeld/.test(l)?"dg-p1":/Ende/.test(l)?"dg-end":"dg-rest"}">${esc(t)}<small>${esc(l)}</small></span>`).join("")}</div>`;
    const ws=line.map(t=>t.w.toLowerCase());const fin=typeof tVForms==="function"?tVForms():new Set();const vi=ws.findIndex(w=>fin.has(w.split(" ")[0])&&!/^ge/.test(w));
    const hint=ok?"":vi===-1?"Wo ist das konjugierte Verb?":/^(wenn|weil|dass|ob)$/.test(ws[0])&&ws.indexOf(",")>-1&&ws.indexOf(",")-1!==vi?"Im Nebensatz steht das Verb direkt vor dem Komma – ganz am Ende des Nebensatzes.":vi>1&&!/^(wenn|weil|dass|ob)$/.test(ws[0])?"Vor dem Verb darf nur EIN Satzglied stehen (Position 2).":"Fast – vergleiche die Felder unten.";
    $(".sb-why",box).innerHTML=`<div class="verdict ${ok?"ok":"no"}" data-noxp="1"><b>${ok?"Richtig.":"Noch nicht."}</b> ${esc(hint)} ${ok&&normT(got)!==normT(s.a)?"Andere Stellung, auch richtig. Die Musterlösung:":"So ist der Satz gebaut:"}${fields}<div class="row" style="margin-top:.4rem"><button class="sm ghost" data-say="${esc(s.a)}">${ic("vol")}</button>${typeof xpBtn==="function"?xpBtn(s.r):""}</div></div>`;logDay("drill")}};draw()};

