(function(){const _dr=dictationRunner;dictationRunner=function(el,lines,o){if(hasDeVoice()||!lines||!lines.length)return _dr(el,lines,o);o=o||{};let i=0,score=0;
  const draw=()=>{if(i>=lines.length){const pct=Math.round(100*score/lines.length);el.innerHTML=`<div class="celebrate fade-in"><div class="eyebrow">Gedächtnis-Diktat</div><h2>${pct} %</h2><button class="primary dm-ok">Weiter</button></div>`;$(".dm-ok",el).onclick=()=>{if(o.onDone)o.onDone(pct)};logDay("dict");return}
    const L=lines[i];el.innerHTML=`<div class="stack s"><div class="tch-merke"><b>Keine deutsche Stimme auf diesem Gerät.</b> Statt Hören: Lies den Satz, er verschwindet nach ein paar Sekunden – dann schreib ihn aus dem Gedächtnis.</div><div class="eyebrow">Satz ${i+1} / ${lines.length}</div><div class="card dm-s" style="font-size:1.15rem;min-height:3rem">${esc(L.de)}</div><textarea class="dm-in" rows="2" placeholder="Aus dem Gedächtnis …" disabled></textarea><div class="row"><button class="primary dm-chk" disabled>Prüfen</button><button class="sm ghost dm-again">Nochmal zeigen</button></div><div class="dm-out"></div></div>`;
    const sEl=$(".dm-s",el),inp=$(".dm-in",el),chk=$(".dm-chk",el);const hide=()=>{sEl.innerHTML='<span class="muted ui">… jetzt schreiben</span>';inp.disabled=false;chk.disabled=false;inp.focus()};let t=setTimeout(hide,Math.max(2500,L.de.length*90));
    $(".dm-again",el).onclick=()=>{clearTimeout(t);sEl.textContent=L.de;t=setTimeout(hide,2500)};
    chk.onclick=()=>{const s=typeof similarity==="function"?similarity(normT(inp.value),normT(L.de)):(normT(inp.value)===normT(L.de)?1:0);if(s>=.9)score++;$(".dm-out",el).innerHTML=`<div class="verdict ${s>=.9?"ok":"no"}" data-noxp="1">${typeof wordDiff==="function"?wordDiff(inp.value,L.de):esc(L.de)}<div class="row" style="margin-top:.5rem"><button class="primary dm-nx">Weiter</button></div></div>`;$(".dm-nx",el).onclick=()=>{i++;draw()};chk.disabled=true}};draw()}})();

