function planFit(){const ex=[["goethe","Goethe B2",32],["fsp","FSP",40]].map(([k,n,endW])=>{const c=typeof examCountdown==="function"?examCountdown(k):null;return c&&c.days>0?{k,n,endW,weeks:Math.floor(c.days/7)}:null}).filter(Boolean).sort((a,b)=>a.weeks-b.weeks)[0];
  if(!ex)return null;const w=weekNumber();const need=ex.endW-w;if(need<=ex.weeks)return null;const target=Math.max(w+1,Math.min(ex.endW,ex.endW-ex.weeks));return {ex,target,need}}
ACT.planFit=()=>{const f=planFit();if(!f)return;const keepDay=weekDay();S.startDate=addDays(todayKey(),-((f.target-1)*7+keepDay-1));S.today=null;logEvent("plan","Plan vorgezogen auf Woche "+f.target+" ("+f.ex.n+")");saveSoon();toast("Plan ab Woche "+f.target);go("home")};
(function(){const _wh=wegHTML;wegHTML=function(){let h=_wh();const f=planFit();if(f)h=h.replace('<div class="lvbars">',`<div class="tch-merke" style="font-size:.9rem"><b>${esc(f.ex.n)} in ${f.ex.weeks} Wochen</b> – der Plan bräuchte bis dahin noch ${f.need}. Vorziehen auf Woche ${f.target}? Die übersprungenen Lektionen bleiben unter Lernen erreichbar.<div class="row" style="margin-top:.4rem"><button class="sm primary" data-act="planFit">Plan vorziehen</button></div></div><div class="lvbars">`);return h}})();
