// ================= 11.4 — design & usability fixes from the round-2 UX review (05/11/2026) =================
// 1 placement no longer back-dates the plan (week offset instead) · 2 history: Back moves between tabs/lessons ·
// 3 Classic look by default · 4 skipped steps aren't counted · 5 Heute: steps right under the hero · 6 lesson page
// without library chrome, Klinik list in week order · 7 Üben "Für dich" row · 8 small fixes (minutes, welcome text,
// toasts, map list on phones, Stufenprüfung label, Behalten hint)

// ---- 1. plan position = real days + an offset in weeks (set by placement or "Plan vorziehen")
(function(){if(S.placed&&S.weekOffset==null){const logDays=Object.keys(S.log||{}).sort();const real=[logDays[0],S.placed].filter(Boolean).sort()[0]||todayKey();
    if(real>S.startDate){const wasWeek=weekNumber();S.startDate=real;S.weekOffset=Math.max(0,wasWeek-Math.ceil(dayNumber()/7));saveSoon()}else S.weekOffset=0}})();
weekNumber=()=>clamp(Math.ceil(dayNumber()/7)+(S.weekOffset||0),1,WEEKS.length);
function setPlanWeek(w){S.weekOffset=Math.max(0,w-Math.ceil(dayNumber()/7));S.today=null;saveSoon()}
// placement and plan-fit now move the offset, not the start date
(function(){const P=typeof PLACE!=="undefined"?PLACE:null;if(!P)return;placeWire=function(root,done){let lv=S.placement||"",mn=S.minutes;const go2=$(".place-go",root);
  $$(".place-o",root).forEach(b=>b.onclick=()=>{lv=b.dataset.l;$$(".place-o",root).forEach(x=>x.classList.toggle("on",x===b));go2.disabled=false});
  $$(".place-min button",root).forEach(b=>b.onclick=()=>{mn=+b.dataset.n;$$(".place-min button",root).forEach(x=>x.classList.toggle("on",x===b))});
  const x=$(".place-x",root);if(x)x.onclick=()=>done&&done(false);
  go2.onclick=()=>{const p=P.find(q=>q[0]===lv);if(!p)return;const prev=S.placement;S.placement=lv;S.wdt=null;S.placed=S.placed||todayKey();S.minutes=mn;setPlanWeek(prev===lv?Math.max(p[3],weekNumber()):p[3]);if(lv==="C1"&&S.focus!=="pruefung")S.focus="pruefung";S.today=null;
    logEvent("plan","Einstufung "+lv+" · "+mn+" Min./Tag · ab Woche "+weekNumber());saveSoon();toast("Plan ab Woche "+weekNumber()+" · "+lv);if(done)done(true)}}})();
if(typeof ACT.planFit==="function")ACT.planFit=()=>{const f=planFit();if(!f)return;setPlanWeek(f.target);logEvent("plan","Plan vorgezogen auf Woche "+f.target+" ("+f.ex.n+")");toast("Plan ab Woche "+f.target);go("home")};
// level shown honestly next to a self-placement: levels up to the placement count as "selbst eingestuft"
(function(){const _le=levelEstimate;levelEstimate=function(){const e=_le();const P=S.placement;if(!P)return e;const p=LV(P);if(p>LV(e.reached==="A0"?"A1":e.reached)||e.reached==="A0"){const nx=LEVELS[Math.min(4,p+1)];return Object.assign({},e,{stufe:P,reached:P,next:nx,pct:Math.round(100*((e.prog[nx]||{p:0}).p||0)),self:true})}return e}})();

// ---- 2. Back/forward move through tabs and lesson pages (overlays keep their own guard in c_fix)
(function(){let popping=false;const _go=go;go=function(tab,arg){const r=_go(tab,arg);if(!popping){try{const st={tab:typeof tab==="string"?tab:"home",arg:arg||null};const cur=history.state||{};if(cur.tab!==st.tab||cur.arg!==st.arg||cur.mf)history.pushState(st,"","#"+st.tab+(st.arg?"/"+encodeURIComponent(st.arg):""))}catch(e){}}return r};
  try{if(!history.state||!history.state.tab)history.replaceState({tab:"home",arg:null},"",location.hash||"#home")}catch(e){}
  addEventListener("popstate",e=>{const st=e.state||{};const fo=$("#focus"),sh=$("#sheet");if((fo&&!fo.hidden)||(sh&&!sh.hidden)||st.mf)return;if(st.tab){popping=true;try{go(st.tab,st.arg||undefined)}finally{popping=false}}});
  addEventListener("hashchange",()=>{const h=location.hash.replace(/^#/,"");const [t,a]=h.split("/");if(/^(home|learn|practice|me)$/.test(t)&&!(history.state&&history.state.tab===t&&(history.state.arg||null)===(a?decodeURIComponent(a):null))){popping=true;try{go(t,a?decodeURIComponent(a):undefined)}finally{popping=false}}})})();

