  const ring=m.querySelector(".ring text");if(ring&&/\d+\s*\/\s*\d+/.test(ring.textContent))ring.textContent=done+"/"+T.steps.length;
  const steps=m.querySelector(".steps");const hero=m.querySelector(".hero");if(steps&&hero){const card=steps.closest(".card")||steps;if(hero.nextElementSibling!==card)hero.after(card)}
