let FUND=null;
async function fundIndex(){if(FUND)return FUND;const D=await bibLoad();FUND=[];const seen=new Set();D.books.forEach(b=>b.ch.forEach(c=>c.p.forEach(p=>{if(b.verse)return;(p.match(/[^.!?]+[.!?]+/g)||[]).forEach(s=>{s=s.trim();if(s.length>=25&&s.length<=200&&!seen.has(s)){seen.add(s);FUND.push([s,b.t,b.a,b.lv])}})})));return FUND}
