function pkPayCost(p){p=p||P();const peak=Math.max(p.debtPeak||0,p.debt||0);return Math.min(40,10+5*Math.max(0,peak-(p.debt||0)))}
ACT.pkPay=()=>{const p=P();const n=pkPayCost(p);const q=(typeof buildQueue==="function"?buildQueue():[]).slice(0,n);
  const settle=()=>{p.debt=Math.max(0,p.debt-1);p.paid++;if(!p.debt)p.debtPeak=0;saveSoon();SND.fx("bell");toast(p.debt?`Ein Schuldschein verbrannt. Noch ${p.debt} · der nächste kostet ${pkPayCost(p)} Karten.`:"Alle Schuldscheine verbrannt. Vorerst.",3800)};
  if(!q.length){settle();rerender();return}const box=Focus.open({title:"Bußrunde",sub:`${q.length} Karten · ein Schuldschein`});
  cardRunner(box,q,{standalone:true,onDone:()=>{settle();setTimeout(()=>{if(Focus.isOpen())Focus.close(true);go("pakt")},600)}})};
// ---------------------------------------------------------------- 4. pocket rounds (shift days: 4 × 5 minutes)
const POCKET=[["cards","10 Karten","Wiederholen","pocketCards"],["omen","Das Omen","ein Sprichwort","pocketOmen"],["shadow","3 Sätze nachsprechen","Shadowing","pocketShadow"],["palace","Ein Palastzimmer","der · die · das","pocketPalace"]];
function pocketS(){const t=todayKey();if(!S.pocket||S.pocket.date!==t)S.pocket={date:t,done:{}};return S.pocket}
function pocketDone(k){const P0=pocketS();if(P0.done[k])return;P0.done[k]=1;logDay("pocket");saveSoon();const n=Object.keys(P0.done).length;
  if(n>=3&&!P0.counted){P0.counted=1;logDay("session");try{pkOnSession()}catch(e){}toast(`Taschenrunde ${n}/4 · der Tag zählt. Die Kerze brennt.`,3600)}else toast(`Taschenrunde ${n}/4`,2200);if(R.tab==="home"&&!Focus.isOpen())rerender()}
function pocketHTML(force){if(!force&&(!isShift()||S.shiftFull===todayKey()))return "";const P0=pocketS();const n=Object.keys(P0.done).length;
  return `<div class="card orn stack s pocket"><div class="row between"><div class="eyebrow">Taschenrunden</div><span class="chip">${n}/4</span></div>
   <p class="ui muted" style="font-size:.88rem;margin:0">Dienst: 4 × 5 Minuten – drei reichen. <span class="en">three of four count as today</span></p>
   <div class="pocket-grid">${POCKET.map(([k,t,s,a])=>`<button class="${P0.done[k]?"done":""}" data-act="${a}"><b>${P0.done[k]?"✓ ":""}${t}</b><small>${s}</small></button>`).join("")}</div></div>`}
ACT.pocketCards=()=>{const q=buildQueue().slice(0,10);if(!q.length){pocketDone("cards");return toast("Keine Karten fällig. Gezählt.")}const box=Focus.open({title:"Taschenrunde",sub:"10 Karten"});cardRunner(box,q,{standalone:true,onDone:()=>{pocketDone("cards");setTimeout(()=>{if(Focus.isOpen())Focus.close(true)},500)}})};
ACT.pocketOmen=()=>{const box=Focus.open({title:"Taschenrunde",sub:"Das Omen des Tages"});box.innerHTML=`<div style="max-width:640px;margin:0 auto">${typeof omenHTML==="function"?omenHTML():""}</div>`;const mo=new MutationObserver(()=>{if(box.querySelector(".omen-back,.verdict,.omen.sealed .omen-de, .omen-solved")){mo.disconnect();setTimeout(()=>pocketDone("omen"),400)}});mo.observe(box,{childList:true,subtree:true,attributes:true});Focus.foot(`<button class="sm ghost" data-act="pocketOmenDone">Gelesen und gelöst</button>`)};
ACT.pocketOmenDone=()=>{pocketDone("omen");if(Focus.isOpen())Focus.close(true)};
ACT.pocketShadow=()=>{let L=(shadowLines(null)||[]).slice(0,3);if(!L.length){const ks=Object.keys(S.cards).filter(k=>!k.startsWith("p:")).slice(-40).map(k=>card(k)).filter(c=>c&&c.ex).slice(0,3);L=ks.map(c=>({de:c.ex,en:c.exEn||""}))}if(!L.length)return toast("Noch keine Sätze – lern erst ein paar Karten.");const box=Focus.open({title:"Taschenrunde",sub:"3 Sätze nachsprechen"});shadowRunner(box,L,{onDone:()=>{pocketDone("shadow");setTimeout(()=>{if(Focus.isOpen())Focus.close(true)},700)}})};
ACT.pocketPalace=()=>{S._pocketPal=1;ACT.palace()};
(function(){const mo=new MutationObserver(()=>{if(!S._pocketPal)return;const f=$("#fIn");if(f&&/von \d+/.test((f.querySelector("h2")||{}).textContent||"")&&f.querySelector(".pk-werk,[data-act=\"palace\"],.card")){S._pocketPal=0;pocketDone("palace")}if(!Focus.isOpen())S._pocketPal=0});mo.observe(document.body,{childList:true,subtree:true})})();
