   <div class="rail-kv"><span>Fällig</span><b>${Math.min(due,cap)}${due>cap?` <small>+${due-cap} gestundet</small>`:""}</b><span>Minuten heute</span><b>${minutesOn(todayKey())} / ${effMin()}</b><span>Goethe B2</span><b>${b.cd?"in "+b.cd.days+" Tagen":"kein Termin"}</b><span>Patientenwörter</span><b>${w.sure} / ${w.tot}</b><span>Wochennote</span><b>${z.note?z.note+" · "+NOTE_NAME[z.note]:"nach Woche 1"}</b></div>
