function devId(){let d=null;try{d=localStorage.getItem("mephisto_dev");if(!d){d="d"+Math.random().toString(36).slice(2,9);localStorage.setItem("mephisto_dev",d)}}catch(e){d="d0"}return d}
(function(){const _sn=saveNow;saveNow=function(){try{const d=todayKey(),L=S.log&&S.log[d];if(L&&L.sec){const me=devId();L.dv=L.dv||{};let others=0;for(const k in L.dv)if(k!==me)others+=+L.dv[k]||0;L.dv[me]=Math.max(L.dv[me]||0,(L.sec||0)-others)}}catch(e){}return _sn.apply(this,arguments)}})();
