// Funktionswörter pack → catalogue
(function(){try{let n=0;(typeof VOC3!=="undefined"?VOC3:[]).forEach(([de,en,ex,exEn,level,theme])=>{const id="w:"+de;if(CATALOG.has(id))return;CATALOG.set(id,{id,de,en,type:"word",ex,exEn,tag:theme,kind:"word",pl:"",info:"",level,syn:"",src:"funktion"});n++});if(n)buildDict()}catch(e){}})();

