    cur[2]=k;const ins=opt[1].map(l=>{const x=l.slice();if(fx.includes("secretFace")&&x[0]==="M")x[4]="secret";return x});if(again)ins.push(["C",cur[1]]);lines.splice(i+1,0,...ins);
